#[tauri::command]
pub fn native_window_command(app: tauri::AppHandle, command: String) -> Result<String, String> {
    let window = app
        .get_webview_window("main")
        .ok_or_else(|| "main window is unavailable".to_string())?;
    match command.as_str() {
        "minimize" => {
            window
                .minimize()
                .map_err(|error| format!("minimize failed: {error}"))?;
            Ok("minimized".to_string())
        }
        "maximize" => {
            let maximized = window
                .is_maximized()
                .map_err(|error| format!("maximize state check failed: {error}"))?;
            if maximized {
                window
                    .unmaximize()
                    .map_err(|error| format!("restore failed: {error}"))?;
                Ok("restored".to_string())
            } else {
                window
                    .maximize()
                    .map_err(|error| format!("maximize failed: {error}"))?;
                Ok("maximized".to_string())
            }
        }
        "close" => {
            window
                .close()
                .map_err(|error| format!("close failed: {error}"))?;
            Ok("closed".to_string())
        }
        _ => Err(format!("unsupported window command: {command}")),
    }
}

