fn hermes_home_for_preflight() -> PathBuf {
    let hermes_home = env::var("HERMES_HOME").unwrap_or_default();
    let hermes_home = hermes_home.trim();
    if !hermes_home.is_empty() {
        return PathBuf::from(hermes_home);
    }
    let home = env::var("HOME").unwrap_or_else(|_| "/home/rage".to_string());
    PathBuf::from(home).join(".hermes")
}

fn hermes_log_write_preflight(target: &UnlockedAgentPromptTarget) -> Result<(), String> {
    if target.runtime != "hermes-chat" {
        return Ok(());
    }
    let hermes_home = hermes_home_for_preflight();
    let log_dir = hermes_home.join("logs");
    fs::create_dir_all(&log_dir).map_err(|error| {
        format!(
            "Hermes log path is not writable for this Gravity Omega process: {} ({error}). Launch Gravity Omega outside a read-only wrapper, or set HERMES_HOME to a writable Hermes profile before running Hermes.",
            log_dir.display()
        )
    })?;
    let probe_path = log_dir.join(".gravity-omega-write-probe");
    OpenOptions::new()
        .create(true)
        .append(true)
        .open(&probe_path)
        .and_then(|mut file| {
            writeln!(
                file,
                "gravity-omega hermes log preflight {}",
                now_ms().unwrap_or_default()
            )
        })
        .map_err(|error| {
            format!(
                "Hermes log path is not writable for this Gravity Omega process: {} ({error}). Launch Gravity Omega outside a read-only wrapper, or set HERMES_HOME to a writable Hermes profile before running Hermes.",
                log_dir.display()
            )
        })?;
    let _ = fs::remove_file(probe_path);
    Ok(())
}

