const TOOLBAR_CONTRACT: &str = include_str!("../../web/contracts/toolbar.v0.json");
const SANDBOX_CONTRACT: &str = include_str!("../../web/contracts/sandbox.v0.json");

fn probe_binary(name: &'static str, command: &'static str, args: &[&str]) -> BinaryProbe {
    match Command::new(command).args(args).output() {
        Ok(output) => {
            let combined = if output.stdout.is_empty() {
                String::from_utf8_lossy(&output.stderr).trim().to_string()
            } else {
                String::from_utf8_lossy(&output.stdout).trim().to_string()
            };

            BinaryProbe {
                name,
                command,
                found: output.status.success(),
                version: combined,
                error: if output.status.success() {
                    None
                } else {
                    Some(format!("exited with status {}", output.status))
                },
            }
        }
        Err(error) => BinaryProbe {
            name,
            command,
            found: false,
            version: String::new(),
            error: Some(error.to_string()),
        },
    }
}

fn now_ms() -> Result<u64, String> {
    let duration = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|error| format!("system clock is before UNIX_EPOCH: {error}"))?;
    Ok(duration.as_millis() as u64)
}

fn slug(value: &str) -> String {
    value
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || ch == '-' || ch == '_' {
                ch
            } else {
                '-'
            }
        })
        .collect()
}

fn slug_limit(value: &str, max_len: usize) -> String {
    let value = slug(value).chars().take(max_len).collect::<String>();
    if value.is_empty() {
        "item".to_string()
    } else {
        value
    }
}

fn state_root() -> Result<PathBuf, String> {
    let base = match env::var_os("XDG_STATE_HOME") {
        Some(value) if !value.is_empty() => PathBuf::from(value),
        _ => {
            let home = env::var_os("HOME").ok_or("HOME is not set; cannot locate XDG state")?;
            PathBuf::from(home).join(".local").join("state")
        }
    };

    Ok(base.join("gravity-omega-native"))
}

