fn agent_event_log_path(task_run_id: &str) -> Result<PathBuf, String> {
    if !is_safe_id(task_run_id) {
        return Err("task run id contains unsupported characters".to_string());
    }

    Ok(agent_events_dir()?.join(format!("{task_run_id}.jsonl")))
}

fn capability_for_mode(mode: &str) -> &'static str {
    match mode {
        "codex_review" => "safe",
        "codex_exec" | "hermes_chat" | "joint_ci" | "joint_review" => "gated",
        _ => "gated",
    }
}

fn is_safe_id(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 240
        && value
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || ch == '-' || ch == '_')
}

fn read_task_run_record(id: &str) -> Result<Option<OmegaTaskRunRecord>, String> {
    if !is_safe_id(id) {
        return Err("task run id contains unsupported characters".to_string());
    }

    let path = task_runs_dir()?.join(format!("{id}.json"));
    if !path.exists() {
        return Ok(None);
    }

    let content = fs::read_to_string(&path)
        .map_err(|error| format!("failed to read task-run record {}: {error}", path.display()))?;
    serde_json::from_str::<OmegaTaskRunRecord>(&content)
        .map(Some)
        .map_err(|error| format!("failed to parse task-run record {}: {error}", path.display()))
}

