fn local_mcp_health_record_ready(record: &LocalMcpHealthRecord) -> bool {
    record.supported_subsystem
        && record.health_preflight_required
        && record.preflight_found
        && record.preflight_ready
        && record.configured_expected
        && record.capability_manifest_required
        && record.approval_required_for_calls
        && record.audit_required
        && !record.live_probe_enabled
        && !record.live_call_enabled
        && !record.writes_allowed
        && !record.execution_enabled
}

fn latest_ready_local_mcp_health_record_for_subsystem(
    subsystem: &str,
) -> Result<Option<LocalMcpHealthRecord>, String> {
    Ok(list_local_mcp_health_records()?
        .into_iter()
        .find(|record| record.subsystem == subsystem && local_mcp_health_record_ready(record)))
}

fn requested_or_latest_local_mcp_health_record(
    subsystem: &str,
    requested_ids: &[String],
) -> Result<Option<LocalMcpHealthRecord>, String> {
    if requested_ids.is_empty() {
        return latest_ready_local_mcp_health_record_for_subsystem(subsystem);
    }

    for id in requested_ids {
        if let Some(record) = read_local_mcp_health_record(id)? {
            if record.subsystem == subsystem {
                return Ok(Some(record));
            }
        }
    }

    Ok(None)
}

