fn local_mcp_capability_discovery_policy_ready(
    record: &LocalMcpCapabilityDiscoveryPolicyRecord,
) -> bool {
    record.policy_recorded
        && record.read_only_policy
        && record.lane_count == 3
        && record.discovery_ready_count == record.lane_count
        && record.omega_brain_policy_recorded
        && record.sswp_policy_recorded
        && record.steno_policy_recorded
        && record.health_records_found
        && record.health_records_ready
        && !record.live_probe_enabled
        && !record.capability_discovery_enabled
        && !record.live_call_enabled
        && !record.capture_enabled
        && !record.export_enabled
        && !record.memory_write_enabled
        && !record.desktop_control_enabled
        && !record.terminal_enabled
        && !record.process_spawn_enabled
        && !record.file_write_enabled
        && !record.patch_apply_enabled
        && !record.writes_allowed
        && !record.execution_enabled
}

