fn default_workspace_preview_paths() -> Vec<String> {
    vec![
        "README.md".to_string(),
        "package.json".to_string(),
        "rebuild/gravity-omega-tauri/src-tauri/Cargo.toml".to_string(),
        "rebuild/gravity-omega-tauri/web/src/main.js".to_string(),
    ]
}

fn normalize_workspace_preview_path(value: &str) -> Option<String> {
    let candidate = value.trim().replace('\\', "/");
    if candidate.is_empty()
        || candidate.len() > 160
        || candidate.starts_with('/')
        || candidate.chars().any(|ch| ch.is_control())
        || Path::new(&candidate).is_absolute()
    {
        return None;
    }

    for segment in candidate.split('/') {
        if segment.is_empty() || segment == "." || segment == ".." {
            return None;
        }
    }

    Some(candidate)
}

fn workspace_preview_path_ignored(path: &str, ignore_patterns: &[String]) -> bool {
    let normalized = path.trim_matches('/');
    ignore_patterns.iter().any(|pattern| {
        let pattern = pattern.trim().trim_matches('/');
        !pattern.is_empty()
            && (normalized == pattern
                || normalized.starts_with(&format!("{pattern}/"))
                || normalized.ends_with(&format!("/{pattern}"))
                || normalized.contains(&format!("/{pattern}/")))
    })
}

fn sanitize_workspace_preview_paths(
    requested_paths: Vec<String>,
    ignore_patterns: &[String],
) -> (Vec<String>, Vec<String>, usize) {
    let source_paths = if requested_paths.is_empty() {
        default_workspace_preview_paths()
    } else {
        requested_paths
    };
    let mut sanitized = Vec::new();
    let mut preview_paths = Vec::new();
    let mut dropped_count = 0;

    for candidate in source_paths {
        let Some(path) = normalize_workspace_preview_path(&candidate) else {
            dropped_count += 1;
            continue;
        };

        if !sanitized.contains(&path) && sanitized.len() < 12 {
            sanitized.push(path.clone());
        }

        if workspace_preview_path_ignored(&path, ignore_patterns) {
            dropped_count += 1;
            continue;
        }

        if !preview_paths.contains(&path) && preview_paths.len() < 12 {
            preview_paths.push(path);
        }
    }

    if preview_paths.is_empty() {
        for fallback in default_workspace_preview_paths() {
            if !workspace_preview_path_ignored(&fallback, ignore_patterns)
                && !preview_paths.contains(&fallback)
            {
                preview_paths.push(fallback);
            }
        }
    }

    (sanitized, preview_paths, dropped_count)
}

