fn editor_tab_title(relative_path: &str, preferred: Option<String>) -> String {
    let preferred = preferred
        .unwrap_or_default()
        .trim()
        .chars()
        .take(80)
        .collect::<String>();
    if !preferred.is_empty() {
        return preferred;
    }

    relative_path
        .rsplit('/')
        .next()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or(relative_path)
        .chars()
        .take(80)
        .collect()
}

