fn normalize_edit_preflight_action(value: &str) -> String {
    match value.trim().to_ascii_lowercase().as_str() {
        "edit" | "edit_intent" | "modify" => "edit".to_string(),
        "save" | "write" => "save".to_string(),
        "save_as" | "save-as" => "save_as".to_string(),
        _ => "unsupported".to_string(),
    }
}

