#[derive(Debug, Default)]
struct WorkspaceTreeCollection {
    entries: Vec<WorkspaceTreeEntry>,
    skipped_ignored_count: usize,
    skipped_symlink_count: usize,
    read_errors: Vec<String>,
    truncated: bool,
}

fn path_to_workspace_relative_string(path: &Path) -> String {
    path.iter()
        .map(|segment| segment.to_string_lossy())
        .collect::<Vec<_>>()
        .join("/")
}

fn modified_time_ms(metadata: &fs::Metadata) -> Option<u64> {
    metadata
        .modified()
        .ok()
        .and_then(|modified| modified.duration_since(UNIX_EPOCH).ok())
        .map(|duration| duration.as_millis() as u64)
}

fn collect_workspace_tree_metadata(
    root: &Path,
    ignore_patterns: &[String],
    max_depth: usize,
    max_entries: usize,
) -> WorkspaceTreeCollection {
    let mut collection = WorkspaceTreeCollection::default();
    collect_workspace_tree_dir(
        root,
        Path::new(""),
        0,
        ignore_patterns,
        max_depth,
        max_entries,
        &mut collection,
    );
    collection
}

fn collect_workspace_tree_dir(
    root: &Path,
    relative_dir: &Path,
    depth: usize,
    ignore_patterns: &[String],
    max_depth: usize,
    max_entries: usize,
    collection: &mut WorkspaceTreeCollection,
) {
    if collection.entries.len() >= max_entries {
        collection.truncated = true;
        return;
    }

    let dir_path = if relative_dir.as_os_str().is_empty() {
        root.to_path_buf()
    } else {
        root.join(relative_dir)
    };
    let read_dir = match fs::read_dir(&dir_path) {
        Ok(read_dir) => read_dir,
        Err(error) => {
            collection
                .read_errors
                .push(format!("{}: {error}", dir_path.display()));
            return;
        }
    };

    let mut children = Vec::new();
    for entry in read_dir {
        match entry {
            Ok(entry) => children.push(entry.path()),
            Err(error) => collection.read_errors.push(format!("read_dir entry: {error}")),
        }
    }
    children.sort_by(|left, right| {
        left.file_name()
            .and_then(|name| name.to_str())
            .unwrap_or_default()
            .cmp(
                right.file_name()
                    .and_then(|name| name.to_str())
                    .unwrap_or_default(),
            )
    });

    for child_path in children {
        if collection.entries.len() >= max_entries {
            collection.truncated = true;
            return;
        }

        let Some(name) = child_path
            .file_name()
            .and_then(|value| value.to_str())
            .map(|value| value.to_string())
        else {
            collection.read_errors.push(format!(
                "{}: unsupported non-utf8 file name",
                child_path.display()
            ));
            continue;
        };
        let relative_path = if relative_dir.as_os_str().is_empty() {
            PathBuf::from(&name)
        } else {
            relative_dir.join(&name)
        };
        let relative_path_string = path_to_workspace_relative_string(&relative_path);
        if workspace_preview_path_ignored(&relative_path_string, ignore_patterns) {
            collection.skipped_ignored_count += 1;
            continue;
        }

        let metadata = match fs::symlink_metadata(&child_path) {
            Ok(metadata) => metadata,
            Err(error) => {
                collection
                    .read_errors
                    .push(format!("{}: {error}", child_path.display()));
                continue;
            }
        };
        let file_type = metadata.file_type();
        let symlink = file_type.is_symlink();
        let kind = if symlink {
            "symlink"
        } else if file_type.is_dir() {
            "directory"
        } else if file_type.is_file() {
            "file"
        } else {
            "other"
        }
        .to_string();

        collection.entries.push(WorkspaceTreeEntry {
            relative_path: relative_path_string,
            name,
            kind: kind.clone(),
            depth,
            size_bytes: metadata.len(),
            modified_ms: modified_time_ms(&metadata),
            readonly: metadata.permissions().readonly(),
            symlink,
        });

        if symlink {
            collection.skipped_symlink_count += 1;
            continue;
        }

        if kind == "directory" && depth < max_depth {
            collect_workspace_tree_dir(
                root,
                &relative_path,
                depth + 1,
                ignore_patterns,
                max_depth,
                max_entries,
                collection,
            );
        }
    }
}

fn read_runner_adapter_record(id: &str) -> Result<Option<RunnerAdapterRecord>, String> {
    if !is_safe_id(id) {
        return Err("runner adapter id contains unsupported characters".to_string());
    }

    let path = runner_adapters_dir()?.join(format!("{id}.json"));
    if !path.exists() {
        return Ok(None);
    }

    let content = fs::read_to_string(&path)
        .map_err(|error| format!("failed to read runner adapter {}: {error}", path.display()))?;
    serde_json::from_str::<RunnerAdapterRecord>(&content)
        .map(Some)
        .map_err(|error| format!("failed to parse runner adapter {}: {error}", path.display()))
}

