fn read_process_control_policy_records_for_lifecycle(
    process_lifecycle_id: &str,
) -> Result<Vec<ProcessControlPolicyRecord>, String> {
    if !is_safe_id(process_lifecycle_id) {
        return Err("process lifecycle id contains unsupported characters".to_string());
    }

    let dir = process_control_policies_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read process-control-policies directory {}: {error}",
            dir.display()
        )
    })? {
        let entry =
            entry.map_err(|error| format!("failed to read process control policy entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<ProcessControlPolicyRecord>(&content) {
            if record.process_lifecycle_id == process_lifecycle_id {
                records.push(record);
            }
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    Ok(records)
}

