fn command_preview(argv: &[String]) -> String {
    argv.join(" ")
}

fn prefix_matches(argv: &[String], prefix: &[String]) -> bool {
    argv.len() >= prefix.len()
        && argv
            .iter()
            .zip(prefix.iter())
            .all(|(arg, expected)| arg == expected)
}

fn contains_blocked_pattern(argv: &[String], blocked_patterns: &[String]) -> Option<String> {
    argv.iter().find_map(|arg| {
        let lower = arg.to_ascii_lowercase();
        blocked_patterns
            .iter()
            .find(|pattern| lower == pattern.to_ascii_lowercase())
            .cloned()
    })
}

fn write_jsonl_event(path: &PathBuf, event: serde_json::Value) -> Result<(), String> {
    let mut file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
        .map_err(|error| format!("failed to open evidence log {}: {error}", path.display()))?;

    writeln!(file, "{event}")
        .map_err(|error| format!("failed to write evidence log {}: {error}", path.display()))
}

