fn release_binary_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("target")
        .join("release")
        .join("gravity-omega-native")
}

fn release_artifact_status() -> ReleaseArtifactStatus {
    let path = release_binary_path();
    let metadata = fs::metadata(&path).ok();
    let exists = metadata.is_some();
    let is_file = metadata.as_ref().map(|value| value.is_file()).unwrap_or(false);
    let size_bytes = metadata.as_ref().map(|value| value.len()).unwrap_or(0);
    let modified_ms = metadata
        .and_then(|value| value.modified().ok())
        .and_then(|modified| modified.duration_since(UNIX_EPOCH).ok())
        .map(|duration| duration.as_millis() as u64);
    let artifact_ready = exists && is_file && size_bytes > 0;
    let blockers = if artifact_ready {
        vec![
            "installer/package target is not yet recorded; local release launch is operator-unlocked",
        ]
    } else {
        vec![
            "release binary must be built before packaging can be marked ready",
            "desktop entry, app menu integration, installer/package target, and launch smoke are not yet recorded",
        ]
    };

    ReleaseArtifactStatus {
        binary_name: "gravity-omega-native",
        build_profile: "release",
        path: path.display().to_string(),
        exists,
        is_file,
        size_bytes,
        modified_ms,
        artifact_ready,
        package_bundle_ready: false,
        desktop_launcher_ready: artifact_ready,
        install_enabled: false,
        launch_enabled: artifact_ready,
        read_only: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: artifact_ready,
        desktop_control_enabled: artifact_ready,
        socket_connect_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: artifact_ready,
        blockers,
        next_action: "Launch the release binary now, verify the desktop window, then decide whether to install the launcher into the local app menu.",
    }
}

