#[derive(Debug, Clone)]
struct RuntimeSidecarProcessTarget {
    target_id: &'static str,
    title: &'static str,
    target_family: &'static str,
    expected_pattern: &'static str,
    required_for: &'static str,
    needles: Vec<&'static str>,
    required: bool,
    next_action: &'static str,
}

#[derive(Debug, Clone)]
struct RuntimeProcessLine {
    pid: u32,
    command: String,
}

const RUNTIME_SIDECAR_PROCESS_LIST_TIMEOUT_MS: u64 = 2_500;
const RUNTIME_PROCESS_SNAPSHOT_FRESHNESS_THRESHOLD_MS: u64 = 120_000;

#[derive(Debug)]
struct RuntimeSidecarProcessListCapture {
    command: Vec<String>,
    exit_code: Option<i32>,
    status: String,
    stdout: String,
    stderr_preview: String,
    duration_ms: u64,
    timeout_ms: u64,
    timed_out: bool,
    stdout_pipe_reader_enabled: bool,
    stderr_pipe_reader_enabled: bool,
    timeout_kill_sent: bool,
    wait_after_kill_ms: u64,
    partial_output_captured: bool,
}

