fn compact_process_command_line(command: &str) -> String {
    let compact = command.split_whitespace().collect::<Vec<_>>().join(" ");
    if compact.chars().count() <= 260 {
        return compact;
    }

    let mut shortened = compact.chars().take(260).collect::<String>();
    shortened.push_str("...");
    shortened
}

fn parse_runtime_process_lines(stdout: &str) -> Vec<RuntimeProcessLine> {
    stdout
        .lines()
        .filter_map(|line| {
            let trimmed = line.trim_start();
            if trimmed.is_empty() {
                return None;
            }
            let mut parts = trimmed.splitn(2, char::is_whitespace);
            let pid = parts.next()?.parse::<u32>().ok()?;
            let command = parts.next().unwrap_or("").trim().to_string();
            if command.is_empty() {
                return None;
            }
            Some(RuntimeProcessLine { pid, command })
        })
        .collect()
}

fn spawn_runtime_sidecar_process_pipe_reader<R: Read + Send + 'static>(
    mut reader: R,
) -> std::thread::JoinHandle<Vec<u8>> {
    std::thread::spawn(move || {
        let mut bytes = Vec::new();
        let _ = reader.read_to_end(&mut bytes);
        bytes
    })
}

fn run_runtime_sidecar_process_list_command(timeout_ms: u64) -> RuntimeSidecarProcessListCapture {
    let command = vec![
        "ps".to_string(),
        "-eo".to_string(),
        "pid=,args=".to_string(),
    ];
    let start = Instant::now();
    let mut child = match Command::new("ps")
        .args(["-eo", "pid=,args="])
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
    {
        Ok(child) => child,
        Err(error) => {
            return RuntimeSidecarProcessListCapture {
                command,
                exit_code: None,
                status: "process_list_spawn_failed".to_string(),
                stdout: String::new(),
                stderr_preview: prompt_preview(&error.to_string(), 1200),
                duration_ms: start.elapsed().as_millis() as u64,
                timeout_ms,
                timed_out: false,
                stdout_pipe_reader_enabled: false,
                stderr_pipe_reader_enabled: false,
                timeout_kill_sent: false,
                wait_after_kill_ms: 0,
                partial_output_captured: false,
            };
        }
    };

    let stdout_reader = child
        .stdout
        .take()
        .map(spawn_runtime_sidecar_process_pipe_reader);
    let stderr_reader = child
        .stderr
        .take()
        .map(spawn_runtime_sidecar_process_pipe_reader);
    let stdout_pipe_reader_enabled = stdout_reader.is_some();
    let stderr_pipe_reader_enabled = stderr_reader.is_some();
    let mut timed_out = false;
    let mut timeout_kill_sent = false;
    let mut wait_after_kill_ms = 0;
    let exit_code;

    loop {
        match child.try_wait() {
            Ok(Some(status)) => {
                exit_code = status.code();
                break;
            }
            Ok(None) => {
                if start.elapsed() >= Duration::from_millis(timeout_ms) {
                    timed_out = true;
                    timeout_kill_sent = child.kill().is_ok();
                    let wait_start = Instant::now();
                    let _ = child.wait();
                    wait_after_kill_ms = wait_start.elapsed().as_millis() as u64;
                    exit_code = None;
                    break;
                }
                std::thread::sleep(Duration::from_millis(10));
            }
            Err(_) => {
                exit_code = None;
                break;
            }
        }
    }

    let stdout = stdout_reader
        .and_then(|reader| reader.join().ok())
        .unwrap_or_default();
    let stderr = stderr_reader
        .and_then(|reader| reader.join().ok())
        .unwrap_or_default();
    let stdout = String::from_utf8_lossy(&stdout).to_string();
    let stderr_preview = trim_probe_text(&stderr);
    let partial_output_captured = timed_out && (!stdout.is_empty() || !stderr_preview.is_empty());
    let status = if timed_out {
        "process_list_timed_out"
    } else if exit_code == Some(0) {
        "process_list_succeeded"
    } else {
        "process_list_failed"
    };

    RuntimeSidecarProcessListCapture {
        command,
        exit_code,
        status: status.to_string(),
        stdout,
        stderr_preview,
        duration_ms: start.elapsed().as_millis() as u64,
        timeout_ms,
        timed_out,
        stdout_pipe_reader_enabled,
        stderr_pipe_reader_enabled,
        timeout_kill_sent,
        wait_after_kill_ms,
        partial_output_captured,
    }
}

fn runtime_process_matches(target: &RuntimeSidecarProcessTarget, process: &RuntimeProcessLine) -> bool {
    let command = process.command.to_lowercase();
    target
        .needles
        .iter()
        .all(|needle| command.contains(&needle.to_lowercase()))
}

fn build_runtime_sidecar_target_snapshot(
    target: &RuntimeSidecarProcessTarget,
    processes: &[RuntimeProcessLine],
) -> RuntimeSidecarProcessTargetSnapshot {
    let matches = processes
        .iter()
        .filter(|process| runtime_process_matches(target, process))
        .collect::<Vec<_>>();
    let process_count = matches.len();
    let pids = matches.iter().map(|process| process.pid).collect::<Vec<_>>();
    let mut command_previews = matches
        .iter()
        .map(|process| compact_process_command_line(&process.command))
        .collect::<Vec<_>>();
    command_previews.truncate(5);
    let running = process_count > 0;
    RuntimeSidecarProcessTargetSnapshot {
        target_id: target.target_id.to_string(),
        title: target.title.to_string(),
        target_family: target.target_family.to_string(),
        expected_pattern: target.expected_pattern.to_string(),
        required_for: target.required_for.to_string(),
        process_count,
        running,
        pids,
        command_previews,
        health_status: if running {
            "runtime_process_visible_read_only".to_string()
        } else if target.required {
            "runtime_process_missing_required".to_string()
        } else {
            "runtime_process_optional_missing".to_string()
        },
        next_action: target.next_action.to_string(),
    }
}

fn sum_runtime_process_family(targets: &[RuntimeSidecarProcessTargetSnapshot], family: &str) -> usize {
    targets
        .iter()
        .filter(|target| target.target_family == family)
        .map(|target| target.process_count)
        .sum()
}

#[tauri::command]
pub fn record_runtime_sidecar_process_snapshot(
    request: RuntimeSidecarProcessSnapshotRequest,
) -> Result<RuntimeSidecarProcessSnapshotRecord, String> {
    let timestamp = now_ms()?;
    let requested_by = request
        .requested_by
        .unwrap_or_else(|| "gravity-omega-runtime".to_string())
        .trim()
        .chars()
        .take(120)
        .collect::<String>();
    let requested_by = if requested_by.is_empty() {
        "gravity-omega-runtime".to_string()
    } else {
        requested_by
    };
    let id = format!(
        "runtime-sidecar-process-snapshot-{}-{}",
        timestamp,
        std::process::id()
    );
    let dir = runtime_sidecar_process_snapshots_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create runtime sidecar process snapshot directory {}: {error}",
            dir.display()
        )
    })?;
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let mut blockers = Vec::new();
    let process_list_capture =
        run_runtime_sidecar_process_list_command(RUNTIME_SIDECAR_PROCESS_LIST_TIMEOUT_MS);
    if process_list_capture.status == "process_list_spawn_failed" {
        blockers.push(format!(
            "bounded ps process list failed to spawn: {}",
            process_list_capture.stderr_preview
        ));
    } else if process_list_capture.timed_out {
        blockers.push(format!(
            "bounded ps process list timed out after {}ms",
            process_list_capture.timeout_ms
        ));
    } else if process_list_capture.status != "process_list_succeeded" {
        blockers.push("bounded ps process list returned a non-zero exit status".to_string());
    }
    let processes = parse_runtime_process_lines(&process_list_capture.stdout);
    let targets = runtime_sidecar_process_targets()
        .iter()
        .map(|target| build_runtime_sidecar_target_snapshot(target, &processes))
        .collect::<Vec<_>>();
    for target in &targets {
        if !target.running {
            blockers.push(format!(
                "{} missing expected process pattern {}",
                target.target_id, target.expected_pattern
            ));
        }
    }
    let running_target_count = targets.iter().filter(|target| target.running).count();
    let missing_target_count = targets.len().saturating_sub(running_target_count);
    let process_count = targets.iter().map(|target| target.process_count).sum::<usize>();
    let status =
        if process_list_capture.status == "process_list_succeeded" && missing_target_count == 0 {
            "runtime_sidecar_process_snapshot_recorded_ready"
        } else {
            "runtime_sidecar_process_snapshot_recorded_with_gaps"
        };
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let record = RuntimeSidecarProcessSnapshotRecord {
        id: id.clone(),
        status: status.to_string(),
        requested_by,
        process_list_command: process_list_capture.command,
        process_list_exit_code: process_list_capture.exit_code,
        process_list_status: process_list_capture.status,
        process_list_stdout_size_bytes: process_list_capture.stdout.len(),
        process_list_stderr_preview: process_list_capture.stderr_preview,
        process_list_duration_ms: process_list_capture.duration_ms,
        process_list_timeout_ms: process_list_capture.timeout_ms,
        process_list_timed_out: process_list_capture.timed_out,
        stdout_pipe_reader_enabled: process_list_capture.stdout_pipe_reader_enabled,
        stderr_pipe_reader_enabled: process_list_capture.stderr_pipe_reader_enabled,
        process_list_timeout_kill_sent: process_list_capture.timeout_kill_sent,
        process_list_wait_after_kill_ms: process_list_capture.wait_after_kill_ms,
        process_list_partial_output_captured: process_list_capture.partial_output_captured,
        target_count: targets.len(),
        running_target_count,
        missing_target_count,
        process_count,
        hermes_process_count: sum_runtime_process_family(&targets, "hermes_kimi"),
        sswp_process_count: sum_runtime_process_family(&targets, "sswp"),
        steno_process_count: sum_runtime_process_family(&targets, "steno"),
        omega_brain_process_count: sum_runtime_process_family(&targets, "omega_brain"),
        native_process_count: sum_runtime_process_family(&targets, "native_runtime"),
        codex_process_count: sum_runtime_process_family(&targets, "codex_runtime"),
        targets,
        process_scan_enabled: true,
        bounded_execution_performed: true,
        process_spawn_enabled: true,
        process_control_enabled: false,
        sidecar_launch_enabled: false,
        terminal_execution_enabled: false,
        live_mcp_call_enabled: false,
        config_read_enabled: false,
        socket_connect_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        capture_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        blockers,
        next_step: "Use this read-only runtime process evidence to decide which sidecar lanes can move to deeper health checks; sidecar launch, process control, terminal execution, live MCP calls, writes, captures, exports, and memory writes remain disabled.".to_string(),
    };

    let json = serde_json::to_string_pretty(&record)
        .map_err(|error| format!("failed to serialize runtime sidecar process snapshot: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write runtime sidecar process snapshot {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "runtime_sidecar_process_snapshot_recorded",
            "id": &record.id,
            "status": &record.status,
            "process_list_status": &record.process_list_status,
            "process_list_timeout_ms": record.process_list_timeout_ms,
            "process_list_timed_out": record.process_list_timed_out,
            "stdout_pipe_reader_enabled": record.stdout_pipe_reader_enabled,
            "stderr_pipe_reader_enabled": record.stderr_pipe_reader_enabled,
            "process_list_timeout_kill_sent": record.process_list_timeout_kill_sent,
            "process_list_wait_after_kill_ms": record.process_list_wait_after_kill_ms,
            "process_list_partial_output_captured": record.process_list_partial_output_captured,
            "target_count": record.target_count,
            "running_target_count": record.running_target_count,
            "missing_target_count": record.missing_target_count,
            "process_count": record.process_count,
            "hermes_process_count": record.hermes_process_count,
            "sswp_process_count": record.sswp_process_count,
            "steno_process_count": record.steno_process_count,
            "omega_brain_process_count": record.omega_brain_process_count,
            "native_process_count": record.native_process_count,
            "codex_process_count": record.codex_process_count,
            "process_scan_enabled": true,
            "bounded_execution_performed": true,
            "process_spawn_enabled": true,
            "process_control_enabled": false,
            "sidecar_launch_enabled": false,
            "terminal_execution_enabled": false,
            "live_mcp_call_enabled": false,
            "config_read_enabled": false,
            "socket_connect_enabled": false,
            "file_write_enabled": false,
            "patch_apply_enabled": false,
            "capture_enabled": false,
            "export_enabled": false,
            "memory_write_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;
    Ok(record)
}

#[tauri::command]
pub fn list_runtime_sidecar_process_snapshots(
) -> Result<Vec<RuntimeSidecarProcessSnapshotRecord>, String> {
    let dir = runtime_sidecar_process_snapshots_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read runtime sidecar process snapshots directory {}: {error}",
            dir.display()
        )
    })? {
        let entry = entry.map_err(|error| {
            format!("failed to read runtime sidecar process snapshot entry: {error}")
        })?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }
        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<RuntimeSidecarProcessSnapshotRecord>(&content) {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(40);
    Ok(records)
}

