fn trim_probe_text(value: &[u8]) -> String {
    let text = String::from_utf8_lossy(value);
    let trimmed = text.trim();
    if trimmed.chars().count() <= 1200 {
        return trimmed.to_string();
    }

    let mut shortened = trimmed.chars().take(1200).collect::<String>();
    shortened.push_str("...");
    shortened
}

fn run_runtime_probe_target(target: &RuntimeProbeTarget) -> RuntimeProbeResult {
    match Command::new(target.binary).args(&target.args).output() {
        Ok(output) => {
            let stdout = trim_probe_text(&output.stdout);
            let stderr = trim_probe_text(&output.stderr);
            let exit_code = output.status.code();
            let status = if output.status.success() {
                "ready"
            } else {
                "failed"
            };
            let evidence = if output.status.success() {
                format!(
                    "{} responded to bounded probe {} {}.",
                    target.binary,
                    target.binary,
                    target.args.join(" ")
                )
            } else {
                format!(
                    "{} returned non-zero exit {:?} for bounded probe.",
                    target.binary, exit_code
                )
            };

            RuntimeProbeResult {
                target: target.target.to_string(),
                title: target.title.to_string(),
                binary: target.binary.to_string(),
                args: target.args.iter().map(|arg| arg.to_string()).collect(),
                sidecar_id: target.sidecar_id.to_string(),
                target_family: target.target_family.to_string(),
                required_for: target.required_for.to_string(),
                required: target.required,
                status: status.to_string(),
                stdout,
                stderr,
                exit_code,
                evidence,
                process_spawn_enabled: true,
                sidecar_launch_enabled: false,
                execution_enabled: false,
            }
        }
        Err(error) => RuntimeProbeResult {
            target: target.target.to_string(),
            title: target.title.to_string(),
            binary: target.binary.to_string(),
            args: target.args.iter().map(|arg| arg.to_string()).collect(),
            sidecar_id: target.sidecar_id.to_string(),
            target_family: target.target_family.to_string(),
            required_for: target.required_for.to_string(),
            required: target.required,
            status: "missing".to_string(),
            stdout: String::new(),
            stderr: error.to_string(),
            exit_code: None,
            evidence: format!(
                "{} is not available to this bounded runtime probe: {error}",
                target.binary
            ),
            process_spawn_enabled: true,
            sidecar_launch_enabled: false,
            execution_enabled: false,
        },
    }
}

#[tauri::command]
pub fn runtime_probe_board(request: RuntimeProbeRequest) -> RuntimeProbeBoard {
    let selected = request
        .target
        .unwrap_or_else(|| "all".to_string())
        .trim()
        .to_ascii_lowercase();
    let selected = if selected.is_empty() {
        "all".to_string()
    } else {
        selected
    };

    let selected_targets: Vec<RuntimeProbeTarget> = runtime_probe_targets()
        .into_iter()
        .filter(|target| {
            selected == "all" || selected == target.target || selected == target.sidecar_id
        })
        .collect();
    let results: Vec<RuntimeProbeResult> = selected_targets
        .iter()
        .map(run_runtime_probe_target)
        .collect();
    let ready_count = results
        .iter()
        .filter(|result| result.status == "ready")
        .count();
    let missing_count = results
        .iter()
        .filter(|result| result.status == "missing")
        .count();
    let failed_count = results
        .iter()
        .filter(|result| result.status == "failed")
        .count();
    let required_count = results.iter().filter(|result| result.required).count();
    let required_ready_count = results
        .iter()
        .filter(|result| result.required && result.status == "ready")
        .count();
    let blockers = results
        .iter()
        .filter(|result| result.required && result.status != "ready")
        .map(|result| {
            format!(
                "{} required for {} is {}",
                result.title, result.target_family, result.status
            )
        })
        .collect::<Vec<_>>();
    let status = if results.is_empty() {
        "runtime_probe_board_no_matching_target"
    } else if failed_count == 0 && missing_count == 0 {
        "runtime_probe_board_ready_sidecar_launch_disabled"
    } else {
        "runtime_probe_board_probe_evidence_sidecar_launch_disabled"
    };

    RuntimeProbeBoard {
        status,
        probe_count: results.len(),
        ready_count,
        missing_count,
        failed_count,
        required_ready_count,
        required_count,
        process_spawn_enabled: true,
        sidecar_launch_enabled: false,
        execution_enabled: false,
        results,
        blockers,
        next_action: "Use missing or failed probe evidence to install/repair runtimes, then promote passing targets to explicit sidecar launch approval packets.",
    }
}

fn runtime_depth_home_dir() -> PathBuf {
    env::var_os("HOME")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("/home/rage"))
}

fn runtime_depth_path_probe(id: &str, title: &str, path: PathBuf) -> RuntimeDepthPathProbe {
    let path_display = path.display().to_string();
    match fs::metadata(&path) {
        Ok(metadata) => {
            let kind = if metadata.is_dir() {
                "directory"
            } else if metadata.is_file() {
                "file"
            } else {
                "special"
            };
            RuntimeDepthPathProbe {
                id: id.to_string(),
                title: title.to_string(),
                path: path_display.clone(),
                status: "metadata_ready".to_string(),
                exists: true,
                is_file: metadata.is_file(),
                is_dir: metadata.is_dir(),
                size_bytes: Some(metadata.len()),
                metadata_only: true,
                config_read_enabled: false,
                evidence: format!("{title} metadata exists as {kind}; content was not read."),
            }
        }
        Err(error) => RuntimeDepthPathProbe {
            id: id.to_string(),
            title: title.to_string(),
            path: path_display.clone(),
            status: "missing".to_string(),
            exists: false,
            is_file: false,
            is_dir: false,
            size_bytes: None,
            metadata_only: true,
            config_read_enabled: false,
            evidence: format!("{title} metadata missing at {path_display}: {error}"),
        },
    }
}

