fn runtime_depth_hermes_log_preflight() -> (bool, String, Option<String>) {
    let hermes_home = hermes_home_for_preflight();
    let log_dir = hermes_home.join("logs");
    let create_result = fs::create_dir_all(&log_dir);
    if let Err(error) = create_result {
        return (
            false,
            "hermes_log_preflight_failed".to_string(),
            Some(format!("{}: {error}", log_dir.display())),
        );
    }

    let probe_path = log_dir.join(".gravity-omega-runtime-depth-write-probe");
    let write_result = OpenOptions::new()
        .create(true)
        .append(true)
        .open(&probe_path)
        .and_then(|mut file| {
            writeln!(
                file,
                "gravity-omega runtime depth probe {}",
                now_ms().unwrap_or_default()
            )
        });
    match write_result {
        Ok(_) => {
            let _ = fs::remove_file(probe_path);
            (true, "hermes_log_preflight_passed".to_string(), None)
        }
        Err(error) => (
            false,
            "hermes_log_preflight_failed".to_string(),
            Some(format!("{}: {error}", log_dir.display())),
        ),
    }
}

fn first_number_before(text: &str, needle: &str) -> usize {
    let Some(index) = text.find(needle) else {
        return 0;
    };
    text[..index]
        .split_whitespace()
        .rev()
        .find_map(|part| {
            part.trim_matches(|ch: char| !ch.is_ascii_digit())
                .parse::<usize>()
                .ok()
        })
        .unwrap_or(0)
}

fn first_number_after(text: &str, needle: &str) -> usize {
    let Some(index) = text.find(needle) else {
        return 0;
    };
    text[index + needle.len()..]
        .split_whitespace()
        .find_map(|part| {
            part.trim_matches(|ch: char| !ch.is_ascii_digit())
                .parse::<usize>()
                .ok()
        })
        .unwrap_or(0)
}

fn parse_hermes_capability_count(id: &str, stdout: &str) -> usize {
    match id {
        "hermes-skills" => stdout
            .lines()
            .rev()
            .find(|line| line.contains(" enabled") && line.contains("disabled"))
            .map(|line| first_number_before(line, "enabled"))
            .unwrap_or_else(|| first_number_before(stdout, "enabled")),
        "hermes-mcp" => stdout.matches("✓ enabled").count(),
        "hermes-hooks" => first_number_after(stdout, "Configured shell hooks ("),
        _ => 0,
    }
}

fn run_runtime_depth_hermes_capability_probe(
    id: &str,
    title: &str,
    args: &[&str],
) -> RuntimeDepthHermesCapabilityProbe {
    let started = Instant::now();
    let mut child = match Command::new("hermes")
        .args(args)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
    {
        Ok(child) => child,
        Err(error) => {
            return RuntimeDepthHermesCapabilityProbe {
                id: id.to_string(),
                title: title.to_string(),
                argv: std::iter::once("hermes".to_string())
                    .chain(args.iter().map(|arg| arg.to_string()))
                    .collect(),
                status: "spawn_failed".to_string(),
                stdout_preview: String::new(),
                stderr_preview: error.to_string(),
                exit_code: None,
                duration_ms: started.elapsed().as_millis() as u64,
                parsed_count: 0,
                evidence: format!("{title} probe could not spawn Hermes: {error}"),
            };
        }
    };

    let mut timed_out = false;
    loop {
        match child.try_wait() {
            Ok(Some(_status)) => break,
            Ok(None) => {
                if started.elapsed() >= Duration::from_millis(20_000) {
                    timed_out = true;
                    let _ = child.kill();
                    break;
                }
                std::thread::sleep(Duration::from_millis(50));
            }
            Err(error) => {
                return RuntimeDepthHermesCapabilityProbe {
                    id: id.to_string(),
                    title: title.to_string(),
                    argv: std::iter::once("hermes".to_string())
                        .chain(args.iter().map(|arg| arg.to_string()))
                        .collect(),
                    status: "wait_failed".to_string(),
                    stdout_preview: String::new(),
                    stderr_preview: error.to_string(),
                    exit_code: None,
                    duration_ms: started.elapsed().as_millis() as u64,
                    parsed_count: 0,
                    evidence: format!("{title} probe failed while waiting for Hermes: {error}"),
                };
            }
        }
    }

    let output = match child.wait_with_output() {
        Ok(output) => output,
        Err(error) => {
            return RuntimeDepthHermesCapabilityProbe {
                id: id.to_string(),
                title: title.to_string(),
                argv: std::iter::once("hermes".to_string())
                    .chain(args.iter().map(|arg| arg.to_string()))
                    .collect(),
                status: "collect_failed".to_string(),
                stdout_preview: String::new(),
                stderr_preview: error.to_string(),
                exit_code: None,
                duration_ms: started.elapsed().as_millis() as u64,
                parsed_count: 0,
                evidence: format!("{title} probe failed collecting Hermes output: {error}"),
            };
        }
    };
    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    let stdout_preview = trim_probe_text(&output.stdout);
    let stderr_preview = trim_probe_text(&output.stderr);
    let parsed_count = parse_hermes_capability_count(id, &stdout);
    let status = if timed_out {
        "timed_out"
    } else if output.status.success() {
        "ready"
    } else {
        "failed"
    };
    RuntimeDepthHermesCapabilityProbe {
        id: id.to_string(),
        title: title.to_string(),
        argv: std::iter::once("hermes".to_string())
            .chain(args.iter().map(|arg| arg.to_string()))
            .collect(),
        status: status.to_string(),
        stdout_preview,
        stderr_preview,
        exit_code: output.status.code(),
        duration_ms: started.elapsed().as_millis() as u64,
        parsed_count,
        evidence: if status == "ready" {
            format!("{title} probe completed; parsed_count={parsed_count}.")
        } else {
            format!("{title} probe status={status}; parsed_count={parsed_count}.")
        },
    }
}

