fn create_runtime_evidence_spine(
    task_run_id: &str,
    runner_adapter_id: &str,
    runtime: &str,
) -> Result<RunnerEvidenceRuntimeSpine, String> {
    let process_plan = build_process_command_plan_stub(ProcessCommandPlanRequest {
        task_run_id: task_run_id.to_string(),
        runner_adapter_id: runner_adapter_id.to_string(),
        runtime: runtime.to_string(),
    })?;
    let stream_init = initialize_process_streams_stub(ProcessStreamInitRequest {
        process_command_plan_id: process_plan.plan.id.clone(),
    })?;
    let lifecycle = create_process_lifecycle_stub(ProcessLifecycleRequest {
        process_command_plan_id: process_plan.plan.id.clone(),
        process_stream_init_id: stream_init.stream.id.clone(),
    })?;
    let cancel_policy = create_process_control_policy_stub(ProcessControlPolicyRequest {
        process_lifecycle_id: lifecycle.lifecycle.id.clone(),
        requested_action: "cancel".to_string(),
    })?;
    let retry_policy = create_process_control_policy_stub(ProcessControlPolicyRequest {
        process_lifecycle_id: lifecycle.lifecycle.id.clone(),
        requested_action: "retry".to_string(),
    })?;
    let preflight = create_process_supervisor_preflight_stub(ProcessSupervisorPreflightRequest {
        process_lifecycle_id: lifecycle.lifecycle.id.clone(),
    })?;
    let queued_heartbeat =
        create_process_supervisor_heartbeat_stub(ProcessSupervisorHeartbeatRequest {
            process_supervisor_preflight_id: preflight.preflight.id.clone(),
            requested_state: "queued".to_string(),
        })?;
    let running_heartbeat =
        create_process_supervisor_heartbeat_stub(ProcessSupervisorHeartbeatRequest {
            process_supervisor_preflight_id: preflight.preflight.id.clone(),
            requested_state: "running".to_string(),
        })?;
    let exited_heartbeat =
        create_process_supervisor_heartbeat_stub(ProcessSupervisorHeartbeatRequest {
            process_supervisor_preflight_id: preflight.preflight.id.clone(),
            requested_state: "exited".to_string(),
        })?;
    let exit_summary =
        create_process_supervisor_exit_summary_stub(ProcessSupervisorExitSummaryRequest {
            process_supervisor_heartbeat_id: exited_heartbeat.heartbeat.id.clone(),
        })?;
    let output_tail = create_process_output_tail_summary_stub(ProcessOutputTailSummaryRequest {
        process_supervisor_exit_summary_id: exit_summary.summary.id.clone(),
    })?;
    let transcript_bundle = create_run_transcript_bundle_stub(RunTranscriptBundleRequest {
        process_output_tail_summary_id: output_tail.summary.id.clone(),
    })?;
    let export_policy = create_transcript_export_policy_stub(TranscriptExportPolicyRequest {
        run_transcript_bundle_id: transcript_bundle.bundle.id.clone(),
        requested_destination: "local_file".to_string(),
    })?;
    let protection_policy =
        create_transcript_protection_policy_stub(TranscriptProtectionPolicyRequest {
            transcript_export_policy_id: export_policy.policy.id.clone(),
            requested_redaction_profile: "secrets_and_paths".to_string(),
            requested_retention_tier: "local_30_days".to_string(),
        })?;

    let transcript_recorded = transcript_bundle.bundled
        && transcript_bundle.bundle.status == "transcript_bundle_recorded_execution_disabled";
    let export_policy_recorded = export_policy.policy_recorded
        && export_policy.policy.status == "transcript_export_policy_recorded_export_disabled";
    let protection_policy_recorded = protection_policy.policy_recorded
        && protection_policy.policy.status == "transcript_protection_policy_recorded_export_disabled";
    let all_disabled = !process_plan.process_spawn_enabled
        && !process_plan.writes_allowed
        && !process_plan.execution_enabled
        && !stream_init.process_spawn_enabled
        && !stream_init.writes_allowed
        && !stream_init.execution_enabled
        && !lifecycle.process_spawn_enabled
        && !lifecycle.writes_allowed
        && !lifecycle.execution_enabled
        && !cancel_policy.process_spawn_enabled
        && !cancel_policy.execution_enabled
        && !retry_policy.process_spawn_enabled
        && !retry_policy.execution_enabled
        && !preflight.process_spawn_enabled
        && !preflight.writes_allowed
        && !preflight.execution_enabled
        && !queued_heartbeat.process_spawn_enabled
        && !queued_heartbeat.writes_allowed
        && !queued_heartbeat.execution_enabled
        && !running_heartbeat.process_spawn_enabled
        && !running_heartbeat.writes_allowed
        && !running_heartbeat.execution_enabled
        && !exited_heartbeat.process_spawn_enabled
        && !exited_heartbeat.writes_allowed
        && !exited_heartbeat.execution_enabled
        && !exit_summary.process_spawn_enabled
        && !exit_summary.writes_allowed
        && !exit_summary.execution_enabled
        && !output_tail.process_spawn_enabled
        && !output_tail.writes_allowed
        && !output_tail.execution_enabled
        && !transcript_bundle.process_spawn_enabled
        && !transcript_bundle.writes_allowed
        && !transcript_bundle.execution_enabled
        && !export_policy.export_enabled
        && !export_policy.writes_allowed
        && !export_policy.execution_enabled
        && !protection_policy.export_enabled
        && !protection_policy.writes_allowed
        && !protection_policy.execution_enabled;
    let status = if transcript_recorded
        && export_policy_recorded
        && protection_policy_recorded
        && all_disabled
    {
        "runner_evidence_runtime_spine_recorded_execution_disabled"
    } else {
        "runner_evidence_runtime_spine_incomplete_execution_disabled"
    }
    .to_string();

    Ok(RunnerEvidenceRuntimeSpine {
        runtime: runtime.to_string(),
        process_command_plan_id: process_plan.plan.id,
        process_stream_init_id: stream_init.stream.id,
        process_lifecycle_id: lifecycle.lifecycle.id,
        cancel_policy_id: cancel_policy.policy.id,
        retry_policy_id: retry_policy.policy.id,
        supervisor_preflight_id: preflight.preflight.id,
        queued_heartbeat_id: queued_heartbeat.heartbeat.id,
        running_heartbeat_id: running_heartbeat.heartbeat.id,
        exited_heartbeat_id: exited_heartbeat.heartbeat.id,
        exit_summary_id: exit_summary.summary.id,
        output_tail_summary_id: output_tail.summary.id,
        transcript_bundle_id: transcript_bundle.bundle.id,
        export_policy_id: export_policy.policy.id,
        protection_policy_id: protection_policy.policy.id,
        status,
        transcript_recorded,
        export_policy_recorded,
        protection_policy_recorded,
        stdout_size_bytes: transcript_bundle.bundle.stdout_size_bytes,
        stderr_size_bytes: transcript_bundle.bundle.stderr_size_bytes,
        process_spawn_enabled: false,
        sidecar_launch_enabled: false,
        terminal_enabled: false,
        export_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
    })
}

#[tauri::command]
pub fn create_runner_evidence_spine_stub(
    request: RunnerEvidenceSpineRequest,
) -> Result<RunnerEvidenceSpineResult, String> {
    let timestamp = now_ms()?;
    let requested_by = request
        .requested_by
        .unwrap_or_else(|| "operator".to_string())
        .trim()
        .chars()
        .take(120)
        .collect::<String>();
    let requested_by = if requested_by.is_empty() {
        "operator".to_string()
    } else {
        requested_by
    };

    let requested_task_id = request
        .task_run_id
        .unwrap_or_default()
        .trim()
        .to_string();
    let task_run = if requested_task_id.is_empty() {
        list_task_runs()?.into_iter().next()
    } else {
        read_task_run_record(&requested_task_id)?
    };
    let (task_run_id, repo, task_run_found) = match task_run {
        Some(record) => (record.id, record.repo, true),
        None if requested_task_id.is_empty() => {
            let stub = create_task_run_stub(TaskRunRequest {
                mode: "joint_ci".to_string(),
                repo: rebuild_workspace_root().display().to_string(),
                prompt: "Prepare Codex/Hermes supervised runner evidence spine.".to_string(),
            })?;
            (stub.id, stub.repo, true)
        }
        None => {
            return Err(format!(
                "requested task run {requested_task_id} was not found"
            ));
        }
    };

    let requested_joint_packet_id = request
        .joint_runtime_run_packet_id
        .unwrap_or_default()
        .trim()
        .to_string();
    let existing_joint_packet = list_joint_runtime_run_packets()?.into_iter().find(|record| {
        if requested_joint_packet_id.is_empty() {
            record.task_run_id == task_run_id
        } else {
            record.id == requested_joint_packet_id
        }
    });
    let joint_runtime_run_packet_found = existing_joint_packet.is_some();
    let joint_runtime_run_packet = match existing_joint_packet {
        Some(record) => record,
        None => {
            create_joint_runtime_run_packet_stub(JointRuntimeRunPacketRequest {
                task_run_id: Some(task_run_id.clone()),
                requested_by: Some(requested_by.clone()),
            })?
            .record
        }
    };

    let approval = create_approval_record_stub(ApprovalRecordRequest {
        subject_id: task_run_id.clone(),
        command_id: "agent.joint_ci".to_string(),
        task_run_id: Some(task_run_id.clone()),
        capability_tier: "gated".to_string(),
        risk_summary: "Runner evidence spine records Codex/Hermes process prerequisites without live execution.".to_string(),
        confirmation_phrase: "APPROVE RUNNER EVIDENCE SPINE".to_string(),
    })?;
    let resolved_approval = resolve_approval_record_stub(ApprovalDecisionRequest {
        id: approval.id,
        decision: "approve".to_string(),
        confirmation_text: "APPROVE RUNNER EVIDENCE SPINE".to_string(),
        note: "evidence spine approval recorded; execution remains disabled".to_string(),
    })?;
    let runner = prepare_runner_invocation_stub(RunnerPrepareRequest {
        task_run_id: task_run_id.clone(),
        approval_id: resolved_approval.id.clone(),
        command_id: "agent.joint_ci".to_string(),
        argv: vec![
            "codex".to_string(),
            "exec".to_string(),
            "--json".to_string(),
            "--sandbox".to_string(),
            "workspace-write".to_string(),
        ],
        requested_policy: Some("workspace_write".to_string()),
    })?;
    let joint_plan = create_joint_agent_plan_stub(JointAgentPlanRequest {
        task_run_id: task_run_id.clone(),
        goal: "Record full Codex/Hermes runner evidence spine before live process execution.".to_string(),
        repo: Some(repo.clone()),
    })?;
    append_agent_event_stub(AgentEventRequest {
        task_run_id: task_run_id.clone(),
        source_runtime: "codex".to_string(),
        event_type: "runner_evidence_spine_planned".to_string(),
        level: "info".to_string(),
        message: "Codex runner evidence spine planned without process execution.".to_string(),
        payload: Some(serde_json::json!({
            "process_spawn_enabled": false,
            "execution_enabled": false
        })),
    })?;
    append_agent_event_stub(AgentEventRequest {
        task_run_id: task_run_id.clone(),
        source_runtime: "hermes".to_string(),
        event_type: "runner_evidence_spine_planned".to_string(),
        level: "info".to_string(),
        message: "Hermes runner evidence spine planned without process execution.".to_string(),
        payload: Some(serde_json::json!({
            "process_spawn_enabled": false,
            "execution_enabled": false
        })),
    })?;
    let lease = create_workspace_lease_stub(WorkspaceLeaseRequest {
        task_run_id: task_run_id.clone(),
        workspace_path: repo.clone(),
        owner_runtime: "gravity-omega".to_string(),
        purpose: "Runner evidence spine only; no live process, PTY, write, or export action is enabled.".to_string(),
        write_scope: vec![format!("runner-evidence-spine-readonly-{timestamp}")],
        requested_mode: Some("read_only".to_string()),
    })?;
    let adapter = prepare_runner_adapter_stub(RunnerAdapterPrepareRequest {
        task_run_id: task_run_id.clone(),
        runner_invocation_id: runner.invocation.id.clone(),
        joint_plan_id: joint_plan.plan.id.clone(),
        workspace_lease_id: lease.lease.id.clone(),
    })?;

    let runtimes = vec![
        create_runtime_evidence_spine(&task_run_id, &adapter.adapter.id, "codex")?,
        create_runtime_evidence_spine(&task_run_id, &adapter.adapter.id, "hermes")?,
    ];
    append_agent_event_stub(AgentEventRequest {
        task_run_id: task_run_id.clone(),
        source_runtime: "gravity-omega".to_string(),
        event_type: "runner_evidence_spine_recorded".to_string(),
        level: "info".to_string(),
        message: "Full disabled Codex/Hermes runner evidence spine recorded.".to_string(),
        payload: Some(serde_json::json!({
            "runtime_count": runtimes.len(),
            "process_spawn_enabled": false,
            "execution_enabled": false
        })),
    })?;

    let runtime_count = runtimes.len();
    let transcript_bundle_count = runtimes
        .iter()
        .filter(|runtime| runtime.transcript_recorded)
        .count();
    let export_policy_count = runtimes
        .iter()
        .filter(|runtime| runtime.export_policy_recorded)
        .count();
    let protection_policy_count = runtimes
        .iter()
        .filter(|runtime| runtime.protection_policy_recorded)
        .count();
    let complete_runtime_count = runtimes
        .iter()
        .filter(|runtime| {
            runtime.status == "runner_evidence_runtime_spine_recorded_execution_disabled"
                && !runtime.process_spawn_enabled
                && !runtime.sidecar_launch_enabled
                && !runtime.terminal_enabled
                && !runtime.export_enabled
                && !runtime.writes_allowed
                && !runtime.execution_enabled
        })
        .count();
    let evidence_record_count = 8 + (runtime_count * 15);
    let status = if runtime_count == 2
        && transcript_bundle_count == 2
        && export_policy_count == 2
        && protection_policy_count == 2
        && complete_runtime_count == 2
    {
        "runner_evidence_spine_recorded_execution_disabled"
    } else {
        "runner_evidence_spine_incomplete_execution_disabled"
    }
    .to_string();

    let id = format!(
        "runner-evidence-spine-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug_limit(&task_run_id, 48)
    );
    let dir = runner_evidence_spines_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create runner-evidence-spines directory {}: {error}",
            dir.display()
        )
    })?;
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let record = RunnerEvidenceSpineRecord {
        id: id.clone(),
        task_run_id,
        joint_runtime_run_packet_id: joint_runtime_run_packet.id,
        approval_id: resolved_approval.id,
        runner_invocation_id: runner.invocation.id,
        joint_plan_id: joint_plan.plan.id,
        workspace_lease_id: lease.lease.id,
        runner_adapter_id: adapter.adapter.id,
        status: status.clone(),
        requested_by,
        runtime_count,
        transcript_bundle_count,
        export_policy_count,
        protection_policy_count,
        complete_runtime_count,
        evidence_record_count,
        runtimes,
        process_spawn_enabled: false,
        sidecar_launch_enabled: false,
        terminal_enabled: false,
        stream_read_enabled: false,
        live_tail_enabled: false,
        export_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons: vec![
            "runner evidence spine records the full disabled Codex/Hermes process prerequisite chain in one product action".to_string(),
            "the spine includes task, approval, runner, joint plan, workspace lease, adapter, process plan, stream, lifecycle, supervisor, transcript, export, and protection evidence".to_string(),
            "process spawn, sidecar launch, terminal control, stream reading, live tailing, exports, writes, and execution remain disabled".to_string(),
        ],
        next_step: "Replace disabled heartbeat and empty transcript records with a bounded supervised one-shot runner only after explicit operator approval, output streaming, PTY policy, and rollback evidence are implemented.".to_string(),
    };

    let json = serde_json::to_string_pretty(&record)
        .map_err(|error| format!("failed to serialize runner evidence spine: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write runner evidence spine {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "runner_evidence_spine_stub_created",
            "id": id,
            "task_run_id": &record.task_run_id,
            "joint_runtime_run_packet_id": &record.joint_runtime_run_packet_id,
            "status": &record.status,
            "runtime_count": record.runtime_count,
            "transcript_bundle_count": record.transcript_bundle_count,
            "export_policy_count": record.export_policy_count,
            "protection_policy_count": record.protection_policy_count,
            "complete_runtime_count": record.complete_runtime_count,
            "evidence_record_count": record.evidence_record_count,
            "process_spawn_enabled": false,
            "sidecar_launch_enabled": false,
            "terminal_enabled": false,
            "export_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(RunnerEvidenceSpineResult {
        accepted: false,
        spine_recorded: true,
        task_run_found,
        joint_runtime_run_packet_found,
        runtime_count: record.runtime_count,
        transcript_bundle_count: record.transcript_bundle_count,
        complete_runtime_count: record.complete_runtime_count,
        process_spawn_enabled: false,
        sidecar_launch_enabled: false,
        terminal_enabled: false,
        export_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        record,
    })
}

