fn run_supervised_runtime_smoke_target(
    target: &RuntimeProbeTarget,
    requested_by: &str,
    timeout_ms: u64,
    timestamp: u64,
    dir: &Path,
) -> Result<SupervisedRuntimeSmokeRecord, String> {
    if target.binary.contains('/')
        || target.binary.contains('\\')
        || target.binary.chars().any(char::is_whitespace)
        || target
            .args
            .iter()
            .any(|arg| arg.contains(';') || arg.contains('&') || arg.contains('|'))
    {
        return Err(format!(
            "runtime target {} failed hard-coded allowlist validation",
            target.target
        ));
    }

    let id = format!(
        "supervised-runtime-smoke-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug_limit(target.target, 48)
    );
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let stdout_transcript_path = dir.join(format!("{id}.stdout.txt"));
    let stderr_transcript_path = dir.join(format!("{id}.stderr.txt"));

    let started = Instant::now();
    let mut pid = None;
    let mut exit_code = None;
    let mut timed_out = false;
    let stdout_bytes: Vec<u8>;
    let stderr_bytes: Vec<u8>;
    let status: String;

    match Command::new(target.binary)
        .args(&target.args)
        .current_dir(dir)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
    {
        Ok(mut child) => {
            pid = Some(child.id());
            loop {
                match child.try_wait() {
                    Ok(Some(_status)) => break,
                    Ok(None) => {
                        if started.elapsed() >= Duration::from_millis(timeout_ms) {
                            timed_out = true;
                            let _ = child.kill();
                            break;
                        }
                        std::thread::sleep(Duration::from_millis(20));
                    }
                    Err(error) => {
                        stdout_bytes = Vec::new();
                        stderr_bytes = error.to_string().into_bytes();
                        status = "supervised_runtime_smoke_wait_failed".to_string();
                        return write_supervised_runtime_smoke_record(
                            target,
                            requested_by,
                            timestamp,
                            started.elapsed().as_millis() as u64,
                            pid,
                            None,
                            false,
                            stdout_bytes,
                            stderr_bytes,
                            status,
                            record_path,
                            log_path,
                            stdout_transcript_path,
                            stderr_transcript_path,
                        );
                    }
                }
            }

            let output = child.wait_with_output().map_err(|error| {
                format!(
                    "failed to collect supervised runtime smoke output for {}: {error}",
                    target.target
                )
            })?;
            exit_code = output.status.code();
            stdout_bytes = output.stdout;
            stderr_bytes = output.stderr;
            status = if timed_out {
                "supervised_runtime_smoke_timed_out"
            } else if output.status.success() {
                "supervised_runtime_smoke_succeeded"
            } else {
                "supervised_runtime_smoke_failed"
            }
            .to_string();
        }
        Err(error) => {
            stdout_bytes = Vec::new();
            stderr_bytes = error.to_string().into_bytes();
            status = "supervised_runtime_smoke_spawn_failed".to_string();
        }
    }

    write_supervised_runtime_smoke_record(
        target,
        requested_by,
        timestamp,
        started.elapsed().as_millis() as u64,
        pid,
        exit_code,
        timed_out,
        stdout_bytes,
        stderr_bytes,
        status,
        record_path,
        log_path,
        stdout_transcript_path,
        stderr_transcript_path,
    )
}

#[allow(clippy::too_many_arguments)]
fn write_supervised_runtime_smoke_record(
    target: &RuntimeProbeTarget,
    requested_by: &str,
    timestamp: u64,
    duration_ms: u64,
    pid: Option<u32>,
    exit_code: Option<i32>,
    timed_out: bool,
    stdout_bytes: Vec<u8>,
    stderr_bytes: Vec<u8>,
    status: String,
    record_path: PathBuf,
    log_path: PathBuf,
    stdout_transcript_path: PathBuf,
    stderr_transcript_path: PathBuf,
) -> Result<SupervisedRuntimeSmokeRecord, String> {
    let stdout_full = String::from_utf8_lossy(&stdout_bytes).to_string();
    let stderr_full = String::from_utf8_lossy(&stderr_bytes).to_string();
    fs::write(&stdout_transcript_path, &stdout_full).map_err(|error| {
        format!(
            "failed to write stdout transcript {}: {error}",
            stdout_transcript_path.display()
        )
    })?;
    fs::write(&stderr_transcript_path, &stderr_full).map_err(|error| {
        format!(
            "failed to write stderr transcript {}: {error}",
            stderr_transcript_path.display()
        )
    })?;

    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let stdout_transcript_display = stdout_transcript_path.display().to_string();
    let stderr_transcript_display = stderr_transcript_path.display().to_string();
    let id = record_path
        .file_stem()
        .and_then(|value| value.to_str())
        .unwrap_or("supervised-runtime-smoke")
        .to_string();
    let record = SupervisedRuntimeSmokeRecord {
        id: id.clone(),
        target: target.target.to_string(),
        title: target.title.to_string(),
        binary: target.binary.to_string(),
        args: target.args.iter().map(|arg| arg.to_string()).collect(),
        sidecar_id: target.sidecar_id.to_string(),
        target_family: target.target_family.to_string(),
        required_for: target.required_for.to_string(),
        required: target.required,
        requested_by: requested_by.to_string(),
        status: status.clone(),
        pid,
        exit_code,
        timed_out,
        duration_ms,
        stdout: trim_probe_text(&stdout_bytes),
        stderr: trim_probe_text(&stderr_bytes),
        stdout_size_bytes: stdout_bytes.len() as u64,
        stderr_size_bytes: stderr_bytes.len() as u64,
        stdout_transcript_path: stdout_transcript_display.clone(),
        stderr_transcript_path: stderr_transcript_display.clone(),
        process_spawn_enabled: true,
        bounded_execution_performed: true,
        sidecar_launch_enabled: false,
        terminal_enabled: false,
        workspace_read_enabled: false,
        workspace_write_enabled: false,
        patch_apply_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        task_execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons: vec![
            "only a hard-coded runtime-version probe was spawned under bounded supervision".to_string(),
            "stdout and stderr were captured into app-state transcripts for review".to_string(),
            "sidecar launch, terminal control, workspace reads/writes, patches, exports, memory writes, and Codex/Hermes task execution remain disabled".to_string(),
        ],
        next_step: "Promote this supervised runner to Codex/Hermes task execution only after PTY policy, approval binding, workspace lease enforcement, cancellation UI, and rollback evidence are wired.".to_string(),
    };

    let json = serde_json::to_string_pretty(&record)
        .map_err(|error| format!("failed to serialize supervised runtime smoke: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write supervised runtime smoke {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "supervised_runtime_smoke_recorded",
            "id": id,
            "target": target.target,
            "status": status,
            "pid": pid,
            "exit_code": exit_code,
            "timed_out": timed_out,
            "duration_ms": duration_ms,
            "stdout_size_bytes": record.stdout_size_bytes,
            "stderr_size_bytes": record.stderr_size_bytes,
            "process_spawn_enabled": true,
            "bounded_execution_performed": true,
            "sidecar_launch_enabled": false,
            "terminal_enabled": false,
            "workspace_read_enabled": false,
            "workspace_write_enabled": false,
            "patch_apply_enabled": false,
            "export_enabled": false,
            "memory_write_enabled": false,
            "writes_allowed": false,
            "task_execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(record)
}

#[tauri::command]
pub fn run_supervised_runtime_smoke(
    request: SupervisedRuntimeSmokeRequest,
) -> Result<SupervisedRuntimeSmokeResult, String> {
    let timestamp = now_ms()?;
    let requested_target = request
        .target
        .unwrap_or_else(|| "all".to_string())
        .trim()
        .to_ascii_lowercase();
    let requested_target = if requested_target.is_empty() {
        "all".to_string()
    } else {
        requested_target
    };
    let requested_by = request
        .requested_by
        .unwrap_or_else(|| "operator".to_string())
        .trim()
        .chars()
        .take(120)
        .collect::<String>();
    let requested_by = if requested_by.is_empty() {
        "operator".to_string()
    } else {
        requested_by
    };
    let timeout_ms = request.timeout_ms.unwrap_or(3_000).clamp(500, 10_000);
    let selected_targets: Vec<RuntimeProbeTarget> = runtime_probe_targets()
        .into_iter()
        .filter(|target| {
            requested_target == "all"
                || requested_target == target.target
                || requested_target == target.sidecar_id
        })
        .collect();

    if selected_targets.is_empty() {
        return Ok(SupervisedRuntimeSmokeResult {
            accepted: false,
            requested_target,
            timeout_ms,
            run_count: 0,
            succeeded_count: 0,
            failed_count: 0,
            timed_out_count: 0,
            process_spawn_enabled: true,
            bounded_execution_performed: false,
            sidecar_launch_enabled: false,
            terminal_enabled: false,
            writes_allowed: false,
            task_execution_enabled: false,
            records: Vec::new(),
            blockers: vec!["No hard-coded runtime target matched the request.".to_string()],
            next_step: "Choose one of the runtime probe target ids or sidecar ids before requesting a supervised smoke run.".to_string(),
        });
    }

    let dir = supervised_runtime_smokes_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create supervised-runtime-smokes directory {}: {error}",
            dir.display()
        )
    })?;

    let mut records = Vec::new();
    for target in &selected_targets {
        records.push(run_supervised_runtime_smoke_target(
            target,
            &requested_by,
            timeout_ms,
            timestamp,
            &dir,
        )?);
    }

    let succeeded_count = records
        .iter()
        .filter(|record| record.status == "supervised_runtime_smoke_succeeded")
        .count();
    let timed_out_count = records.iter().filter(|record| record.timed_out).count();
    let failed_count = records.len().saturating_sub(succeeded_count);
    let blockers = records
        .iter()
        .filter(|record| record.status != "supervised_runtime_smoke_succeeded")
        .map(|record| {
            format!(
                "{} supervised smoke status is {}",
                record.title, record.status
            )
        })
        .collect::<Vec<_>>();

    Ok(SupervisedRuntimeSmokeResult {
        accepted: true,
        requested_target,
        timeout_ms,
        run_count: records.len(),
        succeeded_count,
        failed_count,
        timed_out_count,
        process_spawn_enabled: true,
        bounded_execution_performed: true,
        sidecar_launch_enabled: false,
        terminal_enabled: false,
        writes_allowed: false,
        task_execution_enabled: false,
        records,
        blockers,
        next_step: "Use the captured transcripts and exit evidence to decide which runtime sidecars can move to explicit operator-approved launch packets; Codex/Hermes task execution remains blocked.".to_string(),
    })
}

