fn spawn_agent_transcript_pipe_reader<R: Read + Send + 'static>(
    mut reader: R,
) -> std::thread::JoinHandle<Vec<u8>> {
    std::thread::spawn(move || {
        let mut bytes = Vec::new();
        let _ = reader.read_to_end(&mut bytes);
        bytes
    })
}

fn run_agent_transcript_target_with_binary(
    target: &AgentTranscriptTarget,
    binary: &str,
    requested_by: &str,
    timeout_ms: u64,
    timestamp: u64,
    dir: &Path,
) -> Result<AgentTranscriptSessionRecord, String> {
    if target.binary.contains('/')
        || target.binary.contains('\\')
        || target.binary.chars().any(char::is_whitespace)
        || target
            .args
            .iter()
            .any(|arg| arg.contains(';') || arg.contains('&') || arg.contains('|'))
    {
        return Err(format!(
            "agent transcript target {} failed hard-coded allowlist validation",
            target.target
        ));
    }

    let id = format!(
        "agent-transcript-session-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug_limit(target.target, 48)
    );
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let stdout_transcript_path = dir.join(format!("{id}.stdout.txt"));
    let stderr_transcript_path = dir.join(format!("{id}.stderr.txt"));

    let started = Instant::now();
    let mut pid = None;
    let mut exit_code = None;
    let mut timed_out = false;
    let stdout_bytes: Vec<u8>;
    let stderr_bytes: Vec<u8>;
    let status: String;

    let mut stdout_pipe_reader_enabled = false;
    let mut stderr_pipe_reader_enabled = false;
    let mut timeout_kill_sent = false;
    let mut wait_after_kill_ms = 0;
    let partial_output_captured: bool;

    match Command::new(binary)
        .args(&target.args)
        .current_dir(dir)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
    {
        Ok(mut child) => {
            pid = Some(child.id());
            let stdout_reader = child
                .stdout
                .take()
                .map(spawn_agent_transcript_pipe_reader);
            let stderr_reader = child
                .stderr
                .take()
                .map(spawn_agent_transcript_pipe_reader);
            stdout_pipe_reader_enabled = stdout_reader.is_some();
            stderr_pipe_reader_enabled = stderr_reader.is_some();

            loop {
                match child.try_wait() {
                    Ok(Some(status_value)) => {
                        exit_code = status_value.code();
                        break;
                    }
                    Ok(None) => {
                        if started.elapsed() >= Duration::from_millis(timeout_ms) {
                            timed_out = true;
                            let kill_started = Instant::now();
                            timeout_kill_sent = child.kill().is_ok();
                            exit_code = child.wait().ok().and_then(|status_value| status_value.code());
                            wait_after_kill_ms = kill_started.elapsed().as_millis() as u64;
                            break;
                        }
                        std::thread::sleep(Duration::from_millis(20));
                    }
                    Err(error) => {
                        let kill_started = Instant::now();
                        timeout_kill_sent = child.kill().is_ok();
                        exit_code = child.wait().ok().and_then(|status_value| status_value.code());
                        wait_after_kill_ms = kill_started.elapsed().as_millis() as u64;
                        let mut stderr_existing = error.to_string().into_bytes();
                        if let Some(handle) = stderr_reader {
                            if let Ok(mut existing) = handle.join() {
                                existing.extend_from_slice(b"\n");
                                existing.extend(stderr_existing);
                                stderr_existing = existing;
                            }
                        }
                        stdout_bytes = stdout_reader
                            .and_then(|handle| handle.join().ok())
                            .unwrap_or_default();
                        stderr_bytes = stderr_existing;
                        partial_output_captured =
                            !stdout_bytes.is_empty() || !stderr_bytes.is_empty();
                        status = "agent_transcript_session_wait_failed".to_string();
                        return write_agent_transcript_session_record(
                            target,
                            requested_by,
                            timestamp,
                            started.elapsed().as_millis() as u64,
                            pid,
                            exit_code,
                            false,
                            stdout_pipe_reader_enabled,
                            stderr_pipe_reader_enabled,
                            timeout_kill_sent,
                            wait_after_kill_ms,
                            partial_output_captured,
                            stdout_bytes,
                            stderr_bytes,
                            status,
                            record_path,
                            log_path,
                            stdout_transcript_path,
                            stderr_transcript_path,
                        );
                    }
                }
            }

            stdout_bytes = stdout_reader
                .and_then(|handle| handle.join().ok())
                .unwrap_or_default();
            stderr_bytes = stderr_reader
                .and_then(|handle| handle.join().ok())
                .unwrap_or_default();
            partial_output_captured = !stdout_bytes.is_empty() || !stderr_bytes.is_empty();
            status = if timed_out {
                "agent_transcript_session_timed_out"
            } else if exit_code == Some(0) {
                "agent_transcript_session_succeeded"
            } else {
                "agent_transcript_session_failed"
            }
            .to_string();
        }
        Err(error) => {
            stdout_bytes = Vec::new();
            stderr_bytes = error.to_string().into_bytes();
            status = "agent_transcript_session_spawn_failed".to_string();
            partial_output_captured = !stderr_bytes.is_empty();
        }
    }

    write_agent_transcript_session_record(
        target,
        requested_by,
        timestamp,
        started.elapsed().as_millis() as u64,
        pid,
        exit_code,
        timed_out,
        stdout_pipe_reader_enabled,
        stderr_pipe_reader_enabled,
        timeout_kill_sent,
        wait_after_kill_ms,
        partial_output_captured,
        stdout_bytes,
        stderr_bytes,
        status,
        record_path,
        log_path,
        stdout_transcript_path,
        stderr_transcript_path,
    )
}

fn run_agent_transcript_target(
    target: &AgentTranscriptTarget,
    requested_by: &str,
    timeout_ms: u64,
    timestamp: u64,
    dir: &Path,
) -> Result<AgentTranscriptSessionRecord, String> {
    run_agent_transcript_target_with_binary(
        target,
        target.binary,
        requested_by,
        timeout_ms,
        timestamp,
        dir,
    )
}

#[allow(clippy::too_many_arguments)]
fn write_agent_transcript_session_record(
    target: &AgentTranscriptTarget,
    requested_by: &str,
    timestamp: u64,
    duration_ms: u64,
    pid: Option<u32>,
    exit_code: Option<i32>,
    timed_out: bool,
    stdout_pipe_reader_enabled: bool,
    stderr_pipe_reader_enabled: bool,
    timeout_kill_sent: bool,
    wait_after_kill_ms: u64,
    partial_output_captured: bool,
    stdout_bytes: Vec<u8>,
    stderr_bytes: Vec<u8>,
    status: String,
    record_path: PathBuf,
    log_path: PathBuf,
    stdout_transcript_path: PathBuf,
    stderr_transcript_path: PathBuf,
) -> Result<AgentTranscriptSessionRecord, String> {
    let stdout_full = String::from_utf8_lossy(&stdout_bytes).to_string();
    let stderr_full = String::from_utf8_lossy(&stderr_bytes).to_string();
    fs::write(&stdout_transcript_path, &stdout_full).map_err(|error| {
        format!(
            "failed to write agent stdout transcript {}: {error}",
            stdout_transcript_path.display()
        )
    })?;
    fs::write(&stderr_transcript_path, &stderr_full).map_err(|error| {
        format!(
            "failed to write agent stderr transcript {}: {error}",
            stderr_transcript_path.display()
        )
    })?;

    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let stdout_transcript_display = stdout_transcript_path.display().to_string();
    let stderr_transcript_display = stderr_transcript_path.display().to_string();
    let id = record_path
        .file_stem()
        .and_then(|value| value.to_str())
        .unwrap_or("agent-transcript-session")
        .to_string();
    let record = AgentTranscriptSessionRecord {
        id: id.clone(),
        runtime: target.runtime.to_string(),
        target: target.target.to_string(),
        session_kind: target.session_kind.to_string(),
        title: target.title.to_string(),
        binary: target.binary.to_string(),
        args: target.args.iter().map(|arg| arg.to_string()).collect(),
        required_for: target.required_for.to_string(),
        requested_by: requested_by.to_string(),
        status: status.clone(),
        pid,
        exit_code,
        timed_out,
        duration_ms,
        stdout_pipe_reader_enabled,
        stderr_pipe_reader_enabled,
        timeout_kill_sent,
        wait_after_kill_ms,
        partial_output_captured,
        stdout: trim_probe_text(&stdout_bytes),
        stderr: trim_probe_text(&stderr_bytes),
        stdout_size_bytes: stdout_bytes.len() as u64,
        stderr_size_bytes: stderr_bytes.len() as u64,
        stdout_transcript_path: stdout_transcript_display.clone(),
        stderr_transcript_path: stderr_transcript_display.clone(),
        process_spawn_enabled: true,
        transcript_capture_enabled: true,
        agent_task_execution_enabled: false,
        sidecar_launch_enabled: false,
        terminal_enabled: false,
        workspace_read_enabled: false,
        workspace_write_enabled: false,
        patch_apply_enabled: false,
        live_mcp_call_enabled: false,
        config_read_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons: vec![
            "only a fixed Codex/Hermes version or help transcript session was spawned".to_string(),
            "stdout and stderr were captured into app-state transcript files for operator review".to_string(),
            "agent prompt execution, sidecar launch, terminal control, workspace reads/writes, patches, live MCP calls, config reads, exports, and memory writes remain disabled".to_string(),
        ],
        next_step: "Promote Codex/Hermes task execution only after prompt approval, workspace lease binding, PTY/stream policy, cancellation, rollback, and evidence reconciliation exist.".to_string(),
    };

    let json = serde_json::to_string_pretty(&record)
        .map_err(|error| format!("failed to serialize agent transcript session: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write agent transcript session {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "agent_transcript_session_recorded",
            "id": id,
            "runtime": target.runtime,
            "target": target.target,
            "session_kind": target.session_kind,
            "status": status,
            "pid": pid,
            "exit_code": exit_code,
            "timed_out": timed_out,
            "duration_ms": duration_ms,
            "stdout_pipe_reader_enabled": record.stdout_pipe_reader_enabled,
            "stderr_pipe_reader_enabled": record.stderr_pipe_reader_enabled,
            "timeout_kill_sent": record.timeout_kill_sent,
            "wait_after_kill_ms": record.wait_after_kill_ms,
            "partial_output_captured": record.partial_output_captured,
            "stdout_size_bytes": record.stdout_size_bytes,
            "stderr_size_bytes": record.stderr_size_bytes,
            "process_spawn_enabled": true,
            "transcript_capture_enabled": true,
            "agent_task_execution_enabled": false,
            "sidecar_launch_enabled": false,
            "terminal_enabled": false,
            "workspace_read_enabled": false,
            "workspace_write_enabled": false,
            "patch_apply_enabled": false,
            "live_mcp_call_enabled": false,
            "config_read_enabled": false,
            "export_enabled": false,
            "memory_write_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(record)
}

#[tauri::command]
pub fn run_agent_transcript_session(
    request: AgentTranscriptSessionRequest,
) -> Result<AgentTranscriptSessionResult, String> {
    let timestamp = now_ms()?;
    let requested_runtime = request
        .runtime
        .unwrap_or_else(|| "all".to_string())
        .trim()
        .to_ascii_lowercase();
    let requested_runtime = if requested_runtime.is_empty() {
        "all".to_string()
    } else {
        requested_runtime
    };
    let requested_by = request
        .requested_by
        .unwrap_or_else(|| "operator".to_string())
        .trim()
        .chars()
        .take(120)
        .collect::<String>();
    let requested_by = if requested_by.is_empty() {
        "operator".to_string()
    } else {
        requested_by
    };
    let timeout_ms = request.timeout_ms.unwrap_or(4_000).clamp(500, 10_000);
    let selected_targets: Vec<AgentTranscriptTarget> = agent_transcript_targets()
        .into_iter()
        .filter(|target| {
            requested_runtime == "all"
                || requested_runtime == target.runtime
                || requested_runtime == target.target
                || requested_runtime == target.session_kind
        })
        .collect();

    if selected_targets.is_empty() {
        return Ok(AgentTranscriptSessionResult {
            accepted: false,
            requested_runtime,
            timeout_ms,
            session_count: 0,
            succeeded_count: 0,
            failed_count: 0,
            timed_out_count: 0,
            process_spawn_enabled: true,
            transcript_capture_enabled: false,
            agent_task_execution_enabled: false,
            sidecar_launch_enabled: false,
            terminal_enabled: false,
            workspace_read_enabled: false,
            workspace_write_enabled: false,
            live_mcp_call_enabled: false,
            config_read_enabled: false,
            export_enabled: false,
            memory_write_enabled: false,
            writes_allowed: false,
            execution_enabled: false,
            records: Vec::new(),
            blockers: vec!["No hard-coded Codex/Hermes transcript target matched the request.".to_string()],
            next_step: "Choose all, codex, hermes, version, help, or a fixed agent transcript target id.".to_string(),
        });
    }

    let dir = agent_transcript_sessions_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create agent-transcript-sessions directory {}: {error}",
            dir.display()
        )
    })?;

    let mut records = Vec::new();
    for target in &selected_targets {
        records.push(run_agent_transcript_target(
            target,
            &requested_by,
            timeout_ms,
            timestamp,
            &dir,
        )?);
    }

    let succeeded_count = records
        .iter()
        .filter(|record| record.status == "agent_transcript_session_succeeded")
        .count();
    let timed_out_count = records.iter().filter(|record| record.timed_out).count();
    let failed_count = records.len().saturating_sub(succeeded_count);
    let blockers = records
        .iter()
        .filter(|record| record.status != "agent_transcript_session_succeeded")
        .map(|record| {
            format!(
                "{} transcript session status is {}",
                record.title, record.status
            )
        })
        .collect::<Vec<_>>();

    Ok(AgentTranscriptSessionResult {
        accepted: true,
        requested_runtime,
        timeout_ms,
        session_count: records.len(),
        succeeded_count,
        failed_count,
        timed_out_count,
        process_spawn_enabled: true,
        transcript_capture_enabled: true,
        agent_task_execution_enabled: false,
        sidecar_launch_enabled: false,
        terminal_enabled: false,
        workspace_read_enabled: false,
        workspace_write_enabled: false,
        live_mcp_call_enabled: false,
        config_read_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        records,
        blockers,
        next_step: "Use captured Codex/Hermes transcript evidence to wire the task-run approval surface; real prompt execution remains blocked until workspace, PTY, rollback, and reconciliation gates are complete.".to_string(),
    })
}

#[tauri::command]
pub fn list_agent_transcript_sessions() -> Result<Vec<AgentTranscriptSessionRecord>, String> {
    let dir = agent_transcript_sessions_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read agent-transcript-sessions directory {}: {error}",
            dir.display()
        )
    })? {
        let entry =
            entry.map_err(|error| format!("failed to read agent transcript session entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<AgentTranscriptSessionRecord>(&content) {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(40);
    Ok(records)
}

fn unlocked_agent_workspace_root() -> PathBuf {
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    manifest_dir
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or(manifest_dir)
}

fn unlocked_agent_prompt_target(
    runtime: &str,
    workspace_root: &Path,
    prompt: &str,
) -> Option<UnlockedAgentPromptTarget> {
    let workspace_arg = workspace_root.display().to_string();
    match runtime {
        "codex" | "codex-write" | "codex-workspace-write" => {
            let args = vec![
                "exec".to_string(),
                "--json".to_string(),
                "--sandbox".to_string(),
                "workspace-write".to_string(),
                "--skip-git-repo-check".to_string(),
                "--ephemeral".to_string(),
                "-C".to_string(),
                workspace_arg.clone(),
            ];
            let argv_redacted = vec![
                "codex".to_string(),
                "exec".to_string(),
                "--json".to_string(),
                "--sandbox".to_string(),
                "workspace-write".to_string(),
                "--skip-git-repo-check".to_string(),
                "--ephemeral".to_string(),
                "-C".to_string(),
                workspace_arg,
                "<prompt:stdin>".to_string(),
            ];
            Some(UnlockedAgentPromptTarget {
                runtime: "codex-workspace-write",
                title: "Codex workspace-write prompt",
                binary: "codex",
                sandbox_policy: "workspace-write",
                argv_redacted,
                args,
                prompt_stdin: Some(prompt.to_string()),
                workspace_read_enabled: true,
                workspace_write_enabled: true,
                file_write_enabled: true,
                writes_allowed: true,
            })
        }
        "codex-read" | "codex-readonly" | "codex-read-only" => {
            let args = vec![
                "exec".to_string(),
                "--json".to_string(),
                "--sandbox".to_string(),
                "read-only".to_string(),
                "--skip-git-repo-check".to_string(),
                "--ephemeral".to_string(),
                "-C".to_string(),
                workspace_arg.clone(),
            ];
            let argv_redacted = vec![
                "codex".to_string(),
                "exec".to_string(),
                "--json".to_string(),
                "--sandbox".to_string(),
                "read-only".to_string(),
                "--skip-git-repo-check".to_string(),
                "--ephemeral".to_string(),
                "-C".to_string(),
                workspace_arg,
                "<prompt:stdin>".to_string(),
            ];
            Some(UnlockedAgentPromptTarget {
                runtime: "codex-readonly",
                title: "Codex read-only prompt",
                binary: "codex",
                sandbox_policy: "read-only",
                argv_redacted,
                args,
                prompt_stdin: Some(prompt.to_string()),
                workspace_read_enabled: true,
                workspace_write_enabled: false,
                file_write_enabled: false,
                writes_allowed: false,
            })
        }
        "hermes" | "hermes-chat" | "hermes-quiet" => {
            let args = vec![
                "chat".to_string(),
                "-Q".to_string(),
                "--max-turns".to_string(),
                "4".to_string(),
                "--source".to_string(),
                "gravity-omega-native".to_string(),
                "--query".to_string(),
                prompt.to_string(),
            ];
            let argv_redacted = vec![
                "hermes".to_string(),
                "chat".to_string(),
                "-Q".to_string(),
                "--max-turns".to_string(),
                "4".to_string(),
                "--source".to_string(),
                "gravity-omega-native".to_string(),
                "--query".to_string(),
                "<prompt>".to_string(),
            ];
            Some(UnlockedAgentPromptTarget {
                runtime: "hermes-chat",
                title: "Hermes quiet chat prompt",
                binary: "hermes",
                sandbox_policy: "hermes-cli",
                argv_redacted,
                args,
                prompt_stdin: None,
                workspace_read_enabled: true,
                workspace_write_enabled: false,
                file_write_enabled: false,
                writes_allowed: false,
            })
        }
        _ => None,
    }
}

fn unlocked_agent_prompt_stdin_mode(target: &UnlockedAgentPromptTarget) -> Stdio {
    if target.prompt_stdin.is_some() {
        Stdio::piped()
    } else {
        Stdio::null()
    }
}

fn write_unlocked_agent_prompt_stdin(
    child: &mut Child,
    target: &UnlockedAgentPromptTarget,
) -> Result<(), String> {
    let Some(prompt) = target.prompt_stdin.as_deref() else {
        return Ok(());
    };
    let Some(mut stdin) = child.stdin.take() else {
        return Err(format!(
            "failed to open prompt stdin for {}",
            target.runtime
        ));
    };
    stdin.write_all(prompt.as_bytes()).map_err(|error| {
        format!(
            "failed to write prompt stdin for {}: {error}",
            target.runtime
        )
    })?;
    stdin.flush().map_err(|error| {
        format!(
            "failed to flush prompt stdin for {}: {error}",
            target.runtime
        )
    })
}

#[allow(clippy::too_many_arguments)]
fn write_unlocked_agent_prompt_session_record(
    target: &UnlockedAgentPromptTarget,
    requested_by: &str,
    task_run_id: &str,
    task_run_found: bool,
    prompt_preview: &str,
    prompt_size_bytes: u64,
    workspace_root: &Path,
    timestamp: u64,
    duration_ms: u64,
    pid: Option<u32>,
    exit_code: Option<i32>,
    timed_out: bool,
    bounded_execution_performed: bool,
    stdout_bytes: Vec<u8>,
    stderr_bytes: Vec<u8>,
    status: String,
    record_path: PathBuf,
    log_path: PathBuf,
    stdout_transcript_path: PathBuf,
    stderr_transcript_path: PathBuf,
) -> Result<UnlockedAgentPromptSessionRecord, String> {
    let stdout_full = String::from_utf8_lossy(&stdout_bytes).to_string();
    let stderr_full = String::from_utf8_lossy(&stderr_bytes).to_string();
    fs::write(&stdout_transcript_path, &stdout_full).map_err(|error| {
        format!(
            "failed to write unlocked agent stdout transcript {}: {error}",
            stdout_transcript_path.display()
        )
    })?;
    fs::write(&stderr_transcript_path, &stderr_full).map_err(|error| {
        format!(
            "failed to write unlocked agent stderr transcript {}: {error}",
            stderr_transcript_path.display()
        )
    })?;

    let id = record_path
        .file_stem()
        .and_then(|value| value.to_str())
        .unwrap_or("unlocked-agent-prompt-session")
        .to_string();
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let stdout_transcript_display = stdout_transcript_path.display().to_string();
    let stderr_transcript_display = stderr_transcript_path.display().to_string();
    let workspace_root_display = workspace_root.display().to_string();

    let mut reasons = vec![
        "operator-unlocked real agent prompt execution was requested".to_string(),
        "argv was built with Command::new and fixed arguments; no shell interpolation is used".to_string(),
        "stdout and stderr are captured into app-state transcript files".to_string(),
    ];
    if target.prompt_stdin.is_some() {
        reasons.push(
            "large prompt text was delivered through child stdin instead of process argv".to_string(),
        );
    } else {
        reasons.push(
            "this runtime target uses its documented query argument with the prompt redacted in records".to_string(),
        );
    }
    if target.writes_allowed {
        reasons.push(
            "workspace-write mode can mutate files under the rebuild workspace root".to_string(),
        );
    } else {
        reasons.push("this runtime target does not explicitly enable workspace writes".to_string());
    }

    let record = UnlockedAgentPromptSessionRecord {
        id: id.clone(),
        runtime: target.runtime.to_string(),
        title: target.title.to_string(),
        binary: target.binary.to_string(),
        argv_redacted: target.argv_redacted.clone(),
        sandbox_policy: target.sandbox_policy.to_string(),
        workspace_root: workspace_root_display,
        task_run_id: task_run_id.to_string(),
        task_run_found,
        prompt_preview: prompt_preview.to_string(),
        prompt_size_bytes,
        requested_by: requested_by.to_string(),
        status: status.clone(),
        pid,
        exit_code,
        timed_out,
        duration_ms,
        stdout: trim_probe_text(&stdout_bytes),
        stderr: trim_probe_text(&stderr_bytes),
        stdout_size_bytes: stdout_bytes.len() as u64,
        stderr_size_bytes: stderr_bytes.len() as u64,
        stdout_transcript_path: stdout_transcript_display.clone(),
        stderr_transcript_path: stderr_transcript_display.clone(),
        process_spawn_enabled: true,
        transcript_capture_enabled: true,
        agent_prompt_execution_enabled: true,
        bounded_execution_performed,
        sidecar_launch_enabled: false,
        terminal_enabled: false,
        workspace_read_enabled: target.workspace_read_enabled,
        workspace_write_enabled: target.workspace_write_enabled,
        file_write_enabled: target.file_write_enabled,
        patch_apply_enabled: false,
        live_mcp_call_enabled: false,
        config_read_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: target.writes_allowed,
        execution_enabled: true,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Use this transcript ledger to compare Codex and Hermes outputs, then wire streaming, cancel, rollback, and joint reconciliation around the same unlocked runner.".to_string(),
    };

    let json = serde_json::to_string_pretty(&record)
        .map_err(|error| format!("failed to serialize unlocked agent prompt session: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write unlocked agent prompt session {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "unlocked_agent_prompt_session_recorded",
            "id": id,
            "runtime": target.runtime,
            "status": status,
            "task_run_id": task_run_id,
            "task_run_found": task_run_found,
            "pid": pid,
            "exit_code": exit_code,
            "timed_out": timed_out,
            "duration_ms": duration_ms,
            "stdout_size_bytes": record.stdout_size_bytes,
            "stderr_size_bytes": record.stderr_size_bytes,
            "process_spawn_enabled": true,
            "transcript_capture_enabled": true,
            "agent_prompt_execution_enabled": true,
            "bounded_execution_performed": bounded_execution_performed,
            "workspace_read_enabled": record.workspace_read_enabled,
            "workspace_write_enabled": record.workspace_write_enabled,
            "file_write_enabled": record.file_write_enabled,
            "writes_allowed": record.writes_allowed,
            "execution_enabled": true,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(record)
}

fn run_unlocked_agent_prompt_target(
    target: &UnlockedAgentPromptTarget,
    requested_by: &str,
    task_run_id: &str,
    task_run_found: bool,
    prompt_preview: &str,
    prompt_size_bytes: u64,
    timeout_ms: u64,
    timestamp: u64,
    dir: &Path,
    workspace_root: &Path,
) -> Result<UnlockedAgentPromptSessionRecord, String> {
    if target.binary.contains('/')
        || target.binary.contains('\\')
        || target.binary.chars().any(char::is_whitespace)
    {
        return Err(format!(
            "unlocked agent prompt target {} failed hard-coded binary validation",
            target.runtime
        ));
    }

    let id = format!(
        "unlocked-agent-prompt-session-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug_limit(target.runtime, 48)
    );
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let stdout_transcript_path = dir.join(format!("{id}.stdout.txt"));
    let stderr_transcript_path = dir.join(format!("{id}.stderr.txt"));

    let started = Instant::now();
    let mut pid = None;
    let mut exit_code = None;
    let mut timed_out = false;
    let stdout_bytes: Vec<u8>;
    let stderr_bytes: Vec<u8>;
    let status: String;
    let mut bounded_execution_performed = false;

    match Command::new(target.binary)
        .args(&target.args)
        .current_dir(workspace_root)
        .stdin(unlocked_agent_prompt_stdin_mode(target))
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
    {
        Ok(mut child) => {
            bounded_execution_performed = true;
            pid = Some(child.id());
            if let Err(error) = write_unlocked_agent_prompt_stdin(&mut child, target) {
                let _ = child.kill();
                stdout_bytes = Vec::new();
                stderr_bytes = error.into_bytes();
                status = "unlocked_agent_prompt_session_stdin_failed".to_string();
                return write_unlocked_agent_prompt_session_record(
                    target,
                    requested_by,
                    task_run_id,
                    task_run_found,
                    prompt_preview,
                    prompt_size_bytes,
                    workspace_root,
                    timestamp,
                    started.elapsed().as_millis() as u64,
                    pid,
                    None,
                    false,
                    bounded_execution_performed,
                    stdout_bytes,
                    stderr_bytes,
                    status,
                    record_path,
                    log_path,
                    stdout_transcript_path,
                    stderr_transcript_path,
                );
            }
            loop {
                match child.try_wait() {
                    Ok(Some(_status)) => break,
                    Ok(None) => {
                        if started.elapsed() >= Duration::from_millis(timeout_ms) {
                            timed_out = true;
                            let _ = child.kill();
                            break;
                        }
                        std::thread::sleep(Duration::from_millis(50));
                    }
                    Err(error) => {
                        stdout_bytes = Vec::new();
                        stderr_bytes = error.to_string().into_bytes();
                        status = "unlocked_agent_prompt_session_wait_failed".to_string();
                        return write_unlocked_agent_prompt_session_record(
                            target,
                            requested_by,
                            task_run_id,
                            task_run_found,
                            prompt_preview,
                            prompt_size_bytes,
                            workspace_root,
                            timestamp,
                            started.elapsed().as_millis() as u64,
                            pid,
                            None,
                            false,
                            bounded_execution_performed,
                            stdout_bytes,
                            stderr_bytes,
                            status,
                            record_path,
                            log_path,
                            stdout_transcript_path,
                            stderr_transcript_path,
                        );
                    }
                }
            }

            let output = child.wait_with_output().map_err(|error| {
                format!(
                    "failed to collect unlocked agent prompt session output for {}: {error}",
                    target.runtime
                )
            })?;
            exit_code = output.status.code();
            stdout_bytes = output.stdout;
            stderr_bytes = output.stderr;
            status = if timed_out {
                "unlocked_agent_prompt_session_timed_out"
            } else if output.status.success() {
                "unlocked_agent_prompt_session_succeeded"
            } else {
                "unlocked_agent_prompt_session_failed"
            }
            .to_string();
        }
        Err(error) => {
            stdout_bytes = Vec::new();
            stderr_bytes = error.to_string().into_bytes();
            status = "unlocked_agent_prompt_session_spawn_failed".to_string();
        }
    }

    write_unlocked_agent_prompt_session_record(
        target,
        requested_by,
        task_run_id,
        task_run_found,
        prompt_preview,
        prompt_size_bytes,
        workspace_root,
        timestamp,
        started.elapsed().as_millis() as u64,
        pid,
        exit_code,
        timed_out,
        bounded_execution_performed,
        stdout_bytes,
        stderr_bytes,
        status,
        record_path,
        log_path,
        stdout_transcript_path,
        stderr_transcript_path,
    )
}

#[tauri::command]
pub fn run_unlocked_agent_prompt_session(
    request: UnlockedAgentPromptSessionRequest,
) -> Result<UnlockedAgentPromptSessionResult, String> {
    let timestamp = now_ms()?;
    let requested_runtime = request
        .runtime
        .unwrap_or_else(|| "codex-workspace-write".to_string())
        .trim()
        .to_ascii_lowercase();
    let requested_runtime = if requested_runtime.is_empty() {
        "codex-workspace-write".to_string()
    } else {
        requested_runtime
    };
    let requested_by = request
        .requested_by
        .unwrap_or_else(|| "operator".to_string())
        .trim()
        .chars()
        .take(120)
        .collect::<String>();
    let requested_by = if requested_by.is_empty() {
        "operator".to_string()
    } else {
        requested_by
    };
    let prompt = request
        .prompt
        .unwrap_or_default()
        .trim()
        .chars()
        .take(12_000)
        .collect::<String>();
    if prompt.is_empty() {
        return Ok(UnlockedAgentPromptSessionResult {
            accepted: false,
            requested_runtime,
            timeout_ms: 0,
            session_count: 0,
            succeeded_count: 0,
            failed_count: 0,
            timed_out_count: 0,
            process_spawn_enabled: true,
            transcript_capture_enabled: false,
            agent_prompt_execution_enabled: false,
            bounded_execution_performed: false,
            sidecar_launch_enabled: false,
            terminal_enabled: false,
            workspace_read_enabled: false,
            workspace_write_enabled: false,
            file_write_enabled: false,
            live_mcp_call_enabled: false,
            config_read_enabled: false,
            export_enabled: false,
            memory_write_enabled: false,
            writes_allowed: false,
            execution_enabled: false,
            records: Vec::new(),
            blockers: vec!["Prompt is empty.".to_string()],
            next_step: "Enter a prompt in the Codex/Hermes composer and run the unlocked agent lane again.".to_string(),
        });
    }

    let workspace_root = unlocked_agent_workspace_root();
    let Some(target) = unlocked_agent_prompt_target(&requested_runtime, &workspace_root, &prompt) else {
        return Ok(UnlockedAgentPromptSessionResult {
            accepted: false,
            requested_runtime,
            timeout_ms: 0,
            session_count: 0,
            succeeded_count: 0,
            failed_count: 0,
            timed_out_count: 0,
            process_spawn_enabled: true,
            transcript_capture_enabled: false,
            agent_prompt_execution_enabled: false,
            bounded_execution_performed: false,
            sidecar_launch_enabled: false,
            terminal_enabled: false,
            workspace_read_enabled: false,
            workspace_write_enabled: false,
            file_write_enabled: false,
            live_mcp_call_enabled: false,
            config_read_enabled: false,
            export_enabled: false,
            memory_write_enabled: false,
            writes_allowed: false,
            execution_enabled: false,
            records: Vec::new(),
            blockers: vec!["Unknown unlocked agent runtime.".to_string()],
            next_step: "Choose codex-workspace-write, codex-readonly, or hermes-chat.".to_string(),
        });
    };
    if let Err(blocker) = hermes_log_write_preflight(&target) {
        return Ok(UnlockedAgentPromptSessionResult {
            accepted: false,
            requested_runtime,
            timeout_ms: 0,
            session_count: 0,
            succeeded_count: 0,
            failed_count: 0,
            timed_out_count: 0,
            process_spawn_enabled: true,
            transcript_capture_enabled: false,
            agent_prompt_execution_enabled: false,
            bounded_execution_performed: false,
            sidecar_launch_enabled: false,
            terminal_enabled: false,
            workspace_read_enabled: target.workspace_read_enabled,
            workspace_write_enabled: target.workspace_write_enabled,
            file_write_enabled: target.file_write_enabled,
            live_mcp_call_enabled: false,
            config_read_enabled: false,
            export_enabled: false,
            memory_write_enabled: false,
            writes_allowed: target.writes_allowed,
            execution_enabled: false,
            records: Vec::new(),
            blockers: vec![blocker],
            next_step: "Fix the Hermes writable log path or run the app outside the read-only wrapper, then retry Hermes.".to_string(),
        });
    }

    let requested_task_id = request
        .task_run_id
        .unwrap_or_default()
        .trim()
        .to_string();
    let task_run = if requested_task_id.is_empty() {
        list_task_runs()?.into_iter().next()
    } else {
        read_task_run_record(&requested_task_id)?
    };
    let task_run_found = task_run.is_some();
    let task_run_id = task_run
        .as_ref()
        .map(|record| record.id.clone())
        .unwrap_or_else(|| {
            if requested_task_id.is_empty() {
                "ad-hoc-unlocked".to_string()
            } else {
                requested_task_id
            }
        });
    let prompt_preview = prompt.chars().take(240).collect::<String>();
    let timeout_ms = request.timeout_ms.unwrap_or(300_000).clamp(1_000, 900_000);
    let dir = unlocked_agent_prompt_sessions_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create unlocked-agent-prompt-sessions directory {}: {error}",
            dir.display()
        )
    })?;

    let record = run_unlocked_agent_prompt_target(
        &target,
        &requested_by,
        &task_run_id,
        task_run_found,
        &prompt_preview,
        prompt.len() as u64,
        timeout_ms,
        timestamp,
        &dir,
        &workspace_root,
    )?;

    let succeeded_count = usize::from(record.status == "unlocked_agent_prompt_session_succeeded");
    let timed_out_count = usize::from(record.timed_out);
    let failed_count = 1usize.saturating_sub(succeeded_count);
    let blockers = if succeeded_count == 1 {
        Vec::new()
    } else {
        vec![format!(
            "{} status is {}",
            record.title, record.status
        )]
    };

    Ok(UnlockedAgentPromptSessionResult {
        accepted: true,
        requested_runtime: target.runtime.to_string(),
        timeout_ms,
        session_count: 1,
        succeeded_count,
        failed_count,
        timed_out_count,
        process_spawn_enabled: true,
        transcript_capture_enabled: true,
        agent_prompt_execution_enabled: true,
        bounded_execution_performed: record.bounded_execution_performed,
        sidecar_launch_enabled: false,
        terminal_enabled: false,
        workspace_read_enabled: record.workspace_read_enabled,
        workspace_write_enabled: record.workspace_write_enabled,
        file_write_enabled: record.file_write_enabled,
        live_mcp_call_enabled: false,
        config_read_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: record.writes_allowed,
        execution_enabled: true,
        records: vec![record],
        blockers,
        next_step: "Run Codex and Hermes prompts from the same composer, compare the captured transcripts, and promote streaming/cancel/rollback around this unlocked runner.".to_string(),
    })
}

const UNLOCKED_AGENT_PROMPT_STREAM_EVENT: &str = "unlocked-agent-prompt-stream";

#[derive(Debug, Clone)]
struct UnlockedAgentPromptStreamProcessState {
    session_id: String,
    runtime: String,
    pid: Option<u32>,
    record_path: String,
    log_path: String,
    started_at_ms: u64,
    cancel_requested: bool,
    cancel_requested_at_ms: Option<u64>,
    cancel_requested_by: String,
    cancel_reason: String,
}

static UNLOCKED_AGENT_PROMPT_STREAM_PROCESSES: OnceLock<
    Mutex<BTreeMap<String, UnlockedAgentPromptStreamProcessState>>,
> = OnceLock::new();

fn unlocked_agent_prompt_stream_processes(
) -> &'static Mutex<BTreeMap<String, UnlockedAgentPromptStreamProcessState>> {
    UNLOCKED_AGENT_PROMPT_STREAM_PROCESSES.get_or_init(|| Mutex::new(BTreeMap::new()))
}

fn with_unlocked_agent_prompt_stream_processes<T>(
    f: impl FnOnce(&mut BTreeMap<String, UnlockedAgentPromptStreamProcessState>) -> T,
) -> Result<T, String> {
    let mut guard = unlocked_agent_prompt_stream_processes()
        .lock()
        .map_err(|_| "unlocked agent stream process registry lock poisoned".to_string())?;
    Ok(f(&mut guard))
}

fn register_unlocked_agent_prompt_stream_process(
    state: UnlockedAgentPromptStreamProcessState,
) -> Result<(), String> {
    with_unlocked_agent_prompt_stream_processes(|processes| {
        processes.insert(state.session_id.clone(), state);
    })
}

fn update_unlocked_agent_prompt_stream_pid(session_id: &str, pid: u32) -> Result<(), String> {
    with_unlocked_agent_prompt_stream_processes(|processes| {
        if let Some(state) = processes.get_mut(session_id) {
            state.pid = Some(pid);
        }
    })
}

fn mark_unlocked_agent_prompt_stream_cancel_requested(
    session_id: &str,
    requested_by: &str,
    reason: &str,
    timestamp: u64,
) -> Result<Option<UnlockedAgentPromptStreamProcessState>, String> {
    with_unlocked_agent_prompt_stream_processes(|processes| {
        let state = processes.get_mut(session_id)?;
        state.cancel_requested = true;
        state.cancel_requested_at_ms = Some(timestamp);
        state.cancel_requested_by = requested_by.to_string();
        state.cancel_reason = reason.to_string();
        Some(state.clone())
    })
}

fn unlocked_agent_prompt_stream_cancel_requested(session_id: &str) -> bool {
    with_unlocked_agent_prompt_stream_processes(|processes| {
        processes
            .get(session_id)
            .map(|state| state.cancel_requested)
            .unwrap_or(false)
    })
    .unwrap_or(false)
}

fn unregister_unlocked_agent_prompt_stream_process(session_id: &str) {
    let _ = with_unlocked_agent_prompt_stream_processes(|processes| {
        processes.remove(session_id);
    });
}

fn emit_unlocked_agent_prompt_stream_event(
    app: &tauri::AppHandle,
    log_path: &PathBuf,
    event: UnlockedAgentPromptSessionStreamEvent,
) {
    let _ = app.emit(UNLOCKED_AGENT_PROMPT_STREAM_EVENT, event.clone());
    let _ = write_jsonl_event(
        log_path,
        serde_json::json!({
            "session_id": event.session_id,
            "runtime": event.runtime,
            "kind": event.kind,
            "line": event.line,
            "status": event.status,
            "exit_code": event.exit_code,
            "record_path": event.record_path,
            "created_at_ms": event.created_at_ms
        }),
    );
}

#[tauri::command]
pub fn cancel_unlocked_agent_prompt_session_stream(
    request: UnlockedAgentPromptSessionCancelRequest,
) -> Result<UnlockedAgentPromptSessionCancelResult, String> {
    let timestamp = now_ms()?;
    let session_id = request.session_id.trim().to_string();
    let requested_by = request
        .requested_by
        .unwrap_or_else(|| "gravity-omega-product-ui".to_string())
        .trim()
        .chars()
        .take(120)
        .collect::<String>();
    let reason = request
        .reason
        .unwrap_or_else(|| "operator recovery requested".to_string())
        .trim()
        .chars()
        .take(260)
        .collect::<String>();

    if session_id.is_empty() {
        return Ok(UnlockedAgentPromptSessionCancelResult {
            accepted: false,
            status: "unlocked_agent_prompt_stream_cancel_rejected".to_string(),
            session_id,
            runtime: String::new(),
            pid: None,
            record_path: String::new(),
            log_path: String::new(),
            process_spawn_enabled: true,
            process_control_enabled: false,
            agent_prompt_execution_enabled: true,
            cancellation_requested: false,
            kill_delegated_to_stream_worker: false,
            created_at_ms: timestamp,
            blockers: vec![
                "session_id is required to cancel a tracked unlocked-agent stream".to_string(),
            ],
            next_step: "Retry recovery after an agent stream has emitted a session id.".to_string(),
        });
    }

    let Some(state) = mark_unlocked_agent_prompt_stream_cancel_requested(
        &session_id,
        &requested_by,
        &reason,
        timestamp,
    )?
    else {
        return Ok(UnlockedAgentPromptSessionCancelResult {
            accepted: false,
            status: "unlocked_agent_prompt_stream_cancel_not_found".to_string(),
            session_id,
            runtime: String::new(),
            pid: None,
            record_path: String::new(),
            log_path: String::new(),
            process_spawn_enabled: true,
            process_control_enabled: false,
            agent_prompt_execution_enabled: true,
            cancellation_requested: false,
            kill_delegated_to_stream_worker: false,
            created_at_ms: timestamp,
            blockers: vec![
                "No tracked active unlocked-agent stream matched the requested session id."
                    .to_string(),
            ],
            next_step: "The UI can still recover its visible gate, but no backend process cancellation was requested.".to_string(),
        });
    };

    let status = if state.pid.is_some() {
        "unlocked_agent_prompt_stream_cancel_requested"
    } else {
        "unlocked_agent_prompt_stream_cancel_requested_pending_spawn"
    }
    .to_string();
    let _ = write_jsonl_event(
        &PathBuf::from(&state.log_path),
        serde_json::json!({
            "event": "unlocked_agent_prompt_stream_cancel_requested",
            "session_id": state.session_id.clone(),
            "runtime": state.runtime.clone(),
            "pid": state.pid,
            "status": status.clone(),
            "requested_by": requested_by,
            "reason": reason,
            "started_at_ms": state.started_at_ms,
            "created_at_ms": timestamp,
            "process_control_enabled": true,
            "kill_delegated_to_stream_worker": true
        }),
    );

    Ok(UnlockedAgentPromptSessionCancelResult {
        accepted: true,
        status,
        session_id: state.session_id,
        runtime: state.runtime,
        pid: state.pid,
        record_path: state.record_path,
        log_path: state.log_path,
        process_spawn_enabled: true,
        process_control_enabled: true,
        agent_prompt_execution_enabled: true,
        cancellation_requested: true,
        kill_delegated_to_stream_worker: true,
        created_at_ms: timestamp,
        blockers: Vec::new(),
        next_step: "The tracked stream worker will terminate its own child process and record a cancelled final status.".to_string(),
    })
}

fn read_unlocked_agent_prompt_stream<R: Read + Send + 'static>(
    app: tauri::AppHandle,
    log_path: PathBuf,
    session_id: String,
    runtime: String,
    kind: &'static str,
    reader: R,
    record_path: String,
    created_at_ms: u64,
) -> String {
    let mut transcript = String::new();
    for line in BufReader::new(reader).lines() {
        let line = match line {
            Ok(line) => line,
            Err(error) => format!("stream read failed: {error}"),
        };
        transcript.push_str(&line);
        transcript.push('\n');
        emit_unlocked_agent_prompt_stream_event(
            &app,
            &log_path,
            UnlockedAgentPromptSessionStreamEvent {
                session_id: session_id.clone(),
                runtime: runtime.clone(),
                kind: kind.to_string(),
                line,
                status: "unlocked_agent_prompt_stream_output".to_string(),
                exit_code: None,
                record_path: record_path.clone(),
                log_path: log_path.display().to_string(),
                created_at_ms,
            },
        );
    }
    transcript
}

