#[tauri::command]
pub fn workspace_editor_navigation_lane() -> Result<WorkspaceEditorNavigationLane, String> {
    let workspace_inspections = list_workspace_inspection_records()?;
    let workspace_previews = list_workspace_preview_records()?;
    let tree_metadata = list_workspace_tree_metadata_records()?;
    let file_previews = list_workspace_file_content_preview_records()?;
    let editor_tabs = list_workspace_editor_tab_states()?;
    let edit_preflights = list_workspace_edit_preflights()?;
    let write_policies = list_workspace_write_approval_policies()?;
    let write_approvals = list_workspace_write_approvals()?;
    let buffer_drafts = list_workspace_writable_buffer_drafts()?;
    let dirty_preflights = list_workspace_dirty_transition_preflights()?;

    let items = vec![
        workspace_editor_navigation_item(
            "workspace-inspection",
            "Workspace inspection",
            "read-only workspace boundary",
            workspace_inspections.len(),
            "Record or review read-only workspace scope before preview, tree, search, or diff surfaces.",
        ),
        workspace_editor_navigation_item(
            "workspace-preview",
            "Workspace preview",
            "read-only workspace summary",
            workspace_previews.len(),
            "Review the preview summary before tree metadata or file preview records are trusted.",
        ),
        workspace_editor_navigation_item(
            "tree-metadata",
            "Tree metadata",
            "scoped file tree",
            tree_metadata.len(),
            "Use recorded tree metadata to drive navigation before any live watcher or write gate exists.",
        ),
        workspace_editor_navigation_item(
            "file-preview",
            "File preview",
            "bounded text preview",
            file_previews.len(),
            "Open persisted bounded previews before creating editor tab state.",
        ),
        workspace_editor_navigation_item(
            "editor-tab",
            "Editor tab",
            "read-only buffer state",
            editor_tabs.len(),
            "Link read-only tab state to later buffer materialization before any editable buffer exists.",
        ),
        workspace_editor_navigation_item(
            "edit-save-gate",
            "Edit/save preflight",
            "disabled mutation gate",
            edit_preflights.len(),
            "Review blocked edit/save intent evidence before write policy or approval records advance.",
        ),
        workspace_editor_navigation_item(
            "write-policy",
            "Write policy",
            "disabled write policy",
            write_policies.len(),
            "Keep write policy visible as evidence only until approvals and tests exist.",
        ),
        workspace_editor_navigation_item(
            "write-approval",
            "Write approval",
            "disabled approval evidence",
            write_approvals.len(),
            "Keep approval records visible without allowing file writes or patch application.",
        ),
        workspace_editor_navigation_item(
            "buffer-draft",
            "Buffer draft",
            "disabled writable-buffer draft",
            buffer_drafts.len(),
            "Review draft evidence without materializing writable buffers.",
        ),
        workspace_editor_navigation_item(
            "dirty-state",
            "Dirty-state preflight",
            "disabled dirty transition",
            dirty_preflights.len(),
            "Keep dirty-state transitions preflighted before save, patch, or file writes can exist.",
        ),
    ];
    let ready_count = items.iter().filter(|item| item.ready).count();
    let live_gate_disabled_count = items
        .iter()
        .filter(|item| {
            item.read_only
                && !item.live_probe_enabled
                && !item.live_call_enabled
                && !item.file_write_enabled
                && !item.patch_apply_enabled
                && !item.terminal_enabled
                && !item.process_spawn_enabled
                && !item.desktop_control_enabled
                && !item.config_read_enabled
                && !item.capture_enabled
                && !item.export_enabled
                && !item.memory_write_enabled
                && !item.writes_allowed
                && !item.execution_enabled
        })
        .count();

    Ok(WorkspaceEditorNavigationLane {
        status: "workspace_editor_navigation_lane_read_only",
        item_count: items.len(),
        ready_count,
        read_only: true,
        live_gate_disabled_count,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        desktop_control_enabled: false,
        config_read_enabled: false,
        capture_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        items,
        reasons: vec![
            "navigation lane links existing persisted workspace/editor records without creating new records or reading file contents",
            "file writes, patch application, process spawn, terminal control, desktop control, live MCP, config read, capture, export, memory writes, and execution remain disabled",
        ],
        next_slice: "Turn the navigation lane into a real read-only editor shell layout before any workspace mutation, save, or patch path exists.",
    })
}

fn workspace_editor_navigation_record_count(
    items: &[WorkspaceEditorNavigationLaneItem],
    id: &str,
) -> usize {
    items
        .iter()
        .find(|item| item.id == id)
        .map(|item| item.record_count)
        .unwrap_or(0)
}

