#[tauri::command]
pub fn workspace_editor_shell_focus_model() -> Result<WorkspaceEditorShellFocusModel, String> {
    let bindings = workspace_editor_shell_bindings()?;
    let workspace_tree = workspace_editor_shell_binding_ref(&bindings.bindings, "workspace-tree")?;
    let file_preview = workspace_editor_shell_binding_ref(&bindings.bindings, "file-preview")?;
    let tab_buffer = workspace_editor_shell_binding_ref(&bindings.bindings, "tab-buffer")?;
    let mutation_gates = workspace_editor_shell_binding_ref(&bindings.bindings, "mutation-gates")?;

    let active_panel_id = if tab_buffer.ready {
        "tab-buffer"
    } else if file_preview.ready {
        "file-preview"
    } else if workspace_tree.ready {
        "workspace-tree"
    } else {
        "mutation-gates"
    };
    let active_target_id = workspace_editor_shell_binding_ref(&bindings.bindings, active_panel_id)?
        .summary_target_id;

    let items = vec![
        workspace_editor_shell_focus_item(
            workspace_tree,
            3,
            "Use workspace tree focus when no file preview or tab buffer is ready.",
            "root focus has no panel dependency",
            active_panel_id,
        ),
        workspace_editor_shell_focus_item(
            file_preview,
            2,
            "Use file preview focus when a bounded preview exists but no editor tab is ready.",
            "depends on workspace tree binding",
            active_panel_id,
        ),
        workspace_editor_shell_focus_item(
            tab_buffer,
            1,
            "Prefer tab buffer focus when read-only editor tab state is ready.",
            "depends on workspace tree and file preview bindings",
            active_panel_id,
        ),
        workspace_editor_shell_focus_item(
            mutation_gates,
            4,
            "Use mutation gate focus only to explain blocked edit, save, write, draft, and dirty-state evidence.",
            "depends on workspace tree, file preview, and tab buffer bindings",
            active_panel_id,
        ),
    ];
    let ready_focus_count = items.iter().filter(|item| item.ready).count();
    let disabled_gate_count = items
        .iter()
        .filter(|item| {
            item.read_only
                && !item.file_write_enabled
                && !item.patch_apply_enabled
                && !item.terminal_enabled
                && !item.process_spawn_enabled
                && !item.desktop_control_enabled
                && !item.live_mcp_call_enabled
                && !item.socket_enabled
                && !item.config_read_enabled
                && !item.capture_enabled
                && !item.export_enabled
                && !item.memory_write_enabled
                && !item.writes_allowed
                && !item.execution_enabled
        })
        .count();

    Ok(WorkspaceEditorShellFocusModel {
        status: "workspace_editor_shell_focus_model_read_only",
        focus_count: items.len(),
        ready_focus_count,
        active_panel_id,
        active_target_id,
        binding_count: bindings.binding_count,
        read_only: true,
        disabled_gate_count,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        desktop_control_enabled: false,
        live_mcp_call_enabled: false,
        socket_enabled: false,
        config_read_enabled: false,
        capture_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        items,
        reasons: vec![
            "focus model chooses a read-only panel target from shell bindings only",
            "focus metadata never moves cursor state, opens files, writes files, applies patches, spawns terminal/processes, controls desktop, calls MCP, connects sockets, captures, exports, writes memory, or executes anything",
        ],
        next_slice: "Use the focus model to add keyboard-navigation metadata before any live editor action, save, patch, terminal, process, desktop, or MCP call path exists.",
    })
}

