#[tauri::command]
pub fn workspace_editor_keyboard_navigation_map(
) -> Result<WorkspaceEditorKeyboardNavigationMap, String> {
    let focus = workspace_editor_shell_focus_model()?;
    let mut ordered_focus_items: Vec<&WorkspaceEditorShellFocusItem> = focus.items.iter().collect();
    ordered_focus_items.sort_by_key(|item| item.focus_rank);

    if ordered_focus_items.is_empty() {
        return Err("workspace editor focus model has no items".to_string());
    }

    let mut items = Vec::with_capacity(ordered_focus_items.len());
    for (index, current) in ordered_focus_items.iter().enumerate() {
        let previous =
            ordered_focus_items[(index + ordered_focus_items.len() - 1) % ordered_focus_items.len()];
        let next = ordered_focus_items[(index + 1) % ordered_focus_items.len()];
        items.push(workspace_editor_keyboard_navigation_item(
            current, previous, next,
        ));
    }

    let ready_navigation_count = items.iter().filter(|item| item.ready).count();
    let disabled_gate_count = items
        .iter()
        .filter(|item| {
            item.read_only
                && !item.focus_move_enabled
                && !item.key_listener_enabled
                && !item.file_write_enabled
                && !item.patch_apply_enabled
                && !item.terminal_enabled
                && !item.process_spawn_enabled
                && !item.desktop_control_enabled
                && !item.live_mcp_call_enabled
                && !item.socket_enabled
                && !item.config_read_enabled
                && !item.capture_enabled
                && !item.export_enabled
                && !item.memory_write_enabled
                && !item.writes_allowed
                && !item.execution_enabled
        })
        .count();

    Ok(WorkspaceEditorKeyboardNavigationMap {
        status: "workspace_editor_keyboard_navigation_map_read_only",
        navigation_count: items.len(),
        ready_navigation_count,
        active_panel_id: focus.active_panel_id,
        active_target_id: focus.active_target_id,
        focus_count: focus.focus_count,
        reserved_key_count: 4,
        read_only: true,
        disabled_gate_count,
        focus_move_enabled: false,
        key_listener_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        desktop_control_enabled: false,
        live_mcp_call_enabled: false,
        socket_enabled: false,
        config_read_enabled: false,
        capture_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        items,
        key_reservations: vec![
            "Alt+Down reserves next editor-shell panel traversal",
            "Alt+Up reserves previous editor-shell panel traversal",
            "Home reserves first editor-shell panel traversal",
            "End reserves final editor-shell panel traversal",
        ],
        reasons: vec![
            "keyboard map is derived from read-only focus metadata and does not install key listeners",
            "reserved keys are documentation only until explicit focus movement approval and tests exist",
            "navigation metadata never writes files, applies patches, spawns terminal/processes, controls desktop, calls MCP, connects sockets, captures, exports, writes memory, or executes anything",
        ],
        next_slice: "Use the keyboard navigation map to define a read-only panel command palette before any live focus movement, editable buffer, save, patch, terminal, process, desktop, or MCP path exists.",
    })
}

