#[tauri::command]
pub fn workspace_editor_command_search_map() -> Result<WorkspaceEditorCommandSearchMap, String> {
    let palette = workspace_editor_command_palette_map()?;
    let groups = palette
        .items
        .iter()
        .map(|item| workspace_editor_command_search_group(item, palette.active_command_id))
        .collect::<Vec<_>>();

    let command_count = groups.iter().map(|group| group.command_count).sum();
    let disabled_command_count = groups
        .iter()
        .map(|group| group.disabled_command_count)
        .sum();
    let search_token_count = groups
        .iter()
        .map(|group| group.search_tokens.len())
        .sum();
    let action_bound_count = groups.iter().filter(|group| group.action_bound).count();
    let hotkey_bound_count = groups.iter().filter(|group| group.hotkey_bound).count();
    let active_group_id = groups
        .iter()
        .find(|group| group.active_group)
        .map(|group| group.group_id)
        .unwrap_or("unknown");
    let disabled_gate_count = groups
        .iter()
        .filter(|group| {
            group.read_only
                && group.search_index_ready
                && !group.query_binding_enabled
                && !group.action_bound
                && !group.hotkey_bound
                && !group.file_write_enabled
                && !group.patch_apply_enabled
                && !group.terminal_enabled
                && !group.process_spawn_enabled
                && !group.desktop_control_enabled
                && !group.live_mcp_call_enabled
                && !group.socket_enabled
                && !group.config_read_enabled
                && !group.capture_enabled
                && !group.export_enabled
                && !group.memory_write_enabled
                && !group.writes_allowed
                && !group.execution_enabled
        })
        .count();

    Ok(WorkspaceEditorCommandSearchMap {
        status: "workspace_editor_command_search_map_read_only",
        group_count: groups.len(),
        command_count,
        disabled_command_count,
        search_token_count,
        active_group_id,
        active_command_id: palette.active_command_id,
        palette_command_count: palette.command_count,
        read_only: true,
        disabled_gate_count,
        query_binding_enabled: false,
        action_bound_count,
        hotkey_bound_count,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        desktop_control_enabled: false,
        live_mcp_call_enabled: false,
        socket_enabled: false,
        config_read_enabled: false,
        capture_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        groups,
        reasons: vec![
            "search map groups disabled palette commands into user-facing discovery lanes",
            "search tokens are static metadata only; no live query listener, input binding, command execution, file read, save, patch, terminal/process, desktop, MCP, socket, capture, export, or memory path is active",
            "grouping/search metadata is intentionally larger and more product-facing than another prerequisite-only dry-run slice",
        ],
        next_slice: "Use the command search map to create a read-only run view for Codex/Hermes coordination before any command binding, editable buffer, save, patch, terminal, process, desktop, or MCP path exists.",
    })
}

