#[tauri::command]
pub fn record_sovereign_docs_preview(
    request: SovereignDocsPreviewRequest,
) -> Result<SovereignDocsPreviewRecord, String> {
    let timestamp = now_ms()?;
    let source_path = prompt_preview(
        if request.source_path.trim().is_empty() {
            "active Markdown buffer"
        } else {
            request.source_path.trim()
        },
        180,
    );
    let requested_by = request
        .requested_by
        .as_deref()
        .map(|value| prompt_preview(value, 96))
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| "sovereign-docs-preview".to_string());
    let (markdown, markdown_truncated) = truncate_utf8_bytes(&request.markdown, 524_288);
    let title = sovereign_docs_markdown_title(&markdown);
    let line_count = markdown.replace("\r\n", "\n").lines().count();
    let word_count = markdown.split_whitespace().count();
    let heading_count = markdown
        .lines()
        .filter(|line| {
            let trimmed = line.trim_start();
            let marks = trimmed.chars().take_while(|ch| *ch == '#').count();
            (1..=4).contains(&marks) && trimmed.chars().nth(marks) == Some(' ')
        })
        .count();
    let preview_html = build_sovereign_docs_preview_html(&markdown, &source_path);
    let self_contained = sovereign_docs_self_contained(&preview_html);
    let mut blockers = Vec::new();
    if markdown_truncated {
        blockers.push("markdown was truncated to the 512 KiB preview record limit".to_string());
    }
    if !self_contained {
        blockers.push("preview html contains forbidden external or script references".to_string());
    }
    let id = format!(
        "sovereign-docs-preview-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug_limit(&source_path, 40)
    );
    let dir = sovereign_docs_previews_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create Sovereign Docs preview directory {}: {error}",
            dir.display()
        )
    })?;
    let preview_html_path = dir.join(format!("{id}.html"));
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join("sovereign-docs-previews.jsonl");
    fs::write(&preview_html_path, preview_html.as_bytes()).map_err(|error| {
        format!(
            "failed to write Sovereign Docs preview html {}: {error}",
            preview_html_path.display()
        )
    })?;
    let status = if blockers.is_empty() {
        "sovereign_docs_preview_recorded"
    } else {
        "sovereign_docs_preview_recorded_with_gaps"
    };
    let record = SovereignDocsPreviewRecord {
        id,
        status: status.to_string(),
        requested_by,
        source_path,
        title,
        markdown_size_bytes: markdown.len(),
        markdown_truncated,
        line_count,
        word_count,
        heading_count,
        preview_html_size_bytes: preview_html.len(),
        preview_html,
        preview_html_path: preview_html_path.display().to_string(),
        record_path: record_path.display().to_string(),
        log_path: log_path.display().to_string(),
        live_preview: request.live.unwrap_or(false),
        renderer: "gravity-omega-sovereign-docs-html-v1".to_string(),
        self_contained,
        network_access_enabled: false,
        pdf_export_enabled: false,
        external_asset_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        process_spawn_enabled: false,
        desktop_control_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        blockers,
        next_step: "Use this print-ready HTML preview in the Artifact panel; enable real PDF export only after a bounded renderer sidecar, export policy, and tests exist.".to_string(),
    };
    fs::write(
        &record_path,
        serde_json::to_string_pretty(&record)
            .map_err(|error| format!("failed to serialize Sovereign Docs preview: {error}"))?,
    )
    .map_err(|error| {
        format!(
            "failed to write Sovereign Docs preview record {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "sovereign_docs_preview_recorded",
            "id": &record.id,
            "status": &record.status,
            "source_path": &record.source_path,
            "title": &record.title,
            "line_count": record.line_count,
            "word_count": record.word_count,
            "heading_count": record.heading_count,
            "preview_html_path": &record.preview_html_path,
            "self_contained": record.self_contained,
            "network_access_enabled": false,
            "pdf_export_enabled": false,
            "file_write_enabled": false,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;
    Ok(record)
}

#[tauri::command]
pub fn list_sovereign_docs_previews() -> Result<Vec<SovereignDocsPreviewRecord>, String> {
    let dir = sovereign_docs_previews_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }
    let mut records = Vec::new();
    for entry in fs::read_dir(&dir)
        .map_err(|error| format!("failed to read Sovereign Docs preview dir {}: {error}", dir.display()))?
    {
        let entry =
            entry.map_err(|error| format!("failed to read Sovereign Docs preview entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }
        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<SovereignDocsPreviewRecord>(&content) {
            records.push(record);
        }
    }
    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

