#[tauri::command]
pub fn record_omega_computer_session(
    request: OmegaComputerSessionRequest,
) -> Result<OmegaComputerSessionRecord, String> {
    let timestamp = now_ms()?;
    let requested_by = request
        .requested_by
        .as_deref()
        .map(|value| prompt_preview(value, 96))
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| "omega-computer-toolbar".to_string());
    let prompt_snippet = request
        .prompt_preview
        .as_deref()
        .map(|value| prompt_preview(value, 1600))
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| "No prompt was active when the Omega Computer packet was recorded.".to_string());
    let roles = omega_computer_roles();
    let stages = omega_computer_stages();
    let workers = omega_computer_workers();
    let ready_stage_count = stages
        .iter()
        .filter(|stage| stage.status.starts_with("ready"))
        .count();
    let blocked_stage_count = stages
        .iter()
        .filter(|stage| stage.status.contains("blocked"))
        .count();
    let id = format!(
        "omega-computer-session-{}-{}",
        timestamp,
        std::process::id()
    );
    let dir = omega_computer_sessions_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create Omega Computer session directory {}: {error}",
            dir.display()
        )
    })?;
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join("omega-computer-sessions.jsonl");
    let record = OmegaComputerSessionRecord {
        id: id.clone(),
        status: "omega_computer_session_recorded".to_string(),
        requested_by,
        prompt_preview: prompt_snippet,
        mode: "codex_lead_with_hermes_kimi_assist".to_string(),
        codex_lead_enabled: true,
        hermes_kimi_assist_enabled: true,
        observe_plan_act_verify_model: true,
        role_count: roles.len(),
        stage_count: stages.len(),
        ready_stage_count,
        blocked_stage_count,
        swarm_terminal_enabled: true,
        specialist_worker_count: workers.len(),
        active_worker_id: workers
            .iter()
            .find(|worker| worker.selected_by_default)
            .map(|worker| worker.id_badge.clone())
            .unwrap_or_else(|| "CL-00".to_string()),
        progress_rail_enabled: true,
        clickable_worker_views: true,
        record_path: record_path.display().to_string(),
        log_path: log_path.display().to_string(),
        live_capture_enabled: false,
        screenshot_enabled: false,
        ocr_enabled: false,
        pointer_injection_enabled: false,
        keyboard_injection_enabled: false,
        target_window_control_enabled: false,
        process_spawn_enabled: false,
        terminal_execution_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        export_enabled: false,
        live_mcp_call_enabled: false,
        memory_write_enabled: false,
        desktop_control_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        roles,
        stages,
        workers,
        blockers: vec![
            "Live screenshot capture, OCR, pointer/keyboard injection, and target-window control require explicit approval records plus deferred QA.".to_string(),
            "Terminal/process execution, file writes, patches, exports, live MCP calls, and memory writes stay in their existing explicit lanes.".to_string(),
        ],
        next_step: "Use this toolbar function as the main Omega-native computer workflow entrypoint: Codex Lead opens the swarm terminal, specialist agents become inspectable by ID badge, Hermes assists from capability records, and live action stays behind separate verified gates.".to_string(),
    };
    fs::write(
        &record_path,
        serde_json::to_string_pretty(&record)
            .map_err(|error| format!("failed to serialize Omega Computer session: {error}"))?,
    )
    .map_err(|error| {
        format!(
            "failed to write Omega Computer session record {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "omega_computer_session_recorded",
            "id": &record.id,
            "status": &record.status,
            "mode": &record.mode,
            "role_count": record.role_count,
            "stage_count": record.stage_count,
            "specialist_worker_count": record.specialist_worker_count,
            "active_worker_id": &record.active_worker_id,
            "swarm_terminal_enabled": true,
            "progress_rail_enabled": true,
            "clickable_worker_views": true,
            "ready_stage_count": record.ready_stage_count,
            "blocked_stage_count": record.blocked_stage_count,
            "codex_lead_enabled": true,
            "hermes_kimi_assist_enabled": true,
            "live_capture_enabled": false,
            "screenshot_enabled": false,
            "ocr_enabled": false,
            "pointer_injection_enabled": false,
            "keyboard_injection_enabled": false,
            "target_window_control_enabled": false,
            "process_spawn_enabled": false,
            "terminal_execution_enabled": false,
            "file_write_enabled": false,
            "patch_apply_enabled": false,
            "export_enabled": false,
            "live_mcp_call_enabled": false,
            "memory_write_enabled": false,
            "desktop_control_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;
    Ok(record)
}

#[tauri::command]
pub fn list_omega_computer_sessions() -> Result<Vec<OmegaComputerSessionRecord>, String> {
    let dir = omega_computer_sessions_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }
    let mut records = Vec::new();
    for entry in fs::read_dir(&dir)
        .map_err(|error| format!("failed to read Omega Computer sessions dir {}: {error}", dir.display()))?
    {
        let entry =
            entry.map_err(|error| format!("failed to read Omega Computer session entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }
        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<OmegaComputerSessionRecord>(&content) {
            records.push(record);
        }
    }
    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

fn workspace_explorer_preview(
    root: &Path,
    root_scope_valid: bool,
    entries: &[WorkspaceTreeEntry],
    ignore_patterns: &[String],
    requested_preview_path: String,
    max_bytes: usize,
) -> WorkspaceExplorerPreview {
    let normalized = normalize_workspace_preview_path(&requested_preview_path);
    let relative_path = normalized
        .clone()
        .unwrap_or_else(|| requested_preview_path.chars().take(160).collect());
    let path_valid = normalized.is_some();
    let path_ignored = path_valid && workspace_preview_path_ignored(&relative_path, ignore_patterns);
    let tree_entry = entries
        .iter()
        .find(|entry| entry.relative_path == relative_path)
        .cloned();
    let path_found_in_tree = tree_entry.is_some();
    let tree_entry_is_regular = tree_entry
        .as_ref()
        .map(|entry| entry.kind == "file")
        .unwrap_or(false);
    let tree_entry_is_symlink = tree_entry
        .as_ref()
        .map(|entry| entry.symlink)
        .unwrap_or(false);
    let absolute_path = if path_valid {
        root.join(&relative_path)
    } else {
        root.to_path_buf()
    };
    let absolute_path_display = absolute_path.display().to_string();
    let metadata = if path_valid {
        fs::symlink_metadata(&absolute_path).ok()
    } else {
        None
    };
    let file_exists = metadata.is_some();
    let file_is_symlink = metadata
        .as_ref()
        .map(|metadata| metadata.file_type().is_symlink())
        .unwrap_or(false)
        || tree_entry_is_symlink;
    let file_is_regular = metadata
        .as_ref()
        .map(|metadata| metadata.file_type().is_file())
        .unwrap_or(false)
        && tree_entry_is_regular
        && !file_is_symlink;
    let file_size_bytes = metadata.as_ref().map(|metadata| metadata.len()).unwrap_or(0);
    let file_scope_valid = if root_scope_valid && path_valid && file_exists {
        match (root.canonicalize(), absolute_path.canonicalize()) {
            (Ok(root), Ok(file)) => file.starts_with(root),
            _ => false,
        }
    } else {
        false
    };

    let can_read = root_scope_valid
        && path_valid
        && !path_ignored
        && path_found_in_tree
        && file_scope_valid
        && file_exists
        && file_is_regular
        && !file_is_symlink;
    let mut raw_bytes = Vec::new();
    let mut read_error = None;
    if can_read {
        match fs::File::open(&absolute_path) {
            Ok(mut file) => {
                let mut limited = std::io::Read::by_ref(&mut file).take((max_bytes + 1) as u64);
                if let Err(error) = limited.read_to_end(&mut raw_bytes) {
                    read_error = Some(error.to_string());
                    raw_bytes.clear();
                }
            }
            Err(error) => read_error = Some(error.to_string()),
        }
    }

    let read_error_present = read_error.is_some();
    let truncated = raw_bytes.len() > max_bytes || file_size_bytes > max_bytes as u64;
    if raw_bytes.len() > max_bytes {
        raw_bytes.truncate(max_bytes);
    }
    let utf8_valid = std::str::from_utf8(&raw_bytes).is_ok();
    let binary_detected = !raw_bytes.is_empty() && bytes_look_binary(&raw_bytes);
    let content = if can_read && !read_error_present && !binary_detected {
        String::from_utf8(raw_bytes.clone()).unwrap_or_default()
    } else {
        String::new()
    };
    let line_count = if content.is_empty() {
        0
    } else {
        content.lines().count()
    };
    let status = if !root_scope_valid {
        "blocked_workspace_root_outside_scope"
    } else if !path_valid {
        "blocked_invalid_relative_path"
    } else if path_ignored {
        "blocked_ignored_relative_path"
    } else if !path_found_in_tree {
        "blocked_path_not_in_live_tree"
    } else if file_is_symlink {
        "blocked_symlink_file_preview"
    } else if !file_exists {
        "blocked_file_missing"
    } else if !file_is_regular {
        "blocked_path_not_regular_file"
    } else if !file_scope_valid {
        "blocked_scope_validation_failed"
    } else if read_error_present {
        "blocked_file_read_error"
    } else if binary_detected {
        "blocked_binary_file_preview"
    } else {
        "workspace_explorer_file_preview_read_only"
    }
    .to_string();
    let file_content_read_enabled = status == "workspace_explorer_file_preview_read_only";
    let mut reasons = Vec::new();
    if let Some(error) = read_error {
        reasons.push(format!("file read failed: {error}"));
    }
    if truncated {
        reasons.push(format!("preview was capped at {max_bytes} byte(s)"));
    }
    reasons.push("preview is UTF-8 text only, read-only, and cannot write or patch files".to_string());

    WorkspaceExplorerPreview {
        relative_path,
        absolute_path: absolute_path_display,
        status,
        path_valid,
        path_ignored,
        path_found_in_tree,
        root_scope_valid: file_scope_valid,
        file_exists,
        file_is_regular,
        file_is_symlink,
        max_bytes,
        file_size_bytes,
        bytes_read: raw_bytes.len(),
        truncated,
        binary_detected,
        utf8_valid,
        content,
        line_count,
        file_content_read_enabled,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        reasons,
    }
}

#[tauri::command]
pub fn workspace_explorer_snapshot(
    request: WorkspaceExplorerRequest,
) -> Result<WorkspaceExplorerSnapshot, String> {
    let allowed_root = rebuild_workspace_root();
    let allowed_root = allowed_root.canonicalize().map_err(|error| {
        format!(
            "failed to canonicalize rebuild workspace root {}: {error}",
            allowed_root.display()
        )
    })?;
    let requested_root = request
        .root
        .unwrap_or_else(|| allowed_root.display().to_string())
        .trim()
        .chars()
        .take(240)
        .collect::<String>();
    let requested_root = if requested_root.is_empty() {
        allowed_root.display().to_string()
    } else {
        requested_root
    };
    let root_path = PathBuf::from(&requested_root);
    let root_is_absolute = root_path.is_absolute();
    let root_exists = root_path.exists();
    let root_is_directory = root_path.is_dir();
    let root_scope_valid = if root_is_absolute && root_exists {
        match root_path.canonicalize() {
            Ok(root) => root.starts_with(&allowed_root),
            Err(_) => false,
        }
    } else {
        false
    };
    let root = if root_scope_valid {
        root_path.canonicalize().unwrap_or(root_path.clone())
    } else {
        root_path.clone()
    };
    let max_depth = request.max_depth.unwrap_or(4).clamp(1, 6);
    let max_entries = request.max_entries.unwrap_or(180).clamp(1, 400);
    let max_preview_bytes = request.max_preview_bytes.unwrap_or(16_384).clamp(256, 65_536);
    let ignored_patterns = workspace_explorer_ignore_patterns();

    let collection = if root_scope_valid && root_is_directory {
        collect_workspace_tree_metadata(&root, &ignored_patterns, max_depth, max_entries)
    } else {
        WorkspaceTreeCollection::default()
    };
    let directory_count = collection
        .entries
        .iter()
        .filter(|entry| entry.kind == "directory")
        .count();
    let file_count = collection
        .entries
        .iter()
        .filter(|entry| entry.kind == "file")
        .count();
    let symlink_count = collection.entries.iter().filter(|entry| entry.symlink).count();
    let preview_path = request
        .preview_path
        .unwrap_or_else(workspace_explorer_default_preview_path);
    let preview = workspace_explorer_preview(
        &root,
        root_scope_valid,
        &collection.entries,
        &ignored_patterns,
        preview_path,
        max_preview_bytes,
    );
    let file_read_enabled = preview.file_content_read_enabled;
    let status = if !root_is_absolute {
        "workspace_explorer_blocked_root_not_absolute"
    } else if !root_exists {
        "workspace_explorer_blocked_root_missing"
    } else if !root_is_directory {
        "workspace_explorer_blocked_root_not_directory"
    } else if !root_scope_valid {
        "workspace_explorer_blocked_root_outside_rebuild_scope"
    } else if !file_read_enabled {
        "workspace_explorer_tree_ready_preview_blocked"
    } else {
        "workspace_explorer_snapshot_read_only"
    }
    .to_string();
    let mut reasons = Vec::new();
    reasons.push(format!(
        "workspace explorer is scoped to {}",
        allowed_root.display()
    ));
    reasons.push("node_modules, target, .git, and .sswp files are ignored by policy".to_string());
    reasons.push("file list and text preview are read-only; writes, patches, watchers, search, exports, MCP, desktop, and execution remain disabled".to_string());
    if collection.truncated {
        reasons.push(format!("tree traversal stopped at {max_entries} entries"));
    }
    if collection.skipped_ignored_count > 0 {
        reasons.push(format!(
            "{} ignored path(s) were skipped",
            collection.skipped_ignored_count
        ));
    }

    Ok(WorkspaceExplorerSnapshot {
        status,
        allowed_root: allowed_root.display().to_string(),
        root: root.display().to_string(),
        requested_root,
        root_is_absolute,
        root_exists,
        root_is_directory,
        root_scope_valid,
        max_depth,
        max_entries,
        max_preview_bytes,
        entry_count: collection.entries.len(),
        directory_count,
        file_count,
        symlink_count,
        skipped_ignored_count: collection.skipped_ignored_count,
        skipped_symlink_count: collection.skipped_symlink_count,
        read_error_count: collection.read_errors.len(),
        truncated: collection.truncated,
        entries: collection.entries,
        preview,
        ignored_patterns,
        read_only: true,
        scoped: root_scope_valid,
        file_list_enabled: root_scope_valid && root_is_directory,
        file_read_enabled,
        live_search_enabled: false,
        watch_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        desktop_control_enabled: false,
        live_mcp_call_enabled: false,
        socket_enabled: false,
        config_read_enabled: false,
        capture_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        reasons,
        next_step: "Layer explicit editor-tab materialization and write-policy approval on top of this read-only explorer before any save, patch, watcher, or search execution is enabled.".to_string(),
    })
}

