#[tauri::command]
pub fn provider_settings_dashboard() -> ProviderSettingsDashboard {
    let provider_specs = [
        ("openai", "OpenAI", "OPENAI_API_KEY"),
        ("anthropic", "Anthropic", "ANTHROPIC_API_KEY"),
        ("google", "Google AI", "GOOGLE_API_KEY"),
        ("gemini", "Gemini", "GEMINI_API_KEY"),
        ("openrouter", "OpenRouter", "OPENROUTER_API_KEY"),
        ("github", "GitHub", "GITHUB_TOKEN"),
    ];
    let providers = provider_specs
        .iter()
        .map(|(provider_id, display_name, env_key)| {
            let configured = env::var_os(*env_key).is_some_and(|value| !value.is_empty());
            ProviderSettingsDashboardItem {
                provider_id: *provider_id,
                display_name: *display_name,
                env_key: *env_key,
                configured,
                state: if configured {
                    "configured_redacted"
                } else {
                    "offline_missing_secret"
                },
                secret_value_redacted: true,
                editable_in_app: false,
                keyring_backed_target: true,
            }
        })
        .collect::<Vec<_>>();
    let configured_count = providers.iter().filter(|provider| provider.configured).count();
    let offline_count = providers.len().saturating_sub(configured_count);

    ProviderSettingsDashboard {
        status: if configured_count > 0 {
            "provider_settings_dashboard_redacted_ready"
        } else {
            "provider_settings_dashboard_offline_redacted"
        },
        provider_count: providers.len(),
        configured_count,
        offline_count,
        secrets_redacted: true,
        read_only: true,
        keyring_backed_target: true,
        provider_edit_enabled: false,
        secret_read_enabled: false,
        secret_write_enabled: false,
        socket_enabled: false,
        live_provider_validation_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        providers,
        reasons: vec![
            "provider settings intentionally report presence/absence only; secret values are never returned",
            "in-app provider editing and keyring writes require a separate explicit secret-management flow",
            "live provider validation, sockets, writes, patches, memory writes, and execution remain disabled",
        ],
        next_slice: "Add keyring-backed provider editing only after the UI has confirmation, validation, rollback, and redaction tests.",
    }
}

fn product_smoke_check(
    id: &'static str,
    title: &'static str,
    result: Result<String, String>,
) -> ProductWorkbenchSmokeCheck {
    match result {
        Ok(evidence) => ProductWorkbenchSmokeCheck {
            id: id.to_string(),
            title: title.to_string(),
            status: "passed".to_string(),
            passed: true,
            evidence,
        },
        Err(error) => ProductWorkbenchSmokeCheck {
            id: id.to_string(),
            title: title.to_string(),
            status: "failed".to_string(),
            passed: false,
            evidence: error,
        },
    }
}

#[tauri::command]
pub fn run_product_workbench_smoke() -> Result<ProductWorkbenchSmokeResult, String> {
    let timestamp = now_ms()?;
    let dir = product_workbench_smokes_dir()?;
    fs::create_dir_all(&dir)
        .map_err(|error| format!("failed to create product workbench smoke dir: {error}"))?;
    let id = format!(
        "product-workbench-smoke-{}-{}",
        timestamp,
        std::process::id()
    );
    let record_path = dir.join(format!("{id}.json"));
    let mut checks = Vec::new();

    checks.push(product_smoke_check(
        "workspace-file-open",
        "Workspace file open",
        product_workspace_file_open(ProductWorkspaceFileOpenRequest {
            path: "README.md".to_string(),
            max_bytes: Some(65_536),
        })
        .map(|result| format!("{} {} byte(s)", result.status, result.bytes_read)),
    ));

    checks.push(product_smoke_check(
        "workspace-search",
        "Workspace search",
        product_workspace_search(ProductWorkspaceSearchRequest {
            query: "Gravity Omega".to_string(),
            max_results: Some(25),
            max_depth: Some(5),
            max_entries: Some(300),
            max_file_bytes: Some(262_144),
        })
        .map(|result| {
            format!(
                "{} results={} files={}",
                result.status, result.result_count, result.matched_file_count
            )
        }),
    ));

    checks.push(product_smoke_check(
        "bounded-terminal",
        "Bounded terminal command",
        run_product_terminal_command(ProductTerminalCommandRequest {
            command: "pwd".to_string(),
            timeout_ms: Some(5_000),
        })
        .map(|result| {
            format!(
                "{} exit={:?} transcript={}",
                result.status, result.exit_code, result.stdout_transcript_path
            )
        }),
    ));

    checks.push(product_smoke_check(
        "provider-redaction",
        "Provider redaction dashboard",
        {
            let providers = provider_settings_dashboard();
            if providers.secrets_redacted && !providers.secret_read_enabled {
                Ok(format!(
                    "{} configured={}/{}",
                    providers.status, providers.configured_count, providers.provider_count
                ))
            } else {
                Err("provider dashboard did not preserve secret redaction".to_string())
            }
        },
    ));

    checks.push(product_smoke_check(
        "sidecar-readiness",
        "Browser/media/Python sidecar readiness",
        {
            let board = sidecar_readiness_board();
            Ok(format!(
                "{} sidecars={} blockers={}",
                board.status,
                board.items.len(),
                board.blockers.len()
            ))
        },
    ));

    checks.push(product_smoke_check(
        "runtime-probes",
        "Runtime probe board",
        {
            let board = runtime_probe_board(RuntimeProbeRequest {
                target: Some("all".to_string()),
            });
            Ok(format!(
                "{} targets={} found={}",
                board.status, board.probe_count, board.ready_count
            ))
        },
    ));

    checks.push(product_smoke_check(
        "veritas-modules",
        "VERITAS module readiness",
        veritas_modules_dashboard().map(|dashboard| {
            format!(
                "{} modules={} blocked_live={}",
                dashboard.status, dashboard.module_count, dashboard.blocked_live_module_count
            )
        }),
    ));

    checks.push(product_smoke_check(
        "sswp",
        "SSWP first-class lane",
        sswp_status().map(|panel| {
            format!(
                "{} evidence={} blocked={}",
                panel.status, panel.evidence_record_count, panel.blocked_evidence_count
            )
        }),
    ));

    checks.push(product_smoke_check(
        "steno-pet",
        "Steno and pet companion lane",
        steno_pet_companion_dashboard().map(|dashboard| {
            format!(
                "{} sections={} blocked={}",
                dashboard.status, dashboard.section_count, dashboard.disabled_gate_count
            )
        }),
    ));

    checks.push(product_smoke_check(
        "approval-evidence",
        "Approval and evidence spine",
        approval_evidence_spine_dashboard().map(|dashboard| {
            format!(
                "{} sections={} disabled_gates={}",
                dashboard.status, dashboard.section_count, dashboard.disabled_gate_count
            )
        }),
    ));

    checks.push(product_smoke_check(
        "linux-desktop-readiness",
        "Linux desktop readiness",
        linux_desktop_control_readiness_dashboard().map(|dashboard| {
            format!(
                "{} sections={} blocked={}",
                dashboard.status, dashboard.section_count, dashboard.disabled_gate_count
            )
        }),
    ));

    let passed_count = checks.iter().filter(|check| check.passed).count();
    let check_count = checks.len();
    let failed_count = check_count.saturating_sub(passed_count);
    let result = ProductWorkbenchSmokeResult {
        accepted: true,
        status: if failed_count == 0 {
            "product_workbench_smoke_passed".to_string()
        } else {
            "product_workbench_smoke_failed".to_string()
        },
        check_count,
        passed_count,
        failed_count,
        record_path: record_path.display().to_string(),
        created_at_ms: timestamp,
        file_io_checked: true,
        terminal_checked: true,
        provider_redaction_checked: true,
        sidecar_readiness_checked: true,
        module_readiness_checked: true,
        sswp_checked: true,
        steno_pet_checked: true,
        evidence_spine_checked: true,
        desktop_readiness_checked: true,
        checks,
    };
    if let Some(parent) = record_path.parent() {
        fs::create_dir_all(parent)
            .map_err(|error| format!("failed to recreate product workbench smoke dir: {error}"))?;
    }
    fs::write(
        &record_path,
        serde_json::to_string_pretty(&result)
            .map_err(|error| format!("failed to serialize product workbench smoke: {error}"))?,
    )
    .map_err(|error| {
        format!(
            "failed to write product workbench smoke {}: {error}",
            record_path.display()
        )
    })?;

    Ok(result)
}

#[tauri::command]
pub fn list_product_workbench_smokes() -> Result<Vec<ProductWorkbenchSmokeResult>, String> {
    let dir = product_workbench_smokes_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir)
        .map_err(|error| format!("failed to read product workbench smoke dir: {error}"))?
    {
        let entry = entry.map_err(|error| format!("failed to read smoke dir entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<ProductWorkbenchSmokeResult>(&content) {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

fn json_string(value: &serde_json::Value, key: &str) -> Option<String> {
    value
        .get(key)
        .and_then(|inner| inner.as_str())
        .map(|inner| inner.to_string())
}

fn json_u64(value: &serde_json::Value, key: &str) -> Option<u64> {
    value.get(key).and_then(|inner| inner.as_u64())
}

fn product_evidence_title_detail(
    category: &str,
    value: &serde_json::Value,
) -> (String, String) {
    match category {
        "workspace" => {
            if let Some(query) = json_string(value, "query") {
                let results = json_u64(value, "result_count").unwrap_or(0);
                let files = json_u64(value, "matched_file_count").unwrap_or(0);
                return (
                    format!("Workspace search: {query}"),
                    format!("results={results}; files={files}"),
                );
            }
            let path = json_string(value, "path").unwrap_or_else(|| "workspace file".to_string());
            let bytes = json_u64(value, "bytes_read")
                .or_else(|| json_u64(value, "bytes_written"))
                .unwrap_or(0);
            let lines = json_u64(value, "line_count").unwrap_or(0);
            (path, format!("lines={lines}; bytes={bytes}"))
        }
        "terminal" => {
            let command = json_string(value, "command").unwrap_or_else(|| "terminal command".to_string());
            let exit_code = value
                .get("exit_code")
                .map(|inner| inner.to_string())
                .unwrap_or_else(|| "null".to_string());
            let duration = json_u64(value, "duration_ms").unwrap_or(0);
            (command, format!("exit={exit_code}; duration={duration}ms"))
        }
        "terminal-blocked" => {
            let mode = json_string(value, "requested_mode").unwrap_or_else(|| "terminal".to_string());
            let block_class = json_string(value, "block_class").unwrap_or_else(|| "allowlist-denied".to_string());
            let preview = json_string(value, "command_preview").unwrap_or_else(|| "blocked command".to_string());
            (
                format!("Blocked terminal command: {mode}"),
                format!("{block_class}; preview={preview}; process_spawn=false; execution=false"),
            )
        }
        "terminal-replay" => {
            let command = json_string(value, "command").unwrap_or_else(|| "terminal replay".to_string());
            let stdout_lines = json_u64(value, "stdout_line_count").unwrap_or(0);
            let stderr_lines = json_u64(value, "stderr_line_count").unwrap_or(0);
            let source = json_string(value, "source_session_id").unwrap_or_else(|| "none".to_string());
            (
                format!("Terminal replay: {command}"),
                format!("source={source}; stdout_lines={stdout_lines}; stderr_lines={stderr_lines}; live_tail=false"),
            )
        }
        "sovereign-docs" => {
            let title = json_string(value, "title").unwrap_or_else(|| "Sovereign Docs preview".to_string());
            let lines = json_u64(value, "line_count").unwrap_or(0);
            let words = json_u64(value, "word_count").unwrap_or(0);
            let path = json_string(value, "preview_html_path").unwrap_or_else(|| "none".to_string());
            (
                format!("Sovereign Docs: {title}"),
                format!("lines={lines}; words={words}; html={path}; pdf_export=false"),
            )
        }
        "omega-computer" => {
            let mode = json_string(value, "mode").unwrap_or_else(|| "codex_lead_with_hermes_kimi_assist".to_string());
            let roles = json_u64(value, "role_count").unwrap_or(0);
            let stages = json_u64(value, "stage_count").unwrap_or(0);
            let workers = json_u64(value, "specialist_worker_count").unwrap_or(0);
            let active_worker = json_string(value, "active_worker_id").unwrap_or_else(|| "CL-00".to_string());
            let blocked = json_u64(value, "blocked_stage_count").unwrap_or(0);
            (
                "Omega Computer session".to_string(),
                format!("{mode}; roles={roles}; workers={workers}; active={active_worker}; stages={stages}; blocked={blocked}; desktop_control=false"),
            )
        }
        "smoke" => {
            let passed = json_u64(value, "passed_count").unwrap_or(0);
            let checks = json_u64(value, "check_count").unwrap_or(0);
            ("Workbench smoke".to_string(), format!("passed={passed}/{checks}"))
        }
        "agent" => {
            let runtime = json_string(value, "runtime").unwrap_or_else(|| "agent runtime".to_string());
            let exit_code = value
                .get("exit_code")
                .map(|inner| inner.to_string())
                .unwrap_or_else(|| "null".to_string());
            let duration = json_u64(value, "duration_ms").unwrap_or(0);
            (runtime, format!("exit={exit_code}; duration={duration}ms"))
        }
        "joint-packet" => {
            let task = json_string(value, "task_run_id").unwrap_or_else(|| "unresolved task".to_string());
            let missing = json_u64(value, "missing_runtime_count").unwrap_or(0);
            (task, format!("missing_runtime={missing}; approval_required=true"))
        }
        "runtime-packet" => {
            let title = json_string(value, "title").unwrap_or_else(|| "runtime launch packet".to_string());
            let target = json_string(value, "target").unwrap_or_else(|| "runtime".to_string());
            let family = json_string(value, "target_family").unwrap_or_else(|| "sidecar".to_string());
            (title, format!("target={target}; family={family}; launch_disabled=true"))
        }
        "runtime-depth" => {
            let ready = json_u64(value, "runtime_ready_count").unwrap_or(0);
            let probes = json_u64(value, "runtime_probe_count").unwrap_or(0);
            let path_ready = json_u64(value, "path_ready_count").unwrap_or(0);
            let paths = json_u64(value, "path_probe_count").unwrap_or(0);
            let skills = json_u64(value, "hermes_skill_count").unwrap_or(0);
            let mcp = json_u64(value, "hermes_mcp_server_count").unwrap_or(0);
            let hooks = json_u64(value, "hermes_hook_count").unwrap_or(0);
            (
                "Runtime depth probe".to_string(),
                format!("runtime_ready={ready}/{probes}; metadata_ready={path_ready}/{paths}; hermes_skills={skills}; hermes_mcp={mcp}; hermes_hooks={hooks}; launch_disabled=true"),
            )
        }
        "runtime-sidecar-process" => {
            let running = json_u64(value, "running_target_count").unwrap_or(0);
            let targets = json_u64(value, "target_count").unwrap_or(0);
            let processes = json_u64(value, "process_count").unwrap_or(0);
            let hermes = json_u64(value, "hermes_process_count").unwrap_or(0);
            let sswp = json_u64(value, "sswp_process_count").unwrap_or(0);
            let steno = json_u64(value, "steno_process_count").unwrap_or(0);
            (
                "Runtime sidecar process snapshot".to_string(),
                format!("running={running}/{targets}; processes={processes}; hermes={hermes}; sswp={sswp}; steno={steno}; control_disabled=true"),
            )
        }
        "desktop-environment" => {
            let status = json_string(value, "status").unwrap_or_else(|| "desktop_environment_snapshot".to_string());
            let wayland = value
                .get("wayland_display_present")
                .and_then(|inner| inner.as_bool())
                .unwrap_or(false);
            let x11 = value
                .get("display_present")
                .and_then(|inner| inner.as_bool())
                .unwrap_or(false);
            let ydotool = value
                .get("ydotool_socket_is_socket")
                .and_then(|inner| inner.as_bool())
                .unwrap_or(false);
            (
                "Desktop environment snapshot".to_string(),
                format!("{status}; wayland={wayland}; x11={x11}; ydotool_socket={ydotool}; control_disabled=true"),
            )
        }
        "desktop-stage1-capability" => {
            let status = json_string(value, "status").unwrap_or_else(|| "desktop_stage1_capability_snapshot".to_string());
            let available = json_u64(value, "available_tool_count").unwrap_or(0);
            let tools = json_u64(value, "tool_count").unwrap_or(0);
            let windows = json_u64(value, "available_window_inventory_tool_count").unwrap_or(0);
            let screenshots = json_u64(value, "available_screenshot_tool_count").unwrap_or(0);
            let accessibility = json_u64(value, "available_accessibility_tool_count").unwrap_or(0);
            (
                "Desktop stage-1 capability snapshot".to_string(),
                format!("{status}; available={available}/{tools}; windows={windows}; screenshots={screenshots}; accessibility={accessibility}; process_spawn=false"),
            )
        }
        "evidence-durability" => {
            let status = json_string(value, "status").unwrap_or_else(|| "evidence_durability_manifest".to_string());
            let readable = json_u64(value, "readable_record_count").unwrap_or(0);
            let records = json_u64(value, "evidence_record_count").unwrap_or(0);
            let missing = json_u64(value, "missing_record_count").unwrap_or(0);
            let categories = json_u64(value, "category_count").unwrap_or(0);
            let manifest_hash = json_string(value, "manifest_hash").unwrap_or_else(|| "hash-missing".to_string());
            (
                "Evidence durability manifest".to_string(),
                format!("{status}; readable={readable}/{records}; missing={missing}; categories={categories}; seal={manifest_hash}; export=false"),
            )
        }
        "codex-orchestration" => {
            let status = json_string(value, "status").unwrap_or_else(|| "orchestration".to_string());
            let delegations = json_u64(value, "delegation_count").unwrap_or(0);
            let codex = json_u64(value, "codex_owned_count").unwrap_or(0);
            let hermes = json_u64(value, "hermes_assist_count").unwrap_or(0);
            let skills = json_u64(value, "hermes_skill_count").unwrap_or(0);
            let mcp = json_u64(value, "hermes_mcp_server_count").unwrap_or(0);
            (
                "Codex Lead orchestration".to_string(),
                format!("{status}; lanes={delegations}; codex={codex}; hermes={hermes}; hermes_skills={skills}; hermes_mcp={mcp}; execution_disabled=true"),
            )
        }
        "hermes-inventory" => {
            let skills = json_u64(value, "enabled_skill_count").unwrap_or(0);
            let files = json_u64(value, "filesystem_skill_count").unwrap_or(0);
            let mcp = json_u64(value, "mcp_server_count").unwrap_or(0);
            let hooks = json_u64(value, "hook_count").unwrap_or(0);
            (
                "Hermes capability inventory".to_string(),
                format!("enabled_skills={skills}; filesystem_skills={files}; mcp={mcp}; hooks={hooks}; execution_disabled=true"),
            )
        }
        "hermes-assist" => {
            let status = json_string(value, "status").unwrap_or_else(|| "assist".to_string());
            let exit_code = value
                .get("exit_code")
                .map(|inner| inner.to_string())
                .unwrap_or_else(|| "null".to_string());
            let duration = json_u64(value, "duration_ms").unwrap_or(0);
            let stdout = json_u64(value, "stdout_size_bytes").unwrap_or(0);
            (
                "Hermes assist brief".to_string(),
                format!("{status}; exit={exit_code}; duration={duration}ms; stdout={stdout}b; writes_disabled=true"),
            )
        }
        "sswp-registry" => {
            let nodes = json_u64(value, "node_count").unwrap_or(0);
            let risky = json_u64(value, "risky_node_count").unwrap_or(0);
            let highest = value
                .get("highest_risk_percent")
                .and_then(|inner| inner.as_f64())
                .unwrap_or(0.0);
            (
                "SSWP registry snapshot".to_string(),
                format!("nodes={nodes}; risky={risky}; highest_risk={highest:.1}%; witness_disabled=true; verify_disabled=true"),
            )
        }
        "pet-signal" => {
            let state = json_string(value, "state").unwrap_or_else(|| "idle".to_string());
            let source = json_string(value, "source").unwrap_or_else(|| "runtime".to_string());
            let severity = json_string(value, "severity").unwrap_or_else(|| "info".to_string());
            let progress = json_u64(value, "progress").unwrap_or(0);
            (
                format!("Pet signal: {state}"),
                format!("source={source}; severity={severity}; progress={progress}; execution_disabled=true"),
            )
        }
        _ => ("Evidence record".to_string(), "recorded".to_string()),
    }
}

fn push_product_evidence_history_dir(
    items: &mut Vec<ProductEvidenceHistoryItem>,
    category: &str,
    dir: PathBuf,
) -> Result<(), String> {
    if !dir.exists() {
        return Ok(());
    }

    for entry in fs::read_dir(&dir)
        .map_err(|error| format!("failed to read product evidence dir {}: {error}", dir.display()))?
    {
        let entry = entry.map_err(|error| format!("failed to read evidence dir entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }
        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        let value = match serde_json::from_str::<serde_json::Value>(&content) {
            Ok(value) => value,
            Err(_) => continue,
        };
        let id = json_string(&value, "id").unwrap_or_else(|| {
            path.file_stem()
                .and_then(|value| value.to_str())
                .unwrap_or("evidence-record")
                .to_string()
        });
        let status = json_string(&value, "status").unwrap_or_else(|| "recorded".to_string());
        let created_at_ms = json_u64(&value, "created_at_ms").unwrap_or(0);
        let (title, detail) = product_evidence_title_detail(category, &value);
        items.push(ProductEvidenceHistoryItem {
            category: category.to_string(),
            id,
            status,
            title,
            detail,
            record_path: path.display().to_string(),
            created_at_ms,
        });
    }

    Ok(())
}

#[tauri::command]
pub fn product_evidence_history() -> Result<ProductEvidenceHistory, String> {
    let mut items = Vec::new();
    push_product_evidence_history_dir(&mut items, "workspace", product_workspace_events_dir()?)?;
    push_product_evidence_history_dir(&mut items, "terminal", product_terminal_sessions_dir()?)?;
    push_product_evidence_history_dir(
        &mut items,
        "terminal-blocked",
        product_terminal_blocked_commands_dir()?,
    )?;
    push_product_evidence_history_dir(&mut items, "terminal-replay", product_terminal_transcript_replays_dir()?)?;
    push_product_evidence_history_dir(&mut items, "sovereign-docs", sovereign_docs_previews_dir()?)?;
    push_product_evidence_history_dir(&mut items, "omega-computer", omega_computer_sessions_dir()?)?;
    push_product_evidence_history_dir(&mut items, "smoke", product_workbench_smokes_dir()?)?;
    push_product_evidence_history_dir(&mut items, "agent", unlocked_agent_prompt_sessions_dir()?)?;
    push_product_evidence_history_dir(&mut items, "joint-packet", joint_runtime_run_packets_dir()?)?;
    push_product_evidence_history_dir(&mut items, "runtime-packet", runtime_launch_packets_dir()?)?;
    push_product_evidence_history_dir(&mut items, "runtime-depth", runtime_depth_probes_dir()?)?;
    push_product_evidence_history_dir(&mut items, "runtime-sidecar-process", runtime_sidecar_process_snapshots_dir()?)?;
    push_product_evidence_history_dir(&mut items, "desktop-environment", desktop_environment_snapshots_dir()?)?;
    push_product_evidence_history_dir(&mut items, "desktop-stage1-capability", desktop_read_only_capability_snapshots_dir()?)?;
    push_product_evidence_history_dir(&mut items, "evidence-durability", evidence_durability_manifests_dir()?)?;
    push_product_evidence_history_dir(&mut items, "codex-orchestration", codex_lead_orchestrations_dir()?)?;
    push_product_evidence_history_dir(&mut items, "hermes-inventory", hermes_kimi_capability_inventories_dir()?)?;
    push_product_evidence_history_dir(&mut items, "hermes-assist", hermes_kimi_assist_briefs_dir()?)?;
    push_product_evidence_history_dir(&mut items, "sswp-registry", sswp_registry_snapshots_dir()?)?;
    push_product_evidence_history_dir(&mut items, "pet-signal", pet_runtime_signals_dir()?)?;

    items.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    items.truncate(50);
    let mut categories = items
        .iter()
        .map(|item| item.category.clone())
        .collect::<Vec<_>>();
    categories.sort();
    categories.dedup();

    Ok(ProductEvidenceHistory {
        status: if items.is_empty() {
            "product_evidence_history_empty".to_string()
        } else {
            "product_evidence_history_ready".to_string()
        },
        item_count: items.len(),
        category_count: categories.len(),
        categories,
        items,
        history_enabled: true,
        evidence_read_enabled: true,
        file_write_enabled: false,
        process_spawn_enabled: false,
        live_mcp_call_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
    })
}

fn stable_local_evidence_hash(input: &str) -> String {
    let mut hash = 0xcbf29ce484222325u64;
    for byte in input.as_bytes() {
        hash ^= *byte as u64;
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("fnv1a64:{hash:016x}")
}

#[tauri::command]
pub fn record_evidence_durability_manifest(
    request: EvidenceDurabilityManifestRequest,
) -> Result<EvidenceDurabilityManifestRecord, String> {
    let timestamp = now_ms()?;
    let requested_by = request
        .requested_by
        .unwrap_or_else(|| "evidence-durability".to_string())
        .trim()
        .chars()
        .take(120)
        .collect::<String>();
    let requested_by = if requested_by.is_empty() {
        "evidence-durability".to_string()
    } else {
        requested_by
    };
    let history = product_evidence_history()?;
    let mut categories = BTreeMap::<String, EvidenceDurabilityManifestCategory>::new();
    let mut rows = Vec::new();
    let mut readable_record_count = 0usize;
    let mut missing_record_count = 0usize;

    for item in &history.items {
        let read_result = fs::read_to_string(&item.record_path);
        let (readable, byte_count) = match read_result {
            Ok(content) => {
                readable_record_count += 1;
                (true, content.len())
            }
            Err(_) => {
                missing_record_count += 1;
                (false, 0usize)
            }
        };
        let category = categories
            .entry(item.category.clone())
            .or_insert_with(|| EvidenceDurabilityManifestCategory {
                category: item.category.clone(),
                record_count: 0,
                readable_record_count: 0,
                missing_record_count: 0,
                latest_created_at_ms: 0,
                latest_record_path: String::new(),
            });
        category.record_count += 1;
        if readable {
            category.readable_record_count += 1;
        } else {
            category.missing_record_count += 1;
        }
        if item.created_at_ms >= category.latest_created_at_ms {
            category.latest_created_at_ms = item.created_at_ms;
            category.latest_record_path = item.record_path.clone();
        }
        rows.push(serde_json::json!({
            "category": &item.category,
            "id": &item.id,
            "status": &item.status,
            "record_path": &item.record_path,
            "created_at_ms": item.created_at_ms,
            "readable": readable,
            "byte_count": byte_count,
        }));
    }

    rows.sort_by(|left, right| {
        serde_json::to_string(left)
            .unwrap_or_default()
            .cmp(&serde_json::to_string(right).unwrap_or_default())
    });
    let manifest_input = serde_json::to_string(&serde_json::json!({
        "source_history_status": &history.status,
        "source_history_item_count": history.item_count,
        "rows": rows,
    }))
    .map_err(|error| format!("failed to serialize evidence manifest input: {error}"))?;
    let manifest_hash = stable_local_evidence_hash(&manifest_input);
    let id = format!("evidence-durability-manifest-{}-{}", timestamp, std::process::id());
    let dir = evidence_durability_manifests_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create evidence durability manifests directory {}: {error}",
            dir.display()
        )
    })?;
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let latest = history.items.first();
    let blockers = if missing_record_count > 0 {
        vec![format!(
            "{missing_record_count} product evidence record path(s) were not readable during manifest creation"
        )]
    } else {
        Vec::new()
    };
    let status = if history.items.is_empty() {
        "evidence_durability_manifest_empty"
    } else if missing_record_count > 0 {
        "evidence_durability_manifest_recorded_with_missing_records"
    } else {
        "evidence_durability_manifest_recorded"
    }
    .to_string();
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let record = EvidenceDurabilityManifestRecord {
        id: id.clone(),
        status: status.clone(),
        requested_by,
        source_history_status: history.status.clone(),
        source_history_item_count: history.item_count,
        category_count: history.category_count,
        evidence_record_count: history.items.len(),
        readable_record_count,
        missing_record_count,
        manifest_input_bytes: manifest_input.len(),
        manifest_hash: manifest_hash.clone(),
        latest_evidence_category: latest.map(|item| item.category.clone()).unwrap_or_default(),
        latest_evidence_id: latest.map(|item| item.id.clone()).unwrap_or_default(),
        latest_evidence_status: latest.map(|item| item.status.clone()).unwrap_or_default(),
        latest_evidence_title: latest.map(|item| item.title.clone()).unwrap_or_default(),
        latest_evidence_record_path: latest.map(|item| item.record_path.clone()).unwrap_or_default(),
        latest_evidence_created_at_ms: latest.map(|item| item.created_at_ms).unwrap_or(0),
        categories: categories.into_values().collect(),
        local_manifest_recorded: true,
        read_only: true,
        history_enabled: true,
        evidence_read_enabled: true,
        process_spawn_enabled: false,
        terminal_enabled: false,
        desktop_control_enabled: false,
        capture_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        export_enabled: false,
        live_mcp_call_enabled: false,
        config_read_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        blockers,
        next_step: "Use this local manifest to prove evidence continuity before any export, live MCP, terminal/process, desktop, write, patch, or memory gate can open.".to_string(),
    };
    let json = serde_json::to_string_pretty(&record)
        .map_err(|error| format!("failed to serialize evidence durability manifest: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write evidence durability manifest {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "evidence_durability_manifest_recorded",
            "id": &record.id,
            "status": &record.status,
            "evidence_record_count": record.evidence_record_count,
            "readable_record_count": record.readable_record_count,
            "missing_record_count": record.missing_record_count,
            "category_count": record.category_count,
            "manifest_hash": &record.manifest_hash,
            "local_manifest_recorded": true,
            "export_enabled": false,
            "process_spawn_enabled": false,
            "terminal_enabled": false,
            "desktop_control_enabled": false,
            "live_mcp_call_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;
    Ok(record)
}

#[tauri::command]
pub fn list_evidence_durability_manifests(
) -> Result<Vec<EvidenceDurabilityManifestRecord>, String> {
    let dir = evidence_durability_manifests_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read evidence durability manifests directory {}: {error}",
            dir.display()
        )
    })? {
        let entry = entry.map_err(|error| format!("failed to read evidence durability manifest entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }
        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<EvidenceDurabilityManifestRecord>(&content) {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(40);
    Ok(records)
}

