#[tauri::command]
pub fn create_agent_capability_inventory_stub(
    request: AgentCapabilityInventoryRequest,
) -> Result<AgentCapabilityInventoryResult, String> {
    let timestamp = now_ms()?;
    let requested_scope_summary = request
        .requested_scope_summary
        .unwrap_or_default()
        .trim()
        .chars()
        .take(220)
        .collect::<String>();
    let items = agent_capability_inventory_items();
    let integration_count = items.len();
    let codex_item_count = items
        .iter()
        .filter(|item| item.source.contains("codex"))
        .count();
    let hermes_item_count = items
        .iter()
        .filter(|item| item.source.contains("hermes"))
        .count();
    let mcp_item_count = items.iter().filter(|item| item.source == "mcp").count();
    let first_class_mcp_count = items
        .iter()
        .filter(|item| item.source == "mcp" && item.first_class)
        .count();
    let pet_item_count = items.iter().filter(|item| item.source == "pet").count();
    let sswp_first_class = items
        .iter()
        .any(|item| item.id == "sswp-workflow" && item.first_class);
    let steno_first_class = items
        .iter()
        .any(|item| item.id == "omega-stenographer" && item.first_class);
    let pet_first_class = items
        .iter()
        .any(|item| item.id == "codex-pet" && item.first_class);
    let status = "agent_capability_inventory_recorded_read_only".to_string();
    let id = format!(
        "agent-capability-inventory-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug_limit(&status, 48)
    );
    let dir = agent_capability_inventories_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create agent-capability-inventories directory {}: {error}",
            dir.display()
        )
    })?;
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let record = AgentCapabilityInventoryRecord {
        id: id.clone(),
        requested_scope_summary,
        status: status.clone(),
        items,
        integration_count,
        codex_item_count,
        hermes_item_count,
        mcp_item_count,
        first_class_mcp_count,
        pet_item_count,
        sswp_first_class,
        steno_first_class,
        pet_first_class,
        read_only_inventory: true,
        live_runtime_probe_enabled: false,
        mcp_calls_enabled: false,
        desktop_control_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons: vec![
            "capability inventory records Codex, Hermes, MCP, SSWP, Steno, pet, approval, workspace, terminal, and desktop targets without calling or spawning them".to_string(),
            "SSWP, Omega Stenographer, and Codex pet are marked first-class integration targets".to_string(),
        ],
        next_step: "Add read-only readiness records for each first-class integration before enabling live MCP calls, runtime probes, terminals, desktop control, or workspace mutation.".to_string(),
    };

    let json = serde_json::to_string_pretty(&record)
        .map_err(|error| format!("failed to serialize agent capability inventory: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write agent capability inventory {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "agent_capability_inventory_stub_created",
            "id": id,
            "status": record.status,
            "integration_count": record.integration_count,
            "codex_item_count": record.codex_item_count,
            "hermes_item_count": record.hermes_item_count,
            "mcp_item_count": record.mcp_item_count,
            "first_class_mcp_count": record.first_class_mcp_count,
            "pet_item_count": record.pet_item_count,
            "sswp_first_class": record.sswp_first_class,
            "steno_first_class": record.steno_first_class,
            "pet_first_class": record.pet_first_class,
            "read_only_inventory": true,
            "mcp_calls_enabled": false,
            "terminal_enabled": false,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(AgentCapabilityInventoryResult {
        accepted: true,
        inventory_recorded: true,
        integration_count: record.integration_count,
        first_class_mcp_count: record.first_class_mcp_count,
        sswp_first_class: record.sswp_first_class,
        steno_first_class: record.steno_first_class,
        pet_first_class: record.pet_first_class,
        read_only_inventory: true,
        mcp_calls_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        record,
    })
}

#[tauri::command]
pub fn list_agent_capability_inventories(
) -> Result<Vec<AgentCapabilityInventoryRecord>, String> {
    let dir = agent_capability_inventories_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read agent-capability-inventories directory {}: {error}",
            dir.display()
        )
    })? {
        let entry = entry
            .map_err(|error| format!("failed to read agent capability inventory entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<AgentCapabilityInventoryRecord>(&content) {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

fn first_class_readiness_item(
    id: &str,
    dependency_summary: &str,
    inventory: Option<&AgentCapabilityInventoryRecord>,
) -> FirstClassIntegrationReadinessItem {
    let source_item = inventory.and_then(|record| record.items.iter().find(|item| item.id == id));
    let inventory_item_found = source_item.is_some();
    let first_class = source_item.map(|item| item.first_class).unwrap_or(false);
    let title = source_item
        .map(|item| item.title.clone())
        .unwrap_or_else(|| id.to_string());
    let source = source_item
        .map(|item| item.source.clone())
        .unwrap_or_else(|| "unresolved".to_string());
    let target_surface = source_item
        .map(|item| item.target_surface.clone())
        .unwrap_or_else(|| "unresolved".to_string());
    let priority = source_item
        .map(|item| item.priority.clone())
        .unwrap_or_else(|| "unresolved".to_string());
    let readiness_stage = if inventory_item_found && first_class {
        "readiness_recorded_live_gates_disabled"
    } else {
        "blocked_missing_first_class_inventory_item"
    };

    FirstClassIntegrationReadinessItem {
        id: id.to_string(),
        title,
        source,
        target_surface,
        priority,
        readiness_stage: readiness_stage.to_string(),
        dependency_summary: dependency_summary.to_string(),
        inventory_item_found,
        first_class,
        read_only_readiness: inventory_item_found && first_class,
        live_probe_required: true,
        live_probe_enabled: false,
        mcp_calls_enabled: false,
        asset_inspection_enabled: false,
        desktop_control_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
    }
}

fn first_class_integration_readiness_items(
    inventory: Option<&AgentCapabilityInventoryRecord>,
) -> Vec<FirstClassIntegrationReadinessItem> {
    vec![
        first_class_readiness_item(
            "omega-brain-memory",
            "readiness must define health, citation, retention, and recovery evidence before live Omega Brain calls",
            inventory,
        ),
        first_class_readiness_item(
            "sswp-workflow",
            "readiness must define health, capability, gated-call, consent, and audit states before live SSWP calls",
            inventory,
        ),
        first_class_readiness_item(
            "omega-stenographer",
            "readiness must define capture, transcript search, redaction, retention, export, and consent gates before live Steno calls",
            inventory,
        ),
        first_class_readiness_item(
            "codex-pet",
            "readiness must define asset discovery, animation state, pet-safe UI placement, and non-blocking companion behavior before live pet loading",
            inventory,
        ),
        first_class_readiness_item(
            "joint-codex-hermes-ci",
            "readiness must define non-overlapping write scopes, reconciliation, evidence bundles, and approval gates before live Codex/Hermes CI",
            inventory,
        ),
    ]
}

#[tauri::command]
pub fn create_first_class_integration_readiness_stub(
    request: FirstClassIntegrationReadinessRequest,
) -> Result<FirstClassIntegrationReadinessResult, String> {
    let timestamp = now_ms()?;
    let requested_readiness_summary = request
        .requested_readiness_summary
        .unwrap_or_default()
        .trim()
        .chars()
        .take(220)
        .collect::<String>();
    let requested_inventory_id = request
        .agent_capability_inventory_id
        .unwrap_or_default()
        .trim()
        .chars()
        .take(180)
        .collect::<String>();
    let inventory = if requested_inventory_id.is_empty() {
        latest_agent_capability_inventory_record()?
    } else {
        read_agent_capability_inventory_record(&requested_inventory_id)?
    };
    let inventory_source = inventory.as_ref();
    let inventory_found = inventory_source.is_some();
    let inventory_read_only = inventory_source
        .map(|record| record.read_only_inventory)
        .unwrap_or(false);
    let agent_capability_inventory_id = inventory_source
        .map(|record| record.id.clone())
        .unwrap_or_else(|| {
            if requested_inventory_id.is_empty() {
                "unresolved".to_string()
            } else {
                requested_inventory_id.clone()
            }
        });
    let inventory_record_path = inventory_source
        .map(|record| record.record_path.clone())
        .unwrap_or_else(|| "unresolved".to_string());
    let readiness_items = first_class_integration_readiness_items(inventory_source);
    let readiness_count = readiness_items.len();
    let first_class_ready_count = readiness_items
        .iter()
        .filter(|item| item.read_only_readiness && item.first_class)
        .count();
    let mcp_lane_count = readiness_items
        .iter()
        .filter(|item| item.source == "mcp")
        .count();
    let pet_lane_count = readiness_items
        .iter()
        .filter(|item| item.source == "pet")
        .count();
    let omega_brain_readiness_recorded = readiness_items
        .iter()
        .any(|item| item.id == "omega-brain-memory" && item.read_only_readiness);
    let sswp_readiness_recorded = readiness_items
        .iter()
        .any(|item| item.id == "sswp-workflow" && item.read_only_readiness);
    let steno_readiness_recorded = readiness_items
        .iter()
        .any(|item| item.id == "omega-stenographer" && item.read_only_readiness);
    let pet_readiness_recorded = readiness_items
        .iter()
        .any(|item| item.id == "codex-pet" && item.read_only_readiness);
    let joint_ci_readiness_recorded = readiness_items
        .iter()
        .any(|item| item.id == "joint-codex-hermes-ci" && item.read_only_readiness);
    let readiness_recorded = inventory_found
        && inventory_read_only
        && omega_brain_readiness_recorded
        && sswp_readiness_recorded
        && steno_readiness_recorded
        && pet_readiness_recorded
        && joint_ci_readiness_recorded;
    let status = if !inventory_found {
        "blocked_missing_agent_capability_inventory"
    } else if !inventory_read_only {
        "blocked_agent_capability_inventory_not_read_only"
    } else if !readiness_recorded {
        "blocked_agent_capability_inventory_incomplete"
    } else {
        "first_class_integration_readiness_recorded_read_only"
    }
    .to_string();
    let mut reasons = Vec::new();
    if !inventory_found {
        reasons.push("first-class integration readiness requires an existing agent capability inventory record".to_string());
    } else if !inventory_read_only {
        reasons.push(
            "agent capability inventory exists but is not marked as read-only inventory"
                .to_string(),
        );
    } else if !readiness_recorded {
        reasons.push("agent capability inventory is missing one or more first-class Omega Brain, SSWP, Steno, pet, or joint CI rows".to_string());
    } else {
        reasons.push("first-class integration readiness recorded for Omega Brain, SSWP, Omega Stenographer, Codex pet, and joint Codex/Hermes CI without probing, calling, spawning, controlling, writing, patching, or executing".to_string());
    }
    let id = format!(
        "first-class-integration-readiness-{}-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug_limit(&agent_capability_inventory_id, 48),
        slug_limit(&status, 48)
    );
    let dir = first_class_integration_readiness_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create first-class-integration-readiness directory {}: {error}",
            dir.display()
        )
    })?;
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let record = FirstClassIntegrationReadinessRecord {
        id: id.clone(),
        agent_capability_inventory_id: agent_capability_inventory_id.clone(),
        requested_readiness_summary,
        status: status.clone(),
        inventory_found,
        inventory_read_only,
        readiness_recorded,
        readiness_items,
        readiness_count,
        first_class_ready_count,
        mcp_lane_count,
        pet_lane_count,
        omega_brain_readiness_recorded,
        sswp_readiness_recorded,
        steno_readiness_recorded,
        pet_readiness_recorded,
        joint_ci_readiness_recorded,
        read_only_readiness: readiness_recorded,
        live_runtime_probe_enabled: false,
        mcp_calls_enabled: false,
        asset_inspection_enabled: false,
        desktop_control_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        inventory_record_path,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Add per-lane health and capability contracts before enabling live Omega Brain, SSWP, Omega Stenographer, pet assets, Codex/Hermes CI, MCP calls, runtime probes, terminals, desktop control, or workspace mutation.".to_string(),
    };

    let json = serde_json::to_string_pretty(&record).map_err(|error| {
        format!("failed to serialize first-class integration readiness: {error}")
    })?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write first-class integration readiness {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "first_class_integration_readiness_stub_created",
            "id": id,
            "agent_capability_inventory_id": record.agent_capability_inventory_id,
            "status": record.status,
            "inventory_found": record.inventory_found,
            "readiness_recorded": record.readiness_recorded,
            "readiness_count": record.readiness_count,
            "first_class_ready_count": record.first_class_ready_count,
            "omega_brain_readiness_recorded": record.omega_brain_readiness_recorded,
            "sswp_readiness_recorded": record.sswp_readiness_recorded,
            "steno_readiness_recorded": record.steno_readiness_recorded,
            "pet_readiness_recorded": record.pet_readiness_recorded,
            "joint_ci_readiness_recorded": record.joint_ci_readiness_recorded,
            "mcp_calls_enabled": false,
            "terminal_enabled": false,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(FirstClassIntegrationReadinessResult {
        accepted: record.readiness_recorded,
        readiness_recorded: record.readiness_recorded,
        inventory_found: record.inventory_found,
        readiness_count: record.readiness_count,
        first_class_ready_count: record.first_class_ready_count,
        omega_brain_readiness_recorded: record.omega_brain_readiness_recorded,
        sswp_readiness_recorded: record.sswp_readiness_recorded,
        steno_readiness_recorded: record.steno_readiness_recorded,
        pet_readiness_recorded: record.pet_readiness_recorded,
        joint_ci_readiness_recorded: record.joint_ci_readiness_recorded,
        read_only_readiness: record.read_only_readiness,
        mcp_calls_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        record,
    })
}

#[tauri::command]
pub fn list_first_class_integration_readiness(
) -> Result<Vec<FirstClassIntegrationReadinessRecord>, String> {
    let dir = first_class_integration_readiness_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read first-class-integration-readiness directory {}: {error}",
            dir.display()
        )
    })? {
        let entry = entry.map_err(|error| {
            format!("failed to read first-class integration readiness entry: {error}")
        })?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<FirstClassIntegrationReadinessRecord>(&content)
        {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

fn local_mcp_lane_contract_item(
    subsystem: &str,
    display_name: &str,
    source_readiness_item_id: &str,
    expected_command_ids: Vec<&str>,
    required_contracts: Vec<&str>,
    readiness: Option<&FirstClassIntegrationReadinessRecord>,
) -> LocalMcpLaneCapabilityContractItem {
    let readiness_item = readiness.and_then(|record| {
        record
            .readiness_items
            .iter()
            .find(|item| item.id == source_readiness_item_id)
    });
    let readiness_item_found = readiness_item.is_some();
    let first_class = readiness_item.map(|item| item.first_class).unwrap_or(false);
    let capability_contract_recorded = readiness_item_found && first_class;

    LocalMcpLaneCapabilityContractItem {
        subsystem: subsystem.to_string(),
        display_name: display_name.to_string(),
        source_readiness_item_id: source_readiness_item_id.to_string(),
        expected_command_ids: expected_command_ids
            .into_iter()
            .map(String::from)
            .collect(),
        required_contracts: required_contracts.into_iter().map(String::from).collect(),
        readiness_item_found,
        first_class,
        capability_contract_recorded,
        consent_gate_required: true,
        approval_required_for_calls: true,
        audit_required: true,
        redaction_required: subsystem == "omega_stenographer",
        retention_policy_required: true,
        recovery_required: true,
        live_probe_enabled: false,
        live_call_enabled: false,
        capture_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        desktop_control_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
    }
}

fn local_mcp_lane_contract_items(
    readiness: Option<&FirstClassIntegrationReadinessRecord>,
) -> Vec<LocalMcpLaneCapabilityContractItem> {
    vec![
        local_mcp_lane_contract_item(
            "omega_brain",
            "Omega Brain",
            "omega-brain-memory",
            vec![
                "omega_brain_status",
                "omega_brain_search",
                "omega_brain_cite",
                "omega_brain_memory_policy",
            ],
            vec![
                "health status",
                "citation envelope",
                "retention policy",
                "recovery state",
            ],
            readiness,
        ),
        local_mcp_lane_contract_item(
            "sswp",
            "SSWP",
            "sswp-workflow",
            vec![
                "sswp_status",
                "sswp_capabilities",
                "sswp_plan",
                "sswp_call_policy",
            ],
            vec![
                "health status",
                "capability manifest",
                "gated call policy",
                "audit trail",
            ],
            readiness,
        ),
        local_mcp_lane_contract_item(
            "omega_stenographer",
            "Omega Stenographer",
            "omega-stenographer",
            vec![
                "steno_status",
                "steno_capture_policy",
                "steno_search",
                "steno_export_policy",
            ],
            vec![
                "capture consent",
                "redaction policy",
                "retention policy",
                "export policy",
            ],
            readiness,
        ),
    ]
}

#[tauri::command]
pub fn create_local_mcp_lane_capability_contract_stub(
    request: LocalMcpLaneCapabilityContractRequest,
) -> Result<LocalMcpLaneCapabilityContractResult, String> {
    let timestamp = now_ms()?;
    let requested_contract_summary = request
        .requested_contract_summary
        .unwrap_or_default()
        .trim()
        .chars()
        .take(220)
        .collect::<String>();
    let requested_readiness_id = request
        .integration_readiness_id
        .unwrap_or_default()
        .trim()
        .chars()
        .take(180)
        .collect::<String>();
    let readiness = if requested_readiness_id.is_empty() {
        latest_first_class_integration_readiness_record()?
    } else {
        read_first_class_integration_readiness_record(&requested_readiness_id)?
    };
    let readiness_source = readiness.as_ref();
    let readiness_found = readiness_source.is_some();
    let readiness_recorded = readiness_source
        .map(|record| record.readiness_recorded)
        .unwrap_or(false);
    let integration_readiness_id = readiness_source
        .map(|record| record.id.clone())
        .unwrap_or_else(|| {
            if requested_readiness_id.is_empty() {
                "unresolved".to_string()
            } else {
                requested_readiness_id.clone()
            }
        });
    let readiness_record_path = readiness_source
        .map(|record| record.record_path.clone())
        .unwrap_or_else(|| "unresolved".to_string());
    let lanes = local_mcp_lane_contract_items(readiness_source);
    let lane_count = lanes.len();
    let contract_ready_count = lanes
        .iter()
        .filter(|lane| lane.capability_contract_recorded)
        .count();
    let omega_brain_contract_recorded = lanes
        .iter()
        .any(|lane| lane.subsystem == "omega_brain" && lane.capability_contract_recorded);
    let sswp_contract_recorded = lanes
        .iter()
        .any(|lane| lane.subsystem == "sswp" && lane.capability_contract_recorded);
    let steno_contract_recorded = lanes
        .iter()
        .any(|lane| lane.subsystem == "omega_stenographer" && lane.capability_contract_recorded);
    let capability_contract_recorded = readiness_found
        && readiness_recorded
        && omega_brain_contract_recorded
        && sswp_contract_recorded
        && steno_contract_recorded;
    let status = if !readiness_found {
        "blocked_missing_first_class_integration_readiness"
    } else if !readiness_recorded {
        "blocked_first_class_integration_readiness_not_recorded"
    } else if !capability_contract_recorded {
        "blocked_local_mcp_lane_capability_contract_incomplete"
    } else {
        "local_mcp_lane_capability_contract_recorded_calls_disabled"
    }
    .to_string();
    let mut reasons = Vec::new();
    if !readiness_found {
        reasons.push("local MCP lane capability contracts require an existing first-class integration readiness record".to_string());
    } else if !readiness_recorded {
        reasons.push(
            "first-class integration readiness exists but is not ready for local MCP contracts"
                .to_string(),
        );
    } else if !capability_contract_recorded {
        reasons.push(
            "first-class integration readiness is missing one or more Omega Brain, SSWP, or Steno rows"
                .to_string(),
        );
    } else {
        reasons.push("local MCP lane capability contracts recorded for Omega Brain, SSWP, and Omega Stenographer without probing, calling, capturing, exporting, writing, spawning, or executing".to_string());
    }
    let id = format!(
        "local-mcp-lane-capability-contract-{}-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug_limit(&integration_readiness_id, 48),
        slug_limit(&status, 48)
    );
    let dir = local_mcp_lane_capability_contracts_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create local-mcp-lane-capability-contracts directory {}: {error}",
            dir.display()
        )
    })?;
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let record = LocalMcpLaneCapabilityContractRecord {
        id: id.clone(),
        integration_readiness_id: integration_readiness_id.clone(),
        requested_contract_summary,
        status: status.clone(),
        readiness_found,
        readiness_recorded,
        capability_contract_recorded,
        lanes,
        lane_count,
        contract_ready_count,
        omega_brain_contract_recorded,
        sswp_contract_recorded,
        steno_contract_recorded,
        read_only_contract: capability_contract_recorded,
        live_probe_enabled: false,
        live_call_enabled: false,
        capture_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        desktop_control_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        readiness_record_path,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Add per-lane health preflights that consume these contracts before any live MCP probes, calls, capture, export, memory writes, process spawning, terminal control, desktop control, or workspace mutation.".to_string(),
    };

    let json = serde_json::to_string_pretty(&record).map_err(|error| {
        format!("failed to serialize local MCP lane capability contract: {error}")
    })?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write local MCP lane capability contract {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "local_mcp_lane_capability_contract_stub_created",
            "id": id,
            "integration_readiness_id": record.integration_readiness_id,
            "status": record.status,
            "readiness_found": record.readiness_found,
            "readiness_recorded": record.readiness_recorded,
            "capability_contract_recorded": record.capability_contract_recorded,
            "lane_count": record.lane_count,
            "contract_ready_count": record.contract_ready_count,
            "omega_brain_contract_recorded": record.omega_brain_contract_recorded,
            "sswp_contract_recorded": record.sswp_contract_recorded,
            "steno_contract_recorded": record.steno_contract_recorded,
            "live_probe_enabled": false,
            "live_call_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(LocalMcpLaneCapabilityContractResult {
        accepted: record.capability_contract_recorded,
        capability_contract_recorded: record.capability_contract_recorded,
        readiness_found: record.readiness_found,
        lane_count: record.lane_count,
        contract_ready_count: record.contract_ready_count,
        omega_brain_contract_recorded: record.omega_brain_contract_recorded,
        sswp_contract_recorded: record.sswp_contract_recorded,
        steno_contract_recorded: record.steno_contract_recorded,
        live_probe_enabled: false,
        live_call_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        record,
    })
}

