fn local_mcp_gated_call_policy_lane(
    subsystem: &str,
    display_name: &str,
    discovery_policy: Option<&LocalMcpCapabilityDiscoveryPolicyRecord>,
    discovery_policy_ready: bool,
) -> LocalMcpGatedCallPolicyLane {
    let discovery_policy_lane = discovery_policy
        .and_then(|record| record.lanes.iter().find(|lane| lane.subsystem == subsystem));
    let discovery_policy_lane_found = discovery_policy_lane.is_some();
    let discovery_policy_lane_ready = discovery_policy_ready
        && discovery_policy_lane
            .map(|lane| {
                lane.discovery_policy_recorded
                    && lane.health_record_ready
                    && lane.manifest_schema_required
                    && lane.approval_required_for_calls
                    && lane.audit_required
                    && lane.consent_gate_required
                    && lane.recovery_required
                    && !lane.live_probe_enabled
                    && !lane.capability_discovery_enabled
                    && !lane.live_call_enabled
                    && !lane.capture_enabled
                    && !lane.export_enabled
                    && !lane.memory_write_enabled
                    && !lane.desktop_control_enabled
                    && !lane.terminal_enabled
                    && !lane.process_spawn_enabled
                    && !lane.file_write_enabled
                    && !lane.patch_apply_enabled
                    && !lane.writes_allowed
                    && !lane.execution_enabled
            })
            .unwrap_or(false);
    let local_mcp_capability_discovery_policy_id = discovery_policy
        .map(|record| record.id.clone())
        .unwrap_or_else(|| "unresolved".to_string());
    let local_mcp_health_record_id = discovery_policy_lane
        .map(|lane| lane.local_mcp_health_record_id.clone())
        .unwrap_or_else(|| "unresolved".to_string());
    let expected_command_ids = discovery_policy_lane
        .map(|lane| lane.expected_command_ids.clone())
        .unwrap_or_default();

    LocalMcpGatedCallPolicyLane {
        subsystem: subsystem.to_string(),
        display_name: display_name.to_string(),
        local_mcp_capability_discovery_policy_id,
        local_mcp_health_record_id,
        discovery_policy_lane_found,
        discovery_policy_lane_ready,
        expected_command_ids,
        command_allowlist_required: true,
        consent_gate_required: true,
        approval_required_for_calls: true,
        audit_required: true,
        recovery_required: true,
        gated_call_policy_recorded: discovery_policy_lane_ready,
        live_probe_enabled: false,
        capability_discovery_enabled: false,
        live_call_enabled: false,
        capture_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        desktop_control_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
    }
}

#[tauri::command]
