#[tauri::command]
pub fn list_local_mcp_config_path_resolution_dry_runs(
) -> Result<Vec<LocalMcpConfigPathResolutionDryRunRecord>, String> {
    let dir = local_mcp_config_path_resolution_dry_runs_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read local-mcp-config-path-resolution-dry-runs directory {}: {error}",
            dir.display()
        )
    })? {
        let entry = entry.map_err(|error| {
            format!("failed to read local MCP config path resolution dry run entry: {error}")
        })?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) =
            serde_json::from_str::<LocalMcpConfigPathResolutionDryRunRecord>(&content)
        {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

fn local_mcp_config_path_materialization_request_lane(
    dry_run_lane: Option<&LocalMcpConfigPathResolutionDryRunLane>,
    subsystem: &str,
    display_name: &str,
    status_command_id: &str,
    fallback_config_source_ids: Vec<&str>,
    dry_run_ready: bool,
) -> LocalMcpConfigPathMaterializationRequestLane {
    let config_path_resolution_dry_run_found = dry_run_lane.is_some();
    let path_resolution_dry_run_recorded = dry_run_lane
        .map(|lane| lane.path_resolution_dry_run_recorded)
        .unwrap_or(false);
    let path_resolution_requested = dry_run_lane
        .map(|lane| lane.path_resolution_requested)
        .unwrap_or(false);
    let path_resolution_approved = dry_run_lane
        .map(|lane| lane.path_resolution_approved)
        .unwrap_or(false);
    let path_resolution_dry_run_ready = dry_run_lane
        .map(|lane| lane.path_resolution_dry_run_ready)
        .unwrap_or(false);
    let path_materialization_request_recorded = dry_run_ready
        && config_path_resolution_dry_run_found
        && path_resolution_dry_run_recorded
        && path_resolution_dry_run_ready
        && path_resolution_approved;
    let config_source_ids = dry_run_lane
        .map(|lane| lane.config_source_ids.clone())
        .unwrap_or_else(|| fallback_config_source_ids.into_iter().map(String::from).collect());
    let allowed_path_scope_ids = dry_run_lane
        .map(|lane| lane.allowed_path_scope_ids.clone())
        .unwrap_or_else(|| local_mcp_config_path_scope_ids(subsystem));

    LocalMcpConfigPathMaterializationRequestLane {
        subsystem: subsystem.to_string(),
        display_name: display_name.to_string(),
        status_command_id: status_command_id.to_string(),
        config_source_ids,
        allowed_path_scope_ids,
        config_path_resolution_dry_run_found,
        path_resolution_dry_run_recorded,
        path_materialization_request_recorded,
        path_resolution_requested,
        path_resolution_approved,
        path_resolution_dry_run_ready,
        path_materialization_requested: path_materialization_request_recorded,
        path_materialization_enabled: false,
        path_resolution_enabled: false,
        path_normalization_enabled: false,
        path_stat_enabled: false,
        symlink_follow_enabled: false,
        path_open_approved: false,
        resolved_path_materialized: false,
        real_path_values_captured: false,
        config_read_approved: false,
        explicit_user_approval_required: true,
        schema_validation_required: true,
        secret_redaction_required: true,
        audit_required: true,
        mcp_config_lookup_enabled: false,
        mcp_config_read_enabled: false,
        mcp_socket_connect_enabled: false,
        live_manifest_read_enabled: false,
        live_probe_enabled: false,
        capability_discovery_enabled: false,
        live_call_enabled: false,
        capture_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        desktop_control_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
    }
}

fn local_mcp_config_path_materialization_request_lanes(
    dry_run_record: Option<&LocalMcpConfigPathResolutionDryRunRecord>,
    dry_run_ready: bool,
) -> Vec<LocalMcpConfigPathMaterializationRequestLane> {
    let lane = |subsystem: &str| {
        dry_run_record.and_then(|record| {
            record
                .lanes
                .iter()
                .find(|lane| lane.subsystem == subsystem)
        })
    };

    vec![
        local_mcp_config_path_materialization_request_lane(
            lane("omega_brain"),
            "omega_brain",
            "Omega Brain",
            "omega_brain_status",
            vec!["omega_brain_mcp_registration", "omega_brain_runtime_endpoint"],
            dry_run_ready,
        ),
        local_mcp_config_path_materialization_request_lane(
            lane("sswp"),
            "sswp",
            "SSWP",
            "sswp_status",
            vec!["sswp_mcp_registration", "sswp_runtime_endpoint"],
            dry_run_ready,
        ),
        local_mcp_config_path_materialization_request_lane(
            lane("omega_stenographer"),
            "omega_stenographer",
            "Omega Stenographer",
            "steno_status",
            vec!["steno_mcp_registration", "steno_runtime_endpoint"],
            dry_run_ready,
        ),
    ]
}

