fn local_mcp_config_path_sealed_config_content_read_approval_lanes(
    final_dry_run_record: Option<&LocalMcpConfigPathSealedContentFinalDryRunRecord>,
    final_dry_run_ready: bool,
    supported_approval_decision: bool,
    confirmation_text_match: bool,
    sealed_config_content_read_approved: bool,
) -> Vec<LocalMcpConfigPathSealedConfigContentReadApprovalLane> {
    let lane = |subsystem: &str| {
        final_dry_run_record.and_then(|record| {
            record
                .lanes
                .iter()
                .find(|lane| lane.subsystem == subsystem)
        })
    };

    vec![
        local_mcp_config_path_sealed_config_content_read_approval_lane(
            lane("omega_brain"),
            "omega_brain",
            "Omega Brain",
            "omega_brain_status",
            vec!["omega_brain_mcp_registration", "omega_brain_runtime_endpoint"],
            final_dry_run_ready,
            supported_approval_decision,
            confirmation_text_match,
            sealed_config_content_read_approved,
        ),
        local_mcp_config_path_sealed_config_content_read_approval_lane(
            lane("sswp"),
            "sswp",
            "SSWP",
            "sswp_status",
            vec!["sswp_mcp_registration", "sswp_runtime_endpoint"],
            final_dry_run_ready,
            supported_approval_decision,
            confirmation_text_match,
            sealed_config_content_read_approved,
        ),
        local_mcp_config_path_sealed_config_content_read_approval_lane(
            lane("omega_stenographer"),
            "omega_stenographer",
            "Omega Stenographer",
            "steno_status",
            vec!["steno_mcp_registration", "steno_runtime_endpoint"],
            final_dry_run_ready,
            supported_approval_decision,
            confirmation_text_match,
            sealed_config_content_read_approved,
        ),
    ]
}

