fn local_mcp_config_path_sealed_config_content_read_final_dry_run_lanes(
    approval: Option<&LocalMcpConfigPathSealedConfigContentReadApprovalRecord>,
    approval_ready: bool,
) -> Vec<LocalMcpConfigPathSealedConfigContentReadFinalDryRunLane> {
    vec![
        local_mcp_config_path_sealed_config_content_read_final_dry_run_lane(
            approval.and_then(|record| {
                record
                    .lanes
                    .iter()
                    .find(|lane| lane.subsystem == "omega_brain")
            }),
            "omega_brain",
            "Omega Brain",
            "omega_brain_status",
            vec!["omega_brain_mcp_config", "codex_mcp_config"],
            approval_ready,
        ),
        local_mcp_config_path_sealed_config_content_read_final_dry_run_lane(
            approval.and_then(|record| record.lanes.iter().find(|lane| lane.subsystem == "sswp")),
            "sswp",
            "SSWP",
            "sswp_status",
            vec!["sswp_mcp_config", "codex_mcp_config"],
            approval_ready,
        ),
        local_mcp_config_path_sealed_config_content_read_final_dry_run_lane(
            approval.and_then(|record| {
                record
                    .lanes
                    .iter()
                    .find(|lane| lane.subsystem == "omega_stenographer")
            }),
            "omega_stenographer",
            "Omega Stenographer",
            "steno_status",
            vec!["steno_mcp_config", "codex_mcp_config"],
            approval_ready,
        ),
    ]
}

