fn local_mcp_config_path_sealed_config_content_read_execution_preflight_lanes(
    final_dry_run: Option<&LocalMcpConfigPathSealedConfigContentReadFinalDryRunRecord>,
    final_dry_run_ready: bool,
) -> Vec<LocalMcpConfigPathSealedConfigContentReadExecutionPreflightLane> {
    let lane = |subsystem: &str| {
        final_dry_run.and_then(|record| {
            record
                .lanes
                .iter()
                .find(|lane| lane.subsystem == subsystem)
        })
    };

    vec![
        local_mcp_config_path_sealed_config_content_read_execution_preflight_lane(
            lane("omega_brain"),
            "omega_brain",
            "Omega Brain",
            "omega_brain_status",
            vec!["omega_brain_mcp_config", "codex_mcp_config"],
            final_dry_run_ready,
        ),
        local_mcp_config_path_sealed_config_content_read_execution_preflight_lane(
            lane("sswp"),
            "sswp",
            "SSWP",
            "sswp_status",
            vec!["sswp_mcp_config", "codex_mcp_config"],
            final_dry_run_ready,
        ),
        local_mcp_config_path_sealed_config_content_read_execution_preflight_lane(
            lane("omega_stenographer"),
            "omega_stenographer",
            "Omega Stenographer",
            "steno_status",
            vec!["steno_mcp_config", "codex_mcp_config"],
            final_dry_run_ready,
        ),
    ]
}

