#[tauri::command]
pub fn list_local_mcp_config_path_sealed_config_content_read_execution_preflights(
) -> Result<Vec<LocalMcpConfigPathSealedConfigContentReadExecutionPreflightRecord>, String> {
    let dir = local_mcp_config_path_sealed_config_content_read_execution_preflights_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read local-mcp-config-path-sealed-config-content-read-execution-preflights directory {}: {error}",
            dir.display()
        )
    })? {
        let entry = entry.map_err(|error| {
            format!("failed to read local MCP sealed config content read execution preflight entry: {error}")
        })?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<
            LocalMcpConfigPathSealedConfigContentReadExecutionPreflightRecord,
        >(&content)
        {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

