fn local_mcp_config_path_sealed_config_content_read_final_execution_dry_run_lanes(
    final_approval: Option<&LocalMcpConfigPathSealedConfigContentReadFinalApprovalRecord>,
    final_approval_ready: bool,
    dry_run_mode: &str,
    supported_dry_run_mode: bool,
) -> Vec<LocalMcpConfigPathSealedConfigContentReadFinalExecutionDryRunLane> {
    let lane = |subsystem: &str| {
        final_approval.and_then(|record| {
            record
                .lanes
                .iter()
                .find(|lane| lane.subsystem == subsystem)
        })
    };

    vec![
        local_mcp_config_path_sealed_config_content_read_final_execution_dry_run_lane(
            lane("omega_brain"),
            "omega_brain",
            "Omega Brain",
            "omega_brain_status",
            vec!["omega_brain_mcp_config", "codex_mcp_config"],
            final_approval_ready,
            dry_run_mode,
            supported_dry_run_mode,
        ),
        local_mcp_config_path_sealed_config_content_read_final_execution_dry_run_lane(
            lane("sswp"),
            "sswp",
            "SSWP",
            "sswp_status",
            vec!["sswp_mcp_config", "codex_mcp_config"],
            final_approval_ready,
            dry_run_mode,
            supported_dry_run_mode,
        ),
        local_mcp_config_path_sealed_config_content_read_final_execution_dry_run_lane(
            lane("omega_stenographer"),
            "omega_stenographer",
            "Omega Stenographer",
            "steno_status",
            vec!["steno_mcp_config", "codex_mcp_config"],
            final_approval_ready,
            dry_run_mode,
            supported_dry_run_mode,
        ),
    ]
}

