        && supported_dry_run_mode
        && supported_redaction_profile
        && supported_schema_profile
        && supported_content_shape_policy_profile
        && supported_structural_intent_profile
        && supported_field_inventory_profile
        && redaction_required
        && schema_validation_required
        && secret_redaction_required
        && content_shape_policy_required
        && structural_intent_required
