        schema_validation_fixture_retention_review
            .as_ref()
            .map(|record| record.id.clone())
            .or(requested_schema_validation_fixture_retention_review_dry_run_id)
            .unwrap_or_else(|| "missing-local-mcp-sealed-config-content-read-schema-validation-fixture-retention-review-dry-run".to_string());
