fn toolbar_action_family(command: &ToolbarCommand) -> &'static str {
    if command.id.starts_with("file.") || command.id.starts_with("workspace.") {
        "workspace-file"
    } else if command.id.starts_with("edit.") || command.id.starts_with("search.replace") {
        "editor-mutation"
    } else if command.id.starts_with("terminal.") {
        "terminal-process"
    } else if command.id.starts_with("security.") {
        "security-control"
    } else if command.id.starts_with("agent.") {
        "agent-runner"
    } else if command.id.starts_with("mcp.") {
        "mcp-action"
    } else if command.id.starts_with("steno.") {
        "steno-capture"
    } else if command.id.starts_with("mobile.") {
        "mobile-pairing"
    } else if command.id.starts_with("window.") {
        "window-control"
    } else if command.id == "app.exit" {
        "app-lifecycle"
    } else if command.id.starts_with("developer.") {
        "developer-diagnostics"
    } else {
        "toolbar-action"
    }
}

fn toolbar_readiness_items(command: &ToolbarCommand) -> Vec<ToolbarActionReadinessItem> {
    let action_family = toolbar_action_family(command);
    let approval_required = command.capability_tier != "safe" || command.state == "gated";
    let mutation_family = matches!(
        action_family,
        "workspace-file"
            | "editor-mutation"
            | "terminal-process"
            | "security-control"
            | "agent-runner"
            | "mcp-action"
            | "steno-capture"
            | "mobile-pairing"
            | "window-control"
            | "app-lifecycle"
            | "developer-diagnostics"
    );

    let mut items = vec![
        ToolbarActionReadinessItem {
            item_id: "toolbar-command-registered",
            title: "Toolbar command registered",
            status: "ready",
            required: true,
            ready: true,
            evidence: "Command id is present in toolbar.v0.json.",
        },
        ToolbarActionReadinessItem {
            item_id: "target-command-mapped",
            title: "Target command mapped",
            status: if command.target_command.is_some() {
                "ready"
            } else {
                "blocked"
            },
            required: true,
            ready: command.target_command.is_some(),
            evidence: "Target command must be named before a toolbar action can graduate.",
        },
        ToolbarActionReadinessItem {
            item_id: "verification-contract-written",
            title: "Verification contract written",
            status: if command.verification.trim().is_empty() {
                "blocked"
            } else {
                "ready"
            },
            required: true,
            ready: !command.verification.trim().is_empty(),
            evidence: "Toolbar contract includes a verification sentence for the intended behavior.",
        },
        ToolbarActionReadinessItem {
            item_id: "execution-disabled",
            title: "Live action execution disabled",
            status: "sealed",
            required: true,
            ready: true,
            evidence: "Readiness panel never invokes target command execution.",
        },
        ToolbarActionReadinessItem {
            item_id: "evidence-panel-live",
            title: "Read-only evidence panel live",
            status: "ready",
            required: true,
            ready: true,
            evidence: "Toolbar click opens this readiness panel instead of doing nothing.",
        },
    ];

    if approval_required {
        items.push(ToolbarActionReadinessItem {
            item_id: "approval-ledger-required",
            title: "Approval ledger required",
            status: "blocked",
            required: true,
            ready: false,
            evidence: "Gated and restricted actions require explicit approval evidence before live execution.",
        });
    }

    if mutation_family {
        items.push(ToolbarActionReadinessItem {
            item_id: "artifact-log-required",
            title: "Artifact and audit log required",
            status: "blocked",
            required: true,
            ready: false,
            evidence: "State-changing actions need durable request, output, and rollback evidence before enablement.",
        });
    }

    items.push(ToolbarActionReadinessItem {
        item_id: "gate-release-required",
        title: "Gate release required",
        status: if command.state == "live" {
            "ready"
        } else {
            "blocked"
        },
        required: command.state != "live",
        ready: command.state == "live",
        evidence: "Non-live actions stay blocked until a dedicated slice verifies their live implementation.",
    });

    items
}

#[tauri::command]
pub fn toolbar_action_readiness(
    command_id: String,
) -> Result<ToolbarActionReadinessPanel, String> {
    let command = toolbar_contract()?
        .commands
        .into_iter()
        .find(|candidate| candidate.id == command_id);

    Ok(match command {
        Some(command) => {
            let readiness = toolbar_readiness_items(&command);
            let ready_count = readiness.iter().filter(|item| item.ready).count();
            let blocked_count = readiness.len().saturating_sub(ready_count);
            let approval_required =
                command.capability_tier != "safe" || command.state == "gated";
            let action_family = toolbar_action_family(&command);

            ToolbarActionReadinessPanel {
                accepted: false,
                found: true,
                status: if command.state == "live" {
                    "toolbar_action_live_readiness"
                } else {
                    "toolbar_action_blocked_readiness"
                },
                panel_id: "toolbar-action-readiness-panel",
                panel_title: "Toolbar Action Readiness",
                command_id: command.id,
                label: Some(command.label),
                surface: Some(command.surface),
                target_command: command.target_command,
                capability_tier: Some(command.capability_tier),
                state: Some(command.state),
                unavailable_reason: Some(command.unavailable_reason),
                verification: Some(command.verification),
                action_family,
                readiness_count: readiness.len(),
                ready_count,
                blocked_count,
                read_only: true,
                approval_required,
                action_enabled: false,
                file_read_enabled: false,
                file_write_enabled: false,
                patch_apply_enabled: false,
                terminal_enabled: false,
                terminal_write_enabled: false,
                process_spawn_enabled: false,
                desktop_control_enabled: false,
                config_read_enabled: false,
                live_mcp_call_enabled: false,
                socket_connect_enabled: false,
                capture_enabled: false,
                export_enabled: false,
                memory_write_enabled: false,
                writes_allowed: false,
                execution_enabled: false,
                readiness,
                reasons: vec![
                    "readiness panel makes disabled and gated toolbar rows inspectable without running their target command",
                    "panel reads the toolbar contract only; it does not create approvals, records, files, sockets, captures, exports, memory writes, processes, desktop actions, MCP calls, or execution",
                ],
                next_step: "Promote the target command in a dedicated verified slice after its prerequisite approval, evidence, and safety records exist.",
            }
        }
        None => ToolbarActionReadinessPanel {
            accepted: false,
            found: false,
            status: "toolbar_action_not_found",
            panel_id: "toolbar-action-readiness-panel",
            panel_title: "Toolbar Action Readiness",
            command_id,
            label: None,
            surface: None,
            target_command: None,
            capability_tier: None,
            state: None,
            unavailable_reason: Some("Command id is not present in toolbar.v0.json.".to_string()),
            verification: None,
            action_family: "missing-toolbar-action",
            readiness_count: 1,
            ready_count: 0,
            blocked_count: 1,
            read_only: true,
            approval_required: false,
            action_enabled: false,
            file_read_enabled: false,
            file_write_enabled: false,
            patch_apply_enabled: false,
            terminal_enabled: false,
            terminal_write_enabled: false,
            process_spawn_enabled: false,
            desktop_control_enabled: false,
            config_read_enabled: false,
            live_mcp_call_enabled: false,
            socket_connect_enabled: false,
            capture_enabled: false,
            export_enabled: false,
            memory_write_enabled: false,
            writes_allowed: false,
            execution_enabled: false,
            readiness: vec![ToolbarActionReadinessItem {
                item_id: "toolbar-command-registered",
                title: "Toolbar command registered",
                status: "blocked",
                required: true,
                ready: false,
                evidence: "Add this command to toolbar.v0.json or remove the visible control.",
            }],
            reasons: vec!["the requested command id is missing from the toolbar registry"],
            next_step: "Add the command to the registry or remove the visible UI surface.",
        },
    })
}

