#[tauri::command]
pub fn first_class_integration_launchpad(
    command_id: Option<String>,
) -> Result<FirstClassIntegrationLaunchpad, String> {
    let requested = command_id
        .unwrap_or_else(|| "agent.joint_ci".to_string())
        .trim()
        .chars()
        .take(120)
        .collect::<String>();
    let command_id = if requested.is_empty() {
        "agent.joint_ci".to_string()
    } else {
        requested
    };
    let items = first_class_integration_launchpad_items();
    let selected = items
        .iter()
        .find(|item| item.toolbar_command_id == command_id)
        .or_else(|| items.iter().find(|item| item.launch_target == command_id.as_str()));
    let found = selected.is_some();
    let read_only_ready_count = items
        .iter()
        .filter(|item| item.read_only_surface_ready)
        .count();
    let blocked_target_count = items
        .iter()
        .filter(|item| !item.action_enabled || !item.execution_enabled)
        .count();
    let approval_required_count = items
        .iter()
        .filter(|item| item.approval_required)
        .count();
    let consent_required_count = items.iter().filter(|item| item.consent_required).count();

    Ok(FirstClassIntegrationLaunchpad {
        accepted: false,
        found,
        status: if found {
            "first_class_integration_launchpad_read_only"
        } else {
            "first_class_integration_launchpad_unknown_command"
        },
        panel_id: "first-class-integration-launchpad",
        panel_title: "First-Class Integration Launchpad",
        command_id,
        selected_title: selected.map(|item| item.title),
        selected_runtime: selected.map(|item| item.runtime),
        selected_underlying_target: selected.map(|item| item.underlying_target),
        item_count: items.len(),
        read_only_ready_count,
        blocked_target_count,
        approval_required_count,
        consent_required_count,
        read_only: true,
        action_enabled: false,
        live_mcp_call_enabled: false,
        capture_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        config_read_enabled: false,
        file_read_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        desktop_control_enabled: false,
        socket_connect_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        items,
        reasons: vec![
            "launchpad turns the remaining first-class integration toolbar rows into inspectable product surfaces",
            "it reads static readiness only and does not start agents, call MCP tools, capture transcripts, read config, open sockets, spawn terminals/processes, control the desktop, write files, export data, write memory, or execute anything",
        ],
        next_step: "Promote each blocked target in its own verified slice after approval records, dry-runs, logs, and recovery policy exist.",
    })
}

fn gated_action_release_lane(
    command: &ToolbarCommand,
) -> (&'static str, &'static str, &'static str, &'static str) {
    match command.id.as_str() {
        "file.save" | "file.save_as" | "search.replace" => (
            "workspace-mutation",
            "workspace editor safety",
            "Could modify project files or editor buffers.",
            "Create write approval, editable-buffer preflight, preview diff, rollback record, and final operator confirmation.",
        ),
        "terminal.new" => (
            "terminal-process",
            "terminal/process lane",
            "Could spawn a PTY or process with workspace access.",
            "Create process command plan, sandbox policy match, stream preflight, lifecycle record, and operator confirmation.",
        ),
        "developer.devtools" => (
            "developer-surface",
            "native shell controls",
            "Could expose native debugging surfaces or privileged app internals.",
            "Add devtools policy, debug-mode guard, session indicator, and explicit operator approval.",
        ),
        "mobile.qr" => (
            "mobile-pairing",
            "Tailscale-first pairing",
            "Could create a pairing token or remote access channel.",
            "Add token expiry, revocation, Tailscale-only policy, audit log, and operator confirmation.",
        ),
        id if id.starts_with("security.") => (
            "security-shield",
            "restricted security actions",
            "Could start or stop host security, containment, or shield behavior.",
            "Add dry-run host-impact report, YubiKey/operator confirmation, rollback policy, and post-action verification.",
        ),
        _ => (
            "general-gated-action",
            "approval spine",
            "Could mutate state or invoke a gated capability.",
            "Add approval, dry-run, rollback, evidence, and recovery records.",
        ),
    }
}

#[tauri::command]
pub fn gated_action_release_board() -> Result<GatedActionReleaseBoard, String> {
    let commands = toolbar_contract()?.commands;
    let mut lanes: Vec<&'static str> = Vec::new();
    let mut items = Vec::new();

    for command in commands.into_iter().filter(|command| command.state == "gated") {
        let (release_lane, release_owner, risk_summary, next_step) =
            gated_action_release_lane(&command);
        if !lanes.contains(&release_lane) {
            lanes.push(release_lane);
        }
        items.push(GatedActionReleaseItem {
            command_id: command.id,
            label: command.label,
            surface: command.surface,
            target_command: command.target_command,
            release_lane,
            release_owner,
            risk_summary,
            release_status: "blocked_until_verified_release_evidence",
            approval_required: true,
            dry_run_required: true,
            rollback_required: true,
            evidence_required: true,
            action_enabled: false,
            file_read_enabled: false,
            file_write_enabled: false,
            patch_apply_enabled: false,
            terminal_enabled: false,
            process_spawn_enabled: false,
            desktop_control_enabled: false,
            config_read_enabled: false,
            live_mcp_call_enabled: false,
            socket_connect_enabled: false,
            capture_enabled: false,
            export_enabled: false,
            memory_write_enabled: false,
            writes_allowed: false,
            execution_enabled: false,
            next_step,
        });
    }

    let gated_count = items.len();
    Ok(GatedActionReleaseBoard {
        accepted: false,
        status: "gated_action_release_board_read_only",
        panel_id: "gated-action-release-board",
        panel_title: "Gated Action Release Board",
        gated_count,
        release_lane_count: lanes.len(),
        approval_required_count: items.iter().filter(|item| item.approval_required).count(),
        dry_run_required_count: items.iter().filter(|item| item.dry_run_required).count(),
        rollback_required_count: items.iter().filter(|item| item.rollback_required).count(),
        evidence_required_count: items.iter().filter(|item| item.evidence_required).count(),
        read_only: true,
        action_enabled: false,
        file_read_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        desktop_control_enabled: false,
        config_read_enabled: false,
        live_mcp_call_enabled: false,
        socket_connect_enabled: false,
        capture_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        items,
        reasons: vec![
            "release board derives remaining gated actions from toolbar.v0.json",
            "it is a planning surface only and does not create approvals, write records, run dry-runs, mutate files, spawn terminals/processes, call MCP tools, control the desktop, capture, export, write memory, or execute anything",
        ],
        next_step: "Promote one gated lane at a time only after approval, dry-run, rollback, evidence, and recovery checks are verified.",
    })
}

fn workspace_mutation_operation(
    command_id: &str,
) -> Option<(
    &'static str,
    &'static str,
    &'static str,
    &'static str,
    &'static str,
    &'static str,
)> {
    match command_id {
        "file.save" => Some((
            "save",
            "current buffer to existing workspace file",
            "Could overwrite existing workspace bytes.",
            "Requires write approval policy, approved operator evidence, dirty-transition preflight, mutable-buffer transaction, diff preview, rollback record, and final confirmation.",
            "Approval policy -> approval evidence -> writable-buffer draft -> dirty preflight -> mutable transaction -> diff/rollback -> final confirmation.",
            "Release only after the save adapter can prove atomic write, rollback path, and post-write verification without bypassing the approval ledger.",
        )),
        "file.save_as" => Some((
            "save_as",
            "current buffer to a new operator-confirmed workspace path",
            "Could create or overwrite a target path outside the intended buffer if the picker and path policy are wrong.",
            "Requires user-confirmed target path, write approval policy, writable-buffer draft, dirty-transition preflight, mutable-buffer transaction, diff preview, rollback record, and final confirmation.",
            "Path confirmation -> approval policy -> approval evidence -> writable-buffer draft -> dirty preflight -> mutable transaction -> diff/rollback -> final confirmation.",
            "Release only after save-as path policy, overwrite warning, rollback path, and post-write verification are tested.",
        )),
        "search.replace" => Some((
            "replace",
            "find results into an editable buffer draft",
            "Could mutate many matches or the wrong buffer if query scope, preview, or selection state drifts.",
            "Requires scoped query preview, replace preview, write approval policy, writable-buffer draft, dirty-transition preflight, mutable-buffer transaction, diff preview, rollback record, and final confirmation.",
            "Scoped find preview -> replace preview -> approval policy -> writable-buffer draft -> dirty preflight -> mutable transaction -> diff/rollback -> final confirmation.",
            "Release only after replace preview, per-match selection, rollback path, and post-mutation verification are tested.",
        )),
        _ => None,
    }
}

fn workspace_mutation_stages(operation: &str) -> Vec<WorkspaceMutationWorkbenchStage> {
    let preview_title = if operation == "replace" {
        "Scoped replace preview"
    } else if operation == "save_as" {
        "Confirmed target path preview"
    } else {
        "Current buffer preview"
    };

    vec![
        WorkspaceMutationWorkbenchStage {
            stage_id: "toolbar-command-gated",
            title: "Toolbar command mapped",
            status: "ready",
            required: true,
            ready: true,
            evidence: "Command exists in toolbar.v0.json and is intentionally gated.",
            gate: "read-only registry",
        },
        WorkspaceMutationWorkbenchStage {
            stage_id: "operator-preview",
            title: preview_title,
            status: "blocked",
            required: true,
            ready: false,
            evidence: "Preview must show exactly what would change before any mutation adapter can run.",
            gate: "preview gate disabled",
        },
        WorkspaceMutationWorkbenchStage {
            stage_id: "write-approval-policy",
            title: "Write approval policy",
            status: "blocked",
            required: true,
            ready: false,
            evidence: "Workspace write approval policy records must match the requested operation.",
            gate: "approval policy required",
        },
        WorkspaceMutationWorkbenchStage {
            stage_id: "approval-evidence",
            title: "Operator approval evidence",
            status: "blocked",
            required: true,
            ready: false,
            evidence: "Operator approval must include subject id, command id, risk summary, and confirmation phrase.",
            gate: "approval evidence required",
        },
        WorkspaceMutationWorkbenchStage {
            stage_id: "writable-buffer-draft",
            title: "Writable buffer draft",
            status: "blocked",
            required: true,
            ready: false,
            evidence: "A draft buffer must exist before any dirty transition is considered.",
            gate: "draft materialization disabled",
        },
        WorkspaceMutationWorkbenchStage {
            stage_id: "dirty-transition-preflight",
            title: "Dirty transition preflight",
            status: "blocked",
            required: true,
            ready: false,
            evidence: "Dirty-state transition must be recorded and still disallowed until final release.",
            gate: "dirty transition disabled",
        },
        WorkspaceMutationWorkbenchStage {
            stage_id: "mutable-buffer-transaction",
            title: "Mutable buffer transaction",
            status: "blocked",
            required: true,
            ready: false,
            evidence: "Mutable-buffer transaction must record intent while keeping materialization disabled.",
            gate: "mutable transaction disabled",
        },
        WorkspaceMutationWorkbenchStage {
            stage_id: "diff-rollback",
            title: "Diff preview and rollback",
            status: "blocked",
            required: true,
            ready: false,
            evidence: "Every mutation needs a before/after diff and rollback plan before execution.",
            gate: "diff and rollback required",
        },
        WorkspaceMutationWorkbenchStage {
            stage_id: "final-confirmation",
            title: "Final operator confirmation",
            status: "blocked",
            required: true,
            ready: false,
            evidence: "A final confirmation must bind the preview, approval, diff, rollback, and target adapter.",
            gate: "execution adapter disabled",
        },
    ]
}

fn workspace_mutation_workbench_item(
    command: ToolbarCommand,
) -> Option<WorkspaceMutationWorkbenchItem> {
    let (operation, mutation_scope, risk_summary, approval_policy, evidence_chain, next_step) =
        workspace_mutation_operation(&command.id)?;
    let stages = workspace_mutation_stages(operation);
    let ready_stage_count = stages.iter().filter(|stage| stage.ready).count();
    let stage_count = stages.len();

    Some(WorkspaceMutationWorkbenchItem {
        command_id: command.id,
        label: command.label,
        target_command: command.target_command,
        operation,
        workflow_lane: "workspace-mutation",
        mutation_scope,
        risk_summary,
        approval_policy,
        evidence_chain,
        diff_preview_status: "blocked_until_preview_and_rollback_exist",
        rollback_status: "blocked_until_rollback_record_exists",
        release_status: "blocked_until_full_mutation_workflow_verified",
        stage_count,
        ready_stage_count,
        blocked_stage_count: stage_count.saturating_sub(ready_stage_count),
        approval_required: true,
        diff_preview_required: true,
        rollback_required: true,
        final_confirmation_required: true,
        read_only_surface_ready: true,
        action_enabled: false,
        file_read_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        desktop_control_enabled: false,
        config_read_enabled: false,
        live_mcp_call_enabled: false,
        socket_connect_enabled: false,
        capture_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        stages,
        next_step,
    })
}

