#[tauri::command]
pub fn list_gated_adapter_release_packets(
) -> Result<Vec<GatedAdapterReleasePacketRecord>, String> {
    let dir = gated_adapter_release_packets_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read gated-adapter-release-packets directory {}: {error}",
            dir.display()
        )
    })? {
        let entry =
            entry.map_err(|error| format!("failed to read gated adapter packet entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<GatedAdapterReleasePacketRecord>(&content) {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

#[tauri::command]
pub fn execute_command_stub(command_id: String) -> Result<CommandExecutionStub, String> {
    let command = toolbar_contract()?
        .commands
        .into_iter()
        .find(|candidate| candidate.id == command_id);

    Ok(match command {
        Some(command) => {
            let next_step = if command.state == "live" {
                "Render the bundled in-app panel; no approval, external opener, or execution is required."
            } else {
                "Persist an approval record and run artifact before enabling this command."
            };
            let reason = if command.state == "missing" {
                command.unavailable_reason.clone()
            } else if command.state == "live" && command.capability_tier == "safe" {
                format!(
                    "Safe in-app command `{}` is live; the renderer opens a bundled panel without external opener, network, file read, process spawn, MCP, socket, write, or execution.",
                    command.id
                )
            } else if command.state == "live" {
                format!(
                    "Read-only launchpad command `{}` is live; the underlying gated target remains disabled until approval, sandbox, recovery, and evidence logging are implemented.",
                    command.id
                )
            } else {
                format!(
                    "Dry-run executor resolved `{}` but live execution is disabled until approval, sandbox, and evidence logging are implemented.",
                    command.id
                )
            };

            CommandExecutionStub {
                accepted: false,
                found: true,
                status: if command.state == "missing" {
                    "missing".to_string()
                } else if command.state == "live" {
                    "live".to_string()
                } else {
                    "blocked".to_string()
                },
                id: command.id,
                label: Some(command.label),
                surface: Some(command.surface),
                target_command: command.target_command,
                capability_tier: Some(command.capability_tier),
                state: Some(command.state),
                reason,
                next_step,
            }
        }
        None => CommandExecutionStub {
            accepted: false,
            found: false,
            status: "not_found".to_string(),
            id: command_id,
            label: None,
            surface: None,
            target_command: None,
            capability_tier: None,
            state: None,
            reason: "Command id is not present in toolbar.v0.json.".to_string(),
            next_step: "Add the command to the registry or remove the visible UI surface.",
        },
    })
}

