#[tauri::command]
pub fn resolve_approval_record_stub(request: ApprovalDecisionRequest) -> Result<ApprovalRecord, String> {
    if !is_safe_id(&request.id) {
        return Err("approval id contains unsupported characters".to_string());
    }

    let path = approvals_dir()?.join(format!("{}.json", request.id));
    let content = fs::read_to_string(&path)
        .map_err(|error| format!("failed to read approval record {}: {error}", path.display()))?;
    let mut record: ApprovalRecord = serde_json::from_str(&content)
        .map_err(|error| format!("failed to parse approval record {}: {error}", path.display()))?;
    let timestamp = now_ms()?;
    let decision = request.decision.to_ascii_lowercase();

    record.updated_at_ms = timestamp;
    record.confirmation_text = Some(request.confirmation_text.clone());
    record.note = Some(request.note.clone());
    record.execution_enabled = false;
    record.status = if decision == "deny" || decision == "denied" {
        "denied".to_string()
    } else if decision == "approve" || decision == "approved" {
        if request.confirmation_text == record.confirmation_phrase {
            "approved_recorded_execution_disabled".to_string()
        } else {
            "confirmation_mismatch".to_string()
        }
    } else {
        "unknown_decision".to_string()
    };
    record.reason = "Approval decision recorded, but live execution remains disabled by scaffold policy.".to_string();

    let json = serde_json::to_string_pretty(&record)
        .map_err(|error| format!("failed to serialize approval record: {error}"))?;
    fs::write(&path, json)
        .map_err(|error| format!("failed to update approval record {}: {error}", path.display()))?;
    write_jsonl_event(
        &PathBuf::from(&record.log_path),
        serde_json::json!({
            "event": "approval_stub_resolved",
            "id": record.id,
            "decision": decision,
            "status": record.status,
            "updated_at_ms": timestamp,
            "execution_enabled": false
        }),
    )?;

    Ok(record)
}

#[tauri::command]
pub fn task_run_artifact_preview(task_run_id: String) -> Result<ArtifactPreview, String> {
    let Some(record) = read_task_run_record(&task_run_id)? else {
        return Ok(ArtifactPreview {
            found: false,
            id: task_run_id,
            record_path: String::new(),
            log_path: String::new(),
            record_json: String::new(),
            log_lines: Vec::new(),
            line_count: 0,
            truncated: false,
            error: Some("task run record was not found".to_string()),
        });
    };

    let record_json = fs::read_to_string(&record.record_path)
        .map_err(|error| format!("failed to read artifact record {}: {error}", record.record_path))?;
    let log_text = fs::read_to_string(&record.log_path).unwrap_or_default();
    let lines: Vec<String> = log_text.lines().map(ToString::to_string).collect();
    let line_count = lines.len();
    let truncated = line_count > 40;
    let log_lines = if truncated {
        lines[line_count - 40..].to_vec()
    } else {
        lines
    };

    Ok(ArtifactPreview {
        found: true,
        id: record.id,
        record_path: record.record_path,
        log_path: record.log_path,
        record_json,
        log_lines,
        line_count,
        truncated,
        error: None,
    })
}

