#[tauri::command]
pub fn create_joint_agent_plan_stub(
    request: JointAgentPlanRequest,
) -> Result<JointAgentPlanResult, String> {
    let Some(task_run) = read_task_run_record(&request.task_run_id)? else {
        return Err("task run record is required before creating a joint agent plan".to_string());
    };

    let timestamp = now_ms()?;
    let id = format!(
        "joint-plan-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug(&task_run.mode)
    );
    let dir = joint_agent_plans_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create joint-agent-plans directory {}: {error}",
            dir.display()
        )
    })?;
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let goal_preview: String = request.goal.chars().take(220).collect();
    let phases = joint_agent_phases();
    let plan = JointAgentPlanRecord {
        id: id.clone(),
        task_run_id: task_run.id,
        goal_preview,
        repo: request.repo.unwrap_or(task_run.repo),
        status: "planned_execution_disabled".to_string(),
        phases,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reason: "Joint Codex/Hermes coordination is recorded as a disabled plan; no agent process is spawned.".to_string(),
        next_step: "Connect this plan to the disabled runner gate before adding live log streaming or process execution.".to_string(),
    };

    let json = serde_json::to_string_pretty(&plan)
        .map_err(|error| format!("failed to serialize joint agent plan: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write joint agent plan {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "joint_agent_plan_stub_created",
            "id": id,
            "task_run_id": plan.task_run_id,
            "phase_count": plan.phases.len(),
            "created_at_ms": timestamp,
            "execution_enabled": false
        }),
    )?;

    Ok(JointAgentPlanResult {
        accepted: false,
        task_run_found: true,
        execution_enabled: false,
        plan,
    })
}

