#[tauri::command]
pub fn append_agent_event_stub(
    request: AgentEventRequest,
) -> Result<AgentEventAppendResult, String> {
    let task_run_id = request.task_run_id.clone();
    if read_task_run_record(&task_run_id)?.is_none() {
        return Err("task run record is required before appending an agent event".to_string());
    }

    let dir = agent_events_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create agent-events directory {}: {error}",
            dir.display()
        )
    })?;

    let log_path = agent_event_log_path(&task_run_id)?;
    let existing = fs::read_to_string(&log_path).unwrap_or_default();
    let sequence = existing.lines().count() as u64 + 1;
    let timestamp = now_ms()?;
    let id = format!(
        "agent-event-{}-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug(&request.source_runtime),
        sequence
    );
    let record = AgentEventRecord {
        id,
        task_run_id: task_run_id.clone(),
        source_runtime: request.source_runtime,
        event_type: request.event_type,
        level: request.level,
        sequence,
        message: request.message,
        payload: request.payload,
        created_at_ms: timestamp,
        execution_enabled: false,
    };

    let event = serde_json::to_value(&record)
        .map_err(|error| format!("failed to serialize agent event: {error}"))?;
    write_jsonl_event(&log_path, event)?;

    Ok(AgentEventAppendResult {
        accepted: false,
        task_run_found: true,
        execution_enabled: false,
        record,
        preview: agent_event_log_preview(task_run_id)?,
    })
}

#[tauri::command]
pub fn agent_event_log_preview(task_run_id: String) -> Result<AgentEventLogPreview, String> {
    let task_run_found = read_task_run_record(&task_run_id)?.is_some();
    let log_path = agent_event_log_path(&task_run_id)?;
    let log_path_display = log_path.display().to_string();
    if !task_run_found {
        return Ok(AgentEventLogPreview {
            task_run_found,
            found: false,
            task_run_id,
            log_path: log_path_display,
            events: Vec::new(),
            line_count: 0,
            truncated: false,
            error: Some("task run record was not found".to_string()),
        });
    }
    if !log_path.exists() {
        return Ok(AgentEventLogPreview {
            task_run_found,
            found: false,
            task_run_id,
            log_path: log_path_display,
            events: Vec::new(),
            line_count: 0,
            truncated: false,
            error: Some("agent event log has not been created yet".to_string()),
        });
    }

    let log_text = fs::read_to_string(&log_path)
        .map_err(|error| format!("failed to read agent event log {}: {error}", log_path.display()))?;
    let mut events: Vec<AgentEventRecord> = log_text
        .lines()
        .filter_map(|line| serde_json::from_str::<AgentEventRecord>(line).ok())
        .collect();
    let line_count = events.len();
    let truncated = line_count > 50;
    if truncated {
        events = events[line_count - 50..].to_vec();
    }

    Ok(AgentEventLogPreview {
        task_run_found,
        found: true,
        task_run_id,
        log_path: log_path_display,
        events,
        line_count,
        truncated,
        error: None,
    })
}

