#[tauri::command]
pub fn codex_hermes_run_reconciliation_checklist(
) -> Result<CodexHermesRunReconciliationChecklist, String> {
    let diff_board = codex_hermes_run_evidence_diff_board()?;
    let mut checklist = diff_board
        .diffs
        .iter()
        .map(codex_hermes_run_reconciliation_item_from_diff)
        .collect::<Vec<_>>();
    checklist.push(codex_hermes_run_gravity_reconciliation_item(
        diff_board.gravity_ready_evidence_count,
    ));

    let ready_check_count = checklist.iter().filter(|item| item.ready).count();
    let balanced_check_count = checklist.iter().filter(|item| item.balanced).count();
    let gap_check_count = checklist.iter().filter(|item| item.gap_detected).count();
    let action_required_count = checklist
        .iter()
        .filter(|item| item.action_required)
        .count();
    let disabled_gate_count = checklist
        .iter()
        .filter(|item| {
            item.read_only
                && !item.process_spawn_enabled
                && !item.terminal_enabled
                && !item.live_mcp_call_enabled
                && !item.file_write_enabled
                && !item.patch_apply_enabled
                && !item.desktop_control_enabled
                && !item.capture_enabled
                && !item.export_enabled
                && !item.memory_write_enabled
                && !item.writes_allowed
                && !item.execution_enabled
        })
        .count();

    Ok(CodexHermesRunReconciliationChecklist {
        status: "codex_hermes_run_reconciliation_checklist_read_only",
        active_task_run_id: diff_board.active_task_run_id,
        selected_run_found: diff_board.selected_run_found,
        checklist_count: checklist.len(),
        ready_check_count,
        balanced_check_count,
        gap_check_count,
        action_required_count,
        codex_ready_evidence_count: diff_board.codex_ready_evidence_count,
        hermes_ready_evidence_count: diff_board.hermes_ready_evidence_count,
        gravity_ready_evidence_count: diff_board.gravity_ready_evidence_count,
        disabled_gate_count,
        read_only: true,
        process_spawn_enabled: false,
        terminal_enabled: false,
        live_mcp_call_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        desktop_control_enabled: false,
        capture_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        checklist,
        reasons: vec![
            "reconciliation checklist consumes read-only Codex/Hermes evidence diffs and Gravity Omega reconciliation evidence",
            "checklist is advisory only and does not create, select, mutate, reorder, delete, reconcile, resolve, export, or execute any records",
            "process spawn, terminal control, live MCP calls, writes, patches, desktop control, capture, export, memory writes, workspace writes, and execution remain disabled",
        ],
        next_slice: "Use this reconciliation checklist to add an operator run picker or close-gap planning surface while keeping live runtime, write, export, memory, desktop, capture, and execution gates sealed.",
    })
}

fn codex_hermes_run_reconciliation_action_priority(
    metric: &str,
    fallback_rank: usize,
) -> (usize, &'static str) {
    match metric {
        "ready_evidence_count" => (1, "highest"),
        "export_policy_ready_count" => (2, "high"),
        "protection_policy_ready_count" => (3, "high"),
        "runner_ready_count" => (4, "medium"),
        "transcript_bundle_ready_count" => (5, "medium"),
        _ => (fallback_rank.saturating_add(10), "normal"),
    }
}

fn codex_hermes_run_reconciliation_action_plan_item(
    item: &CodexHermesRunReconciliationChecklistItem,
    fallback_rank: usize,
) -> CodexHermesRunReconciliationActionPlanItem {
    let (priority_rank, priority_label) =
        codex_hermes_run_reconciliation_action_priority(&item.metric, fallback_rank);
    let missing_evidence_count = item.delta.unsigned_abs() as usize;

    CodexHermesRunReconciliationActionPlanItem {
        action_id: format!("close-gap-{}", item.source_diff_id),
        title: format!("Close {}", item.title),
        source_check_id: item.item_id.clone(),
        source_diff_id: item.source_diff_id.clone(),
        metric: item.metric.clone(),
        priority_rank,
        priority_label,
        current_codex_count: item.codex_count,
        current_hermes_count: item.hermes_count,
        missing_evidence_count,
        blocked_by: "missing balanced Codex/Hermes evidence plus sealed runtime, write, export, memory, desktop, capture, and execution gates",
        recommended_operator_step: format!(
            "Record or link {} missing Hermes-side evidence for {} before marking this gap ready; keep every live runtime and mutation gate disabled.",
            missing_evidence_count, item.metric
        ),
        status: "reconciliation_action_advisory_execution_disabled",
        ready_to_execute: false,
        action_required: item.action_required,
        read_only: true,
        process_spawn_enabled: false,
        terminal_enabled: false,
        live_mcp_call_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        desktop_control_enabled: false,
        capture_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
    }
}

#[tauri::command]
pub fn codex_hermes_run_reconciliation_action_plan(
) -> Result<CodexHermesRunReconciliationActionPlan, String> {
    let checklist_dashboard = codex_hermes_run_reconciliation_checklist()?;
    let mut action_plan = checklist_dashboard
        .checklist
        .iter()
        .enumerate()
        .filter(|(_, item)| item.action_required)
        .map(|(index, item)| codex_hermes_run_reconciliation_action_plan_item(item, index + 1))
        .collect::<Vec<_>>();

    action_plan.sort_by(|left, right| {
        left.priority_rank
            .cmp(&right.priority_rank)
            .then_with(|| left.action_id.cmp(&right.action_id))
    });

    let missing_evidence_total = action_plan
        .iter()
        .map(|item| item.missing_evidence_count)
        .sum();
    let blocked_action_count = action_plan
        .iter()
        .filter(|item| !item.ready_to_execute)
        .count();
    let disabled_gate_count = action_plan
        .iter()
        .filter(|item| {
            item.read_only
                && !item.ready_to_execute
                && !item.process_spawn_enabled
                && !item.terminal_enabled
                && !item.live_mcp_call_enabled
                && !item.file_write_enabled
                && !item.patch_apply_enabled
                && !item.desktop_control_enabled
                && !item.capture_enabled
                && !item.export_enabled
                && !item.memory_write_enabled
                && !item.writes_allowed
                && !item.execution_enabled
        })
        .count();

    Ok(CodexHermesRunReconciliationActionPlan {
        status: "codex_hermes_run_reconciliation_action_plan_read_only",
        active_task_run_id: checklist_dashboard.active_task_run_id,
        selected_run_found: checklist_dashboard.selected_run_found,
        action_count: action_plan.len(),
        gap_action_count: action_plan.len(),
        blocked_action_count,
        missing_evidence_total,
        checklist_count: checklist_dashboard.checklist_count,
        ready_check_count: checklist_dashboard.ready_check_count,
        action_required_count: checklist_dashboard.action_required_count,
        codex_ready_evidence_count: checklist_dashboard.codex_ready_evidence_count,
        hermes_ready_evidence_count: checklist_dashboard.hermes_ready_evidence_count,
        gravity_ready_evidence_count: checklist_dashboard.gravity_ready_evidence_count,
        disabled_gate_count,
        read_only: true,
        process_spawn_enabled: false,
        terminal_enabled: false,
        live_mcp_call_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        desktop_control_enabled: false,
        capture_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        action_plan,
        reasons: vec![
            "reconciliation action plan consumes read-only checklist gaps and ranks advisory close-gap steps",
            "actions are planning records only and do not assign, approve, resolve, mutate, export, or execute anything",
            "process spawn, terminal control, live MCP calls, writes, patches, desktop control, capture, export, memory writes, workspace writes, and execution remain disabled",
        ],
        next_slice: "Use this action plan to connect operator approvals or evidence attachment previews while keeping live runtime, write, export, memory, desktop, capture, and execution gates sealed.",
    })
}

fn codex_hermes_run_evidence_attachment_kind(metric: &str) -> &'static str {
    match metric {
        "ready_evidence_count" => "aggregate_ready_evidence_bundle",
        "export_policy_ready_count" => "transcript_export_policy_evidence",
        "protection_policy_ready_count" => "transcript_protection_policy_evidence",
        "runner_ready_count" => "runner_readiness_evidence",
        "transcript_bundle_ready_count" => "transcript_bundle_evidence",
        _ => "runtime_evidence_attachment",
    }
}

