fn codex_hermes_run_evidence_validation_summary_item(
    form: &CodexHermesRunEvidenceIntakeWorkbenchForm,
) -> CodexHermesRunEvidenceValidationSummaryItem {
    let recorded_field_value_count = 0;
    let missing_field_value_count = form.field_count.saturating_sub(recorded_field_value_count);
    let field_coverage_ready = missing_field_value_count == 0;
    let evidence_present = form.missing_evidence_count == 0;
    let validation_ready = form.approval_recorded && field_coverage_ready && evidence_present;

    CodexHermesRunEvidenceValidationSummaryItem {
        validation_id: format!("validation-{}", form.form_id),
        title: format!("Validation summary for {}", form.title),
        source_form_id: form.form_id.clone(),
        source_packet_id: form.source_packet_id.clone(),
        source_preview_id: form.source_preview_id.clone(),
        target_runtime: form.target_runtime,
        evidence_metric: form.evidence_metric.clone(),
        attachment_kind: form.attachment_kind,
        required_field_count: form.field_count,
        recorded_field_value_count,
        missing_field_value_count,
        missing_evidence_count: form.missing_evidence_count,
        approval_required: form.approval_required,
        approval_recorded: form.approval_recorded,
        field_coverage_ready,
        evidence_present,
        validation_ready,
        validation_blocked: !validation_ready,
        submit_enabled: false,
        status: "evidence_validation_summary_blocked_read_only",
        blocked_by: "approval, field values, and evidence records are not recorded, and validation submission is disabled in this read-only slice",
        validation_message: format!(
            "Validation remains blocked for Hermes metric {}; missing {} field value(s) and {} evidence record(s); do not submit or attach.",
            form.evidence_metric, missing_field_value_count, form.missing_evidence_count
        ),
        read_only: true,
        process_spawn_enabled: false,
        terminal_enabled: false,
        live_mcp_call_enabled: false,
        config_read_enabled: false,
        socket_connect_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        desktop_control_enabled: false,
        capture_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
    }
}

