pub fn desktop_action_safety_summary() -> Result<DesktopActionSafetySummary, String> {
    let policy = desktop_capture_action_approval_policy_dashboard()?;
    let approvals = desktop_capture_action_approval_records()?;
    let confirmations = desktop_capture_action_operator_confirmation_dry_runs()?;
    let final_preactions = desktop_capture_action_final_preaction_dry_runs()?;

    let capability_count: usize = 4;
    let confirmed_operator_evidence_recorded_count =
        final_preactions.operator_confirmation_recorded_count;
    let capability_blocked_count =
        capability_count.saturating_sub(confirmed_operator_evidence_recorded_count);

    let sections = vec![
        desktop_action_safety_summary_section(
            "desktop-policy-dashboard",
            "Desktop policy dashboard",
            "desktop-capture-action-approval-policy-dashboard",
            policy.section_count,
            policy.disabled_gate_count,
            capability_count,
            "policy_visible_actions_disabled",
            "Keep the desktop policy surface visible before any per-capability action can be considered.",
            true,
            false,
            false,
            false,
            false,
        ),
        desktop_action_safety_summary_section(
            "desktop-approval-records",
            "Desktop approval records",
            "desktop-capture-action-approval-records",
            approvals.record_count,
            approvals.policy_recorded_count,
            approvals.blocked_record_count,
            "approval_records_visible_actions_disabled",
            "Keep screenshot, OCR, target-window, and element-action approval records visible while capabilities remain blocked.",
            true,
            true,
            false,
            false,
            false,
        ),
        desktop_action_safety_summary_section(
            "operator-confirmation-dry-runs",
            "Operator confirmation dry-runs",
            "desktop-capture-action-operator-confirmation-dry-runs",
            confirmations.dry_run_count,
            confirmations.dry_run_recorded_count,
            confirmations.blocked_dry_run_count,
            "operator_confirmations_visible_actions_disabled",
            "Keep operator confirmation prompts visible while real confirmation evidence remains unrecorded.",
            false,
            true,
            true,
            false,
            false,
        ),
        desktop_action_safety_summary_section(
            "final-preaction-dry-runs",
            "Final pre-action dry-runs",
            "desktop-capture-action-final-preaction-dry-runs",
            final_preactions.dry_run_count,
            final_preactions.final_dry_run_recorded_count,
            final_preactions.blocked_dry_run_count,
            "final_preactions_visible_actions_disabled",
            "Keep confirmed-operator-evidence blockers visible before any final action gate can be considered.",
            false,
            true,
            true,
            true,
            false,
        ),
        desktop_action_safety_summary_section(
            "capability-safety-matrix",
            "Capability safety matrix",
            "desktop-action-safety-summary",
            capability_count,
            confirmed_operator_evidence_recorded_count,
            capability_blocked_count,
            "capabilities_blocked_pending_confirmed_operator_evidence",
            "Require confirmed operator evidence and another final pre-action pass before opening any screenshot, OCR, target-window, or element-action gate.",
            true,
            true,
            true,
            true,
            true,
        ),
    ];

    let disabled_gate_count = sections
        .iter()
        .filter(|section| {
            section.read_only
                && !section.capture_enabled
                && !section.ocr_enabled
                && !section.target_window_control_enabled
                && !section.element_action_enabled
                && !section.desktop_control_enabled
                && !section.socket_connect_enabled
                && !section.process_spawn_enabled
                && !section.terminal_enabled
                && !section.file_write_enabled
                && !section.patch_apply_enabled
                && !section.live_mcp_call_enabled
                && !section.config_read_enabled
                && !section.export_enabled
                && !section.memory_write_enabled
                && !section.writes_allowed
                && !section.execution_enabled
        })
        .count();

    Ok(DesktopActionSafetySummary {
        status: "desktop_action_safety_summary_read_only",
        section_count: sections.len(),
        policy_section_count: policy.section_count,
        policy_ready_section_count: policy.disabled_gate_count,
        approval_record_count: approvals.record_count,
        approval_recorded_count: approvals.policy_recorded_count,
        confirmation_dry_run_count: confirmations.dry_run_count,
        confirmation_dry_run_recorded_count: confirmations.dry_run_recorded_count,
        final_preaction_dry_run_count: final_preactions.dry_run_count,
        final_preaction_dry_run_recorded_count: final_preactions.final_dry_run_recorded_count,
        confirmed_operator_evidence_required_count: final_preactions
            .confirmed_operator_evidence_required_count,
        confirmed_operator_evidence_recorded_count,
        capability_count,
        capability_blocked_count,
        disabled_gate_count,
        read_only: true,
        capture_enabled: false,
        ocr_enabled: false,
        target_window_control_enabled: false,
        element_action_enabled: false,
        desktop_control_enabled: false,
        socket_connect_enabled: false,
        process_spawn_enabled: false,
        terminal_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        live_mcp_call_enabled: false,
        config_read_enabled: false,
        export_enabled: false,
        memory_write_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        sections,
        reasons: vec![
            "summary ties desktop policy, approval records, operator confirmation dry-runs, final pre-action dry-runs, and capability blockers into one operator view",
            "summary derives from sealed read-only desktop safety surfaces and creates no real confirmations, captures, OCR output, focus changes, element actions, files, patches, exports, memory writes, process activity, or execution",
            "capture, OCR, target-window control, element actions, desktop control, sockets, process spawn, terminal control, file writes, patches, live MCP calls, config reads, exports, memory writes, workspace writes, and execution remain disabled",
        ],
        next_slice: "Use this safety summary to add a Linux desktop readiness release checklist before any live desktop capability gate is opened.",
    })
}

