fn lease_scopes_overlap(left: &[String], right: &[String]) -> bool {
    left.iter().any(|left_scope| {
        right.iter().any(|right_scope| {
            left_scope == "*"
                || right_scope == "*"
                || left_scope == right_scope
                || left_scope.starts_with(&format!("{right_scope}/"))
                || right_scope.starts_with(&format!("{left_scope}/"))
        })
    })
}

#[tauri::command]
pub fn create_workspace_lease_stub(
    request: WorkspaceLeaseRequest,
) -> Result<WorkspaceLeaseResult, String> {
    if read_task_run_record(&request.task_run_id)?.is_none() {
        return Err("task run record is required before creating a workspace lease".to_string());
    }

    let timestamp = now_ms()?;
    let id = format!(
        "workspace-lease-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug(&request.owner_runtime)
    );
    let dir = workspace_leases_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create workspace-leases directory {}: {error}",
            dir.display()
        )
    })?;
    let existing_leases = list_workspace_leases()?;
    let conflicting_lease_ids: Vec<String> = existing_leases
        .iter()
        .filter(|lease| {
            lease.workspace_path == request.workspace_path
                && lease_scopes_overlap(&lease.write_scope, &request.write_scope)
        })
        .map(|lease| lease.id.clone())
        .collect();
    let status = if conflicting_lease_ids.is_empty() {
        "recorded_no_conflict_execution_disabled"
    } else {
        "recorded_conflict_execution_disabled"
    }
    .to_string();
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let purpose_preview: String = request.purpose.chars().take(220).collect();
    let lease = WorkspaceLeaseRecord {
        id: id.clone(),
        task_run_id: request.task_run_id,
        workspace_path: request.workspace_path,
        owner_runtime: request.owner_runtime,
        purpose_preview,
        write_scope: request.write_scope,
        requested_mode: request
            .requested_mode
            .unwrap_or_else(|| "workspace_write".to_string()),
        status: status.clone(),
        conflicting_lease_ids,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reason: "Workspace lease is recorded for future coordination only; writes remain disabled.".to_string(),
        next_step: "Connect leases to the runner gate before any Codex or Hermes write-capable phase is enabled.".to_string(),
    };

    let json = serde_json::to_string_pretty(&lease)
        .map_err(|error| format!("failed to serialize workspace lease: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write workspace lease {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "workspace_lease_stub_created",
            "id": id,
            "task_run_id": lease.task_run_id,
            "owner_runtime": lease.owner_runtime,
            "status": lease.status,
            "conflict_count": lease.conflicting_lease_ids.len(),
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(WorkspaceLeaseResult {
        accepted: false,
        task_run_found: true,
        conflict_count: lease.conflicting_lease_ids.len(),
        writes_allowed: false,
        execution_enabled: false,
        lease,
    })
}

#[tauri::command]
pub fn list_workspace_leases() -> Result<Vec<WorkspaceLeaseRecord>, String> {
    let dir = workspace_leases_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir)
        .map_err(|error| format!("failed to read workspace-leases directory {}: {error}", dir.display()))?
    {
        let entry = entry.map_err(|error| format!("failed to read workspace lease entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<WorkspaceLeaseRecord>(&content) {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

#[tauri::command]
pub fn create_workspace_inspection_record_stub(
    request: WorkspaceInspectionRequest,
) -> Result<WorkspaceInspectionResult, String> {
    let timestamp = now_ms()?;
    let id = format!(
        "workspace-inspection-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug(&request.workspace_path)
    );
    let dir = workspace_inspections_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create workspace-inspections directory {}: {error}",
            dir.display()
        )
    })?;

    let workspace_path_is_absolute = Path::new(&request.workspace_path).is_absolute();
    let mut reasons = Vec::new();
    if !workspace_path_is_absolute {
        reasons.push("workspace path is relative; future live reads require an absolute scoped root".to_string());
    }

    let query: String = request.query.chars().take(160).collect();
    let mut ignore_patterns: Vec<String> = request
        .ignore_patterns
        .into_iter()
        .map(|pattern| pattern.chars().take(80).collect::<String>())
        .filter(|pattern| !pattern.trim().is_empty())
        .take(12)
        .collect();
    if ignore_patterns.is_empty() {
        ignore_patterns = vec![
            "node_modules".to_string(),
            "target".to_string(),
            ".git".to_string(),
            ".sswp.json".to_string(),
            "gravity-omega.sswp.json".to_string(),
        ];
    }

    reasons.push("workspace inspection recorded without reading files, searching content, applying patches, or spawning terminals".to_string());
    let status = if workspace_path_is_absolute {
        "workspace_inspection_recorded_read_only"
    } else {
        "workspace_inspection_recorded_relative_path_blocked"
    }
    .to_string();

    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let record = WorkspaceInspectionRecord {
        id: id.clone(),
        workspace_path: request.workspace_path,
        workspace_path_is_absolute,
        query,
        ignore_patterns,
        intended_surfaces: vec![
            "file_tree".to_string(),
            "file_read".to_string(),
            "workspace_search_text".to_string(),
            "workspace_diff".to_string(),
        ],
        status: status.clone(),
        read_only: true,
        file_tree_enabled: true,
        file_read_enabled: true,
        search_enabled: true,
        diff_enabled: true,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Implement scoped filesystem reads with ignore-aware traversal before enabling live file tree, read, search, or diff operations.".to_string(),
    };

    let json = serde_json::to_string_pretty(&record)
        .map_err(|error| format!("failed to serialize workspace inspection: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write workspace inspection {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "workspace_inspection_record_stub_created",
            "id": id,
            "workspace_path": record.workspace_path,
            "status": record.status,
            "read_only": true,
            "file_tree_enabled": true,
            "file_read_enabled": true,
            "search_enabled": true,
            "diff_enabled": true,
            "file_write_enabled": false,
            "patch_apply_enabled": false,
            "terminal_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(WorkspaceInspectionResult {
        accepted: false,
        inspection_recorded: true,
        read_only: true,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        record,
    })
}

#[tauri::command]
pub fn list_workspace_inspection_records() -> Result<Vec<WorkspaceInspectionRecord>, String> {
    let dir = workspace_inspections_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read workspace-inspections directory {}: {error}",
            dir.display()
        )
    })? {
        let entry =
            entry.map_err(|error| format!("failed to read workspace inspection entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<WorkspaceInspectionRecord>(&content) {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

#[tauri::command]
pub fn create_workspace_preview_record_stub(
    request: WorkspacePreviewRequest,
) -> Result<WorkspacePreviewResult, String> {
    let timestamp = now_ms()?;
    let workspace_inspection_id = request.workspace_inspection_id;
    let inspection = read_workspace_inspection_record(&workspace_inspection_id)?;
    let (workspace_inspection_found, inspection_ready, workspace_path, ignored_patterns) =
        match inspection {
            Some(record) => (
                true,
                workspace_inspection_ready(&record),
                record.workspace_path,
                record.ignore_patterns,
            ),
            None => (
                false,
                false,
                "unresolved".to_string(),
                vec![
                    "node_modules".to_string(),
                    "target".to_string(),
                    ".git".to_string(),
                    ".sswp.json".to_string(),
                    "gravity-omega.sswp.json".to_string(),
                ],
            ),
        };
    let (requested_paths, preview_paths, dropped_path_count) =
        sanitize_workspace_preview_paths(request.requested_paths, &ignored_patterns);

    let id = format!(
        "workspace-preview-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug(&workspace_inspection_id)
    );
    let dir = workspace_previews_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create workspace-previews directory {}: {error}",
            dir.display()
        )
    })?;

    let tree_preview_enabled = inspection_ready;
    let metadata_preview_enabled = inspection_ready;
    let status = if !workspace_inspection_found {
        "blocked_missing_workspace_inspection"
    } else if !inspection_ready {
        "blocked_workspace_inspection_not_ready"
    } else {
        "workspace_preview_recorded_read_only"
    }
    .to_string();

    let mut reasons = Vec::new();
    if !workspace_inspection_found {
        reasons.push("workspace preview requires an existing read-only workspace inspection record".to_string());
    } else if !inspection_ready {
        reasons.push("workspace inspection exists but is not a ready read-only inspection checkpoint".to_string());
    } else {
        reasons.push("workspace preview recorded without traversing directories or reading file contents".to_string());
    }
    if dropped_path_count > 0 {
        reasons.push(format!(
            "{dropped_path_count} requested path(s) were ignored or rejected by preview policy"
        ));
    }
    reasons.push("SSWP project files remain excluded by ignore policy unless explicitly approved later".to_string());

    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let record = WorkspacePreviewRecord {
        id: id.clone(),
        workspace_inspection_id: workspace_inspection_id.clone(),
        workspace_path: workspace_path.clone(),
        preview_root: workspace_path,
        requested_paths,
        preview_paths,
        ignored_patterns,
        status: status.clone(),
        workspace_inspection_found,
        inspection_ready,
        tree_preview_enabled,
        metadata_preview_enabled,
        file_content_read_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Implement scoped metadata traversal before enabling live file tree rendering or explicit file content preview.".to_string(),
    };

    let json = serde_json::to_string_pretty(&record)
        .map_err(|error| format!("failed to serialize workspace preview: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write workspace preview {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "workspace_preview_record_stub_created",
            "id": id,
            "workspace_inspection_id": workspace_inspection_id,
            "status": record.status,
            "workspace_inspection_found": record.workspace_inspection_found,
            "inspection_ready": record.inspection_ready,
            "preview_path_count": record.preview_paths.len(),
            "tree_preview_enabled": record.tree_preview_enabled,
            "metadata_preview_enabled": record.metadata_preview_enabled,
            "file_content_read_enabled": false,
            "file_write_enabled": false,
            "patch_apply_enabled": false,
            "terminal_enabled": false,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(WorkspacePreviewResult {
        accepted: false,
        preview_recorded: true,
        workspace_inspection_found: record.workspace_inspection_found,
        inspection_ready: record.inspection_ready,
        tree_preview_enabled: record.tree_preview_enabled,
        metadata_preview_enabled: record.metadata_preview_enabled,
        file_content_read_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        record,
    })
}

