#[tauri::command]
pub fn create_workspace_tree_metadata_record_stub(
    request: WorkspaceTreeMetadataRequest,
) -> Result<WorkspaceTreeMetadataResult, String> {
    let timestamp = now_ms()?;
    let workspace_preview_id = request.workspace_preview_id;
    let preview = read_workspace_preview_record(&workspace_preview_id)?;
    let (workspace_preview_found, preview_ready, workspace_inspection_id, workspace_path, traversal_root, ignored_patterns) =
        match preview {
            Some(record) => (
                true,
                workspace_preview_ready(&record),
                record.workspace_inspection_id,
                record.workspace_path,
                record.preview_root,
                record.ignored_patterns,
            ),
            None => (
                false,
                false,
                "unresolved".to_string(),
                "unresolved".to_string(),
                "unresolved".to_string(),
                vec![
                    "node_modules".to_string(),
                    "target".to_string(),
                    ".git".to_string(),
                    ".sswp.json".to_string(),
                    "gravity-omega.sswp.json".to_string(),
                ],
            ),
        };

    let max_depth = request.max_depth.unwrap_or(3).clamp(1, 5);
    let max_entries = request.max_entries.unwrap_or(80).clamp(1, 240);
    let root_path = PathBuf::from(&traversal_root);
    let root_is_absolute = root_path.is_absolute();
    let root_exists = root_path.exists();
    let root_is_directory = root_path.is_dir();
    let metadata_traversal_enabled =
        preview_ready && root_is_absolute && root_exists && root_is_directory;

    let collection = if metadata_traversal_enabled {
        collect_workspace_tree_metadata(&root_path, &ignored_patterns, max_depth, max_entries)
    } else {
        WorkspaceTreeCollection::default()
    };
    let directory_count = collection
        .entries
        .iter()
        .filter(|entry| entry.kind == "directory")
        .count();
    let file_count = collection
        .entries
        .iter()
        .filter(|entry| entry.kind == "file")
        .count();
    let symlink_count = collection.entries.iter().filter(|entry| entry.symlink).count();

    let status = if !workspace_preview_found {
        "blocked_missing_workspace_preview"
    } else if !preview_ready {
        "blocked_workspace_preview_not_ready"
    } else if !root_is_absolute {
        "blocked_workspace_root_not_absolute"
    } else if !root_exists {
        "blocked_workspace_root_missing"
    } else if !root_is_directory {
        "blocked_workspace_root_not_directory"
    } else {
        "workspace_tree_metadata_recorded_read_only"
    }
    .to_string();

    let mut reasons = Vec::new();
    if !workspace_preview_found {
        reasons.push("workspace tree metadata requires an existing read-only workspace preview record".to_string());
    } else if !preview_ready {
        reasons.push("workspace preview exists but is not a ready read-only preview checkpoint".to_string());
    } else if !root_is_absolute {
        reasons.push("workspace tree metadata requires an absolute preview root".to_string());
    } else if !root_exists {
        reasons.push("workspace preview root does not exist on disk".to_string());
    } else if !root_is_directory {
        reasons.push("workspace preview root is not a directory".to_string());
    } else {
        reasons.push("workspace tree metadata recorded without reading file contents, following symlink directories, applying patches, or spawning terminals".to_string());
    }
    if collection.truncated {
        reasons.push(format!(
            "metadata traversal stopped at {max_entries} entries by policy"
        ));
    }
    if collection.skipped_ignored_count > 0 {
        reasons.push(format!(
            "{} ignored path(s) were skipped by workspace policy",
            collection.skipped_ignored_count
        ));
    }
    if collection.skipped_symlink_count > 0 {
        reasons.push(format!(
            "{} symlink path(s) were recorded but not followed",
            collection.skipped_symlink_count
        ));
    }

    let id = format!(
        "workspace-tree-metadata-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug(&workspace_preview_id)
    );
    let dir = workspace_tree_metadata_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create workspace-tree-metadata directory {}: {error}",
            dir.display()
        )
    })?;
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let read_error_count = collection.read_errors.len();
    let record = WorkspaceTreeMetadataRecord {
        id: id.clone(),
        workspace_preview_id: workspace_preview_id.clone(),
        workspace_inspection_id,
        workspace_path,
        traversal_root,
        status: status.clone(),
        workspace_preview_found,
        preview_ready,
        root_is_absolute,
        root_exists,
        root_is_directory,
        max_depth,
        max_entries,
        entry_count: collection.entries.len(),
        directory_count,
        file_count,
        symlink_count,
        skipped_ignored_count: collection.skipped_ignored_count,
        skipped_symlink_count: collection.skipped_symlink_count,
        read_error_count,
        truncated: collection.truncated,
        entries: collection.entries,
        ignored_patterns,
        metadata_traversal_enabled,
        file_content_read_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        read_errors: collection.read_errors,
        reasons,
        next_step: "Implement explicit file content preview behind size, binary, and approval-safe read limits before opening editor tabs.".to_string(),
    };

    let json = serde_json::to_string_pretty(&record)
        .map_err(|error| format!("failed to serialize workspace tree metadata: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write workspace tree metadata {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "workspace_tree_metadata_record_stub_created",
            "id": id,
            "workspace_preview_id": workspace_preview_id,
            "status": record.status,
            "metadata_traversal_enabled": record.metadata_traversal_enabled,
            "entry_count": record.entry_count,
            "directory_count": record.directory_count,
            "file_count": record.file_count,
            "symlink_count": record.symlink_count,
            "skipped_ignored_count": record.skipped_ignored_count,
            "skipped_symlink_count": record.skipped_symlink_count,
            "file_content_read_enabled": false,
            "file_write_enabled": false,
            "patch_apply_enabled": false,
            "terminal_enabled": false,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(WorkspaceTreeMetadataResult {
        accepted: false,
        metadata_recorded: true,
        workspace_preview_found: record.workspace_preview_found,
        preview_ready: record.preview_ready,
        metadata_traversal_enabled: record.metadata_traversal_enabled,
        file_content_read_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        record,
    })
}

