#[tauri::command]
pub fn create_workspace_file_content_preview_record_stub(
    request: WorkspaceFileContentPreviewRequest,
) -> Result<WorkspaceFileContentPreviewResult, String> {
    let timestamp = now_ms()?;
    let workspace_tree_metadata_id = request.workspace_tree_metadata_id;
    let normalized_relative_path = normalize_workspace_preview_path(&request.relative_path);
    let relative_path = normalized_relative_path
        .clone()
        .unwrap_or_else(|| request.relative_path.chars().take(160).collect());
    let max_bytes = request.max_bytes.unwrap_or(8192).clamp(1, 65536);
    let tree_metadata = read_workspace_tree_metadata_record(&workspace_tree_metadata_id)?;
    let (
        tree_metadata_found,
        tree_metadata_ready,
        workspace_preview_id,
        workspace_inspection_id,
        workspace_path,
        traversal_root,
        ignored_patterns,
        entries,
    ) = match tree_metadata {
        Some(record) => (
            true,
            workspace_tree_metadata_ready(&record),
            record.workspace_preview_id,
            record.workspace_inspection_id,
            record.workspace_path,
            record.traversal_root,
            record.ignored_patterns,
            record.entries,
        ),
        None => (
            false,
            false,
            "unresolved".to_string(),
            "unresolved".to_string(),
            "unresolved".to_string(),
            "unresolved".to_string(),
            vec![
                "node_modules".to_string(),
                "target".to_string(),
                ".git".to_string(),
                ".sswp.json".to_string(),
                "gravity-omega.sswp.json".to_string(),
            ],
            Vec::new(),
        ),
    };

    let path_valid = normalized_relative_path.is_some();
    let path_ignored = path_valid && workspace_preview_path_ignored(&relative_path, &ignored_patterns);
    let tree_entry = entries
        .iter()
        .find(|entry| entry.relative_path == relative_path)
        .cloned();
    let path_found_in_tree = tree_entry.is_some();
    let tree_entry_is_regular = tree_entry
        .as_ref()
        .map(|entry| entry.kind == "file")
        .unwrap_or(false);
    let tree_entry_is_symlink = tree_entry
        .as_ref()
        .map(|entry| entry.symlink)
        .unwrap_or(false);
    let root_path = PathBuf::from(&traversal_root);
    let absolute_path = if path_valid {
        root_path.join(&relative_path)
    } else {
        root_path.clone()
    };
    let absolute_path_display = absolute_path.display().to_string();
    let metadata = if path_valid {
        fs::symlink_metadata(&absolute_path).ok()
    } else {
        None
    };
    let file_exists = metadata.is_some();
    let file_is_symlink = metadata
        .as_ref()
        .map(|metadata| metadata.file_type().is_symlink())
        .unwrap_or(false)
        || tree_entry_is_symlink;
    let file_is_regular = metadata
        .as_ref()
        .map(|metadata| metadata.file_type().is_file())
        .unwrap_or(false)
        && tree_entry_is_regular
        && !file_is_symlink;
    let file_size_bytes = metadata.as_ref().map(|metadata| metadata.len()).unwrap_or(0);
    let root_scope_valid = if path_valid && file_exists {
        match (root_path.canonicalize(), absolute_path.canonicalize()) {
            (Ok(root), Ok(file)) => file.starts_with(root),
            _ => false,
        }
    } else {
        false
    };

    let can_read_text_sample = tree_metadata_found
        && tree_metadata_ready
        && path_valid
        && !path_ignored
        && path_found_in_tree
        && file_is_regular
        && !file_is_symlink
        && root_scope_valid
        && file_exists;

    let mut raw_bytes = Vec::new();
    let mut read_error = None;
    if can_read_text_sample {
        match fs::File::open(&absolute_path) {
            Ok(mut file) => {
                let mut limited = std::io::Read::by_ref(&mut file).take((max_bytes + 1) as u64);
                if let Err(error) = limited.read_to_end(&mut raw_bytes) {
                    read_error = Some(format!("{error}"));
                    raw_bytes.clear();
                }
            }
            Err(error) => read_error = Some(format!("{error}")),
        }
    }

    let read_error_present = read_error.is_some();
    let truncated = raw_bytes.len() > max_bytes || file_size_bytes > max_bytes as u64;
    if raw_bytes.len() > max_bytes {
        raw_bytes.truncate(max_bytes);
    }
    let utf8_valid = std::str::from_utf8(&raw_bytes).is_ok();
    let binary_detected = !raw_bytes.is_empty() && bytes_look_binary(&raw_bytes);
    let preview_text = if can_read_text_sample && !read_error_present && !binary_detected {
        String::from_utf8(raw_bytes.clone()).unwrap_or_default()
    } else {
        String::new()
    };
    let preview_line_count = if preview_text.is_empty() {
        0
    } else {
        preview_text.lines().count()
    };
    let bytes_read = raw_bytes.len();

    let status = if !tree_metadata_found {
        "blocked_missing_workspace_tree_metadata"
    } else if !tree_metadata_ready {
        "blocked_workspace_tree_metadata_not_ready"
    } else if !path_valid {
        "blocked_invalid_relative_path"
    } else if path_ignored {
        "blocked_ignored_relative_path"
    } else if !path_found_in_tree {
        "blocked_path_not_in_tree_metadata"
    } else if file_is_symlink {
        "blocked_symlink_file_preview"
    } else if !file_exists {
        "blocked_file_missing"
    } else if !file_is_regular {
        "blocked_path_not_regular_file"
    } else if !root_scope_valid {
        "blocked_scope_validation_failed"
    } else if read_error_present {
        "blocked_file_read_error"
    } else if binary_detected {
        "blocked_binary_file_preview"
    } else {
        "file_content_preview_recorded_read_only"
    }
    .to_string();
    let file_content_read_enabled = status == "file_content_preview_recorded_read_only";

    let mut reasons = Vec::new();
    if !tree_metadata_found {
        reasons.push("file content preview requires an existing workspace tree metadata record".to_string());
    } else if !tree_metadata_ready {
        reasons.push("workspace tree metadata exists but is not a ready read-only tree checkpoint".to_string());
    } else if !path_valid {
        reasons.push("requested preview path must be relative and must not contain dot-dot segments".to_string());
    } else if path_ignored {
        reasons.push("requested preview path is blocked by workspace ignore policy".to_string());
    } else if !path_found_in_tree {
        reasons.push("requested preview path is not present in the recorded tree metadata".to_string());
    } else if file_is_symlink {
        reasons.push("symlink targets are not read by file content preview".to_string());
    } else if !file_exists {
        reasons.push("requested preview file is missing from disk".to_string());
    } else if !file_is_regular {
        reasons.push("requested preview path is not a regular file".to_string());
    } else if !root_scope_valid {
        reasons.push("requested preview path failed root scope validation".to_string());
    } else if read_error_present {
        reasons.push("requested preview file could not be read".to_string());
    } else if binary_detected {
        reasons.push("binary or non-UTF-8 content was detected; text preview was not stored".to_string());
    } else {
        reasons.push("file content preview recorded with bounded bytes, UTF-8 text only, no writes, no patching, and no execution".to_string());
    }
    if truncated {
        reasons.push(format!(
            "preview was capped at {max_bytes} byte(s) by policy"
        ));
    }

    let id = format!(
        "workspace-file-preview-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug_limit(&relative_path, 48)
    );
    let dir = workspace_file_previews_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create workspace-file-previews directory {}: {error}",
            dir.display()
        )
    })?;
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let record = WorkspaceFileContentPreviewRecord {
        id: id.clone(),
        workspace_tree_metadata_id: workspace_tree_metadata_id.clone(),
        workspace_preview_id,
        workspace_inspection_id,
        workspace_path,
        traversal_root,
        relative_path: relative_path.clone(),
        absolute_path: absolute_path_display,
        status: status.clone(),
        tree_metadata_found,
        tree_metadata_ready,
        path_valid,
        path_ignored,
        path_found_in_tree,
        root_scope_valid,
        file_exists,
        file_is_regular,
        file_is_symlink,
        max_bytes,
        file_size_bytes,
        bytes_read,
        truncated,
        binary_detected,
        utf8_valid,
        preview_text,
        preview_line_count,
        file_content_read_enabled,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        read_error,
        reasons,
        next_step: "Wire preview text into editor tabs only after explicit read-only tab state, dirty tracking, and save gates are implemented.".to_string(),
    };

    let json = serde_json::to_string_pretty(&record)
        .map_err(|error| format!("failed to serialize workspace file preview: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write workspace file preview {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "workspace_file_content_preview_record_stub_created",
            "id": id,
            "workspace_tree_metadata_id": workspace_tree_metadata_id,
            "relative_path": record.relative_path,
            "status": record.status,
            "bytes_read": record.bytes_read,
            "max_bytes": record.max_bytes,
            "truncated": record.truncated,
            "binary_detected": record.binary_detected,
            "file_content_read_enabled": record.file_content_read_enabled,
            "file_write_enabled": false,
            "patch_apply_enabled": false,
            "terminal_enabled": false,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(WorkspaceFileContentPreviewResult {
        accepted: false,
        preview_recorded: true,
        tree_metadata_found: record.tree_metadata_found,
        tree_metadata_ready: record.tree_metadata_ready,
        file_content_read_enabled: record.file_content_read_enabled,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        record,
    })
}

#[tauri::command]
pub fn list_workspace_file_content_preview_records(
) -> Result<Vec<WorkspaceFileContentPreviewRecord>, String> {
    let dir = workspace_file_previews_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read workspace-file-previews directory {}: {error}",
            dir.display()
        )
    })? {
        let entry =
            entry.map_err(|error| format!("failed to read workspace file preview entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<WorkspaceFileContentPreviewRecord>(&content) {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

#[tauri::command]
pub fn create_workspace_editor_tab_state_stub(
    request: WorkspaceEditorTabStateRequest,
) -> Result<WorkspaceEditorTabStateResult, String> {
    let timestamp = now_ms()?;
    let workspace_file_preview_id = request.workspace_file_preview_id;
    let file_preview = read_workspace_file_content_preview_record(&workspace_file_preview_id)?;
    let (
        file_preview_found,
        file_preview_ready,
        workspace_tree_metadata_id,
        workspace_preview_id,
        workspace_inspection_id,
        workspace_path,
        relative_path,
        source_bytes_read,
        source_truncated,
        source_binary_detected,
        preview_text,
        preview_line_count,
    ) = match file_preview {
        Some(record) => (
            true,
            workspace_file_preview_ready(&record),
            record.workspace_tree_metadata_id,
            record.workspace_preview_id,
            record.workspace_inspection_id,
            record.workspace_path,
            record.relative_path,
            record.bytes_read,
            record.truncated,
            record.binary_detected,
            record.preview_text,
            record.preview_line_count,
        ),
        None => (
            false,
            false,
            "unresolved".to_string(),
            "unresolved".to_string(),
            "unresolved".to_string(),
            "unresolved".to_string(),
            "unresolved".to_string(),
            0,
            false,
            false,
            String::new(),
            0,
        ),
    };
    let tab_title = editor_tab_title(&relative_path, request.preferred_tab_title);
    let editor_tab_enabled = file_preview_ready;
    let buffer_attached = file_preview_ready;
    let status = if !file_preview_found {
        "blocked_missing_workspace_file_preview"
    } else if !file_preview_ready {
        "blocked_workspace_file_preview_not_ready"
    } else {
        "editor_tab_state_recorded_read_only"
    }
    .to_string();

    let mut reasons = Vec::new();
    if !file_preview_found {
        reasons.push("editor tab state requires an existing file content preview record".to_string());
    } else if !file_preview_ready {
        reasons.push("file content preview exists but is not a successful UTF-8 read-only preview".to_string());
    } else {
        reasons.push("editor tab state recorded from an existing preview snapshot without rereading files, editing buffers, saving, patching, or executing commands".to_string());
    }

    let id = format!(
        "workspace-editor-tab-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug_limit(&workspace_file_preview_id, 64)
    );
    let dir = workspace_editor_tabs_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create workspace-editor-tabs directory {}: {error}",
            dir.display()
        )
    })?;
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let record = WorkspaceEditorTabStateRecord {
        id: id.clone(),
        workspace_file_preview_id: workspace_file_preview_id.clone(),
        workspace_tree_metadata_id,
        workspace_preview_id,
        workspace_inspection_id,
        workspace_path,
        relative_path,
        tab_title,
        status: status.clone(),
        file_preview_found,
        file_preview_ready,
        editor_tab_enabled,
        buffer_attached,
        buffer_preview_text: if buffer_attached {
            preview_text
        } else {
            String::new()
        },
        buffer_line_count: if buffer_attached {
            preview_line_count
        } else {
            0
        },
        source_bytes_read,
        source_truncated,
        source_binary_detected,
        cursor_line: 1,
        cursor_column: 1,
        selection_start: 0,
        selection_end: 0,
        dirty: false,
        editable: false,
        file_content_read_enabled: false,
        save_enabled: false,
        save_as_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Implement explicit edit buffers, dirty tracking transitions, and save approvals before enabling any writable editor tab.".to_string(),
    };

    let json = serde_json::to_string_pretty(&record)
        .map_err(|error| format!("failed to serialize workspace editor tab state: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write workspace editor tab state {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "workspace_editor_tab_state_stub_created",
            "id": id,
            "workspace_file_preview_id": workspace_file_preview_id,
            "relative_path": record.relative_path,
            "status": record.status,
            "editor_tab_enabled": record.editor_tab_enabled,
            "buffer_attached": record.buffer_attached,
            "dirty": false,
            "editable": false,
            "file_content_read_enabled": false,
            "save_enabled": false,
            "file_write_enabled": false,
            "patch_apply_enabled": false,
            "terminal_enabled": false,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(WorkspaceEditorTabStateResult {
        accepted: false,
        tab_recorded: true,
        file_preview_found: record.file_preview_found,
        file_preview_ready: record.file_preview_ready,
        editor_tab_enabled: record.editor_tab_enabled,
        buffer_attached: record.buffer_attached,
        dirty: false,
        editable: false,
        save_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        record,
    })
}

