#[tauri::command]
pub fn create_workspace_edit_preflight_stub(
    request: WorkspaceEditPreflightRequest,
) -> Result<WorkspaceEditPreflightResult, String> {
    let timestamp = now_ms()?;
    let workspace_editor_tab_id = request.workspace_editor_tab_id;
    let normalized_action = normalize_edit_preflight_action(&request.requested_action);
    let requested_action = request.requested_action.trim().chars().take(40).collect::<String>();
    let proposed_summary = request
        .proposed_summary
        .unwrap_or_default()
        .trim()
        .chars()
        .take(180)
        .collect::<String>();
    let tab = read_workspace_editor_tab_state_record(&workspace_editor_tab_id)?;
    let (
        editor_tab_found,
        editor_tab_ready,
        workspace_file_preview_id,
        workspace_tree_metadata_id,
        workspace_path,
        relative_path,
        tab_title,
        buffer_attached,
        dirty_before,
    ) = match tab {
        Some(record) => (
            true,
            workspace_editor_tab_ready(&record),
            record.workspace_file_preview_id,
            record.workspace_tree_metadata_id,
            record.workspace_path,
            record.relative_path,
            record.tab_title,
            record.buffer_attached,
            record.dirty,
        ),
        None => (
            false,
            false,
            "unresolved".to_string(),
            "unresolved".to_string(),
            "unresolved".to_string(),
            "unresolved".to_string(),
            "unresolved".to_string(),
            false,
            false,
        ),
    };
    let supported_action = normalized_action != "unsupported";
    let edit_intent_recorded = editor_tab_ready && normalized_action == "edit";
    let save_gate_recorded =
        editor_tab_ready && (normalized_action == "save" || normalized_action == "save_as");
    let status = if !editor_tab_found {
        "blocked_missing_workspace_editor_tab"
    } else if !editor_tab_ready {
        "blocked_workspace_editor_tab_not_ready"
    } else if !supported_action {
        "blocked_unsupported_edit_preflight_action"
    } else if normalized_action == "edit" {
        "edit_intent_recorded_mutation_disabled"
    } else {
        "save_gate_recorded_write_disabled"
    }
    .to_string();

    let mut reasons = Vec::new();
    if !editor_tab_found {
        reasons.push("edit/save preflight requires an existing editor tab state record".to_string());
    } else if !editor_tab_ready {
        reasons.push("editor tab exists but is not a ready read-only tab state".to_string());
    } else if !supported_action {
        reasons.push("requested preflight action is not supported".to_string());
    } else if normalized_action == "edit" {
        reasons.push("edit intent recorded without mutating the buffer or marking the tab dirty".to_string());
    } else {
        reasons.push("save gate recorded without enabling save, save-as, file writes, patches, or execution".to_string());
    }

    let id = format!(
        "workspace-edit-preflight-{}-{}-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug_limit(&normalized_action, 24),
        slug_limit(&relative_path, 40),
        slug_limit(&workspace_editor_tab_id, 48)
    );
    let dir = workspace_edit_preflights_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create workspace-edit-preflights directory {}: {error}",
            dir.display()
        )
    })?;
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let record = WorkspaceEditPreflightRecord {
        id: id.clone(),
        workspace_editor_tab_id: workspace_editor_tab_id.clone(),
        workspace_file_preview_id,
        workspace_tree_metadata_id,
        workspace_path,
        relative_path,
        tab_title,
        requested_action,
        normalized_action: normalized_action.clone(),
        proposed_summary,
        status: status.clone(),
        editor_tab_found,
        editor_tab_ready,
        buffer_attached,
        dirty_before,
        edit_intent_recorded,
        save_gate_recorded,
        edit_enabled: false,
        buffer_mutation_enabled: false,
        dirty_transition_enabled: false,
        file_content_read_enabled: false,
        save_enabled: false,
        save_as_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Implement explicit editable buffers, dirty transitions, approval prompts, and atomic save commands before enabling writes.".to_string(),
    };

    let json = serde_json::to_string_pretty(&record)
        .map_err(|error| format!("failed to serialize workspace edit preflight: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write workspace edit preflight {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "workspace_edit_preflight_stub_created",
            "id": id,
            "workspace_editor_tab_id": workspace_editor_tab_id,
            "normalized_action": record.normalized_action,
            "status": record.status,
            "edit_intent_recorded": record.edit_intent_recorded,
            "save_gate_recorded": record.save_gate_recorded,
            "edit_enabled": false,
            "save_enabled": false,
            "file_write_enabled": false,
            "patch_apply_enabled": false,
            "terminal_enabled": false,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(WorkspaceEditPreflightResult {
        accepted: false,
        preflight_recorded: true,
        editor_tab_found: record.editor_tab_found,
        editor_tab_ready: record.editor_tab_ready,
        edit_intent_recorded: record.edit_intent_recorded,
        save_gate_recorded: record.save_gate_recorded,
        edit_enabled: false,
        save_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        record,
    })
}

