#[tauri::command]
pub fn create_workspace_write_approval_stub(
    request: WorkspaceWriteApprovalRequest,
) -> Result<WorkspaceWriteApprovalResult, String> {
    let timestamp = now_ms()?;
    let workspace_write_policy_id = request.workspace_write_policy_id;
    let approval_id = request.approval_id;
    let policy = read_workspace_write_approval_policy_record(&workspace_write_policy_id)?;
    let (
        write_policy_found,
        write_policy_ready,
        workspace_edit_preflight_id,
        workspace_editor_tab_id,
        workspace_file_preview_id,
        workspace_tree_metadata_id,
        workspace_path,
        relative_path,
        tab_title,
        normalized_action,
        requires_diff_preview,
        requires_clean_base,
        requires_backup_snapshot,
        requires_atomic_write,
        requires_user_confirmed_path,
        policy_approval_tier,
    ) = match policy {
        Some(record) => (
            true,
            workspace_write_policy_ready(&record),
            record.workspace_edit_preflight_id,
            record.workspace_editor_tab_id,
            record.workspace_file_preview_id,
            record.workspace_tree_metadata_id,
            record.workspace_path,
            record.relative_path,
            record.tab_title,
            record.normalized_action,
            record.requires_diff_preview,
            record.requires_clean_base,
            record.requires_backup_snapshot,
            record.requires_atomic_write,
            record.requires_user_confirmed_path,
            record.approval_tier,
        ),
        None => (
            false,
            false,
            "unresolved".to_string(),
            "unresolved".to_string(),
            "unresolved".to_string(),
            "unresolved".to_string(),
            "unresolved".to_string(),
            "unresolved".to_string(),
            "unresolved".to_string(),
            "unsupported".to_string(),
            false,
            false,
            false,
            false,
            false,
            "unresolved".to_string(),
        ),
    };

    let expected_command_id = workspace_write_approval_command_id(&normalized_action).to_string();
    let approval = read_approval_record(&approval_id)?;
    let approval_found = approval.is_some();
    let approval_subject_id = approval
        .as_ref()
        .map(|record| record.subject_id.clone())
        .unwrap_or_else(|| "unresolved".to_string());
    let approval_command_id = approval
        .as_ref()
        .map(|record| record.command_id.clone())
        .unwrap_or_else(|| "unresolved".to_string());
    let approval_status = approval
        .as_ref()
        .map(|record| record.status.clone())
        .unwrap_or_else(|| "missing".to_string());
    let approval_matches_policy = approval.as_ref().map_or(false, |record| {
        record.subject_id == workspace_write_policy_id
            && record.command_id == expected_command_id
            && record.capability_tier == "gated"
    });
    let approval_resolved = approval.as_ref().map_or(false, |record| {
        record.status == "approved_recorded_execution_disabled" && !record.execution_enabled
    });
    let approval_evidence_recorded =
        write_policy_ready && approval_matches_policy && approval_resolved;
    let status = if !write_policy_found {
        "blocked_missing_workspace_write_policy"
    } else if !write_policy_ready {
        "blocked_workspace_write_policy_not_ready"
    } else if !approval_found {
        "blocked_missing_approval"
    } else if !approval_matches_policy {
        "blocked_approval_policy_mismatch"
    } else if !approval_resolved {
        "blocked_approval_not_resolved"
    } else if normalized_action == "edit" {
        "write_buffer_approval_recorded_mutation_disabled"
    } else {
        "save_approval_recorded_write_disabled"
    }
    .to_string();

    let mut reasons = Vec::new();
    if !write_policy_found {
        reasons.push("workspace write approval requires an existing write policy record".to_string());
    } else if !write_policy_ready {
        reasons.push("write policy exists but is not a ready disabled approval checkpoint".to_string());
    } else if !approval_found {
        reasons.push("matching approval record is missing from the approval ledger".to_string());
    } else if !approval_matches_policy {
        reasons.push(format!(
            "approval must target subject {} with command {} and gated tier",
            workspace_write_policy_id, expected_command_id
        ));
    } else if !approval_resolved {
        reasons.push("approval exists but has not been resolved with the required confirmation phrase".to_string());
    } else if normalized_action == "edit" {
        reasons.push("write-buffer approval evidence recorded; buffer mutation remains disabled".to_string());
    } else {
        reasons.push("save approval evidence recorded; atomic file writes remain disabled".to_string());
    }

    let id = format!(
        "workspace-write-approval-{}-{}-{}-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug_limit(&normalized_action, 24),
        slug_limit(&workspace_write_policy_id, 40),
        slug_limit(&approval_id, 48),
        slug_limit(&status, 40)
    );
    let dir = workspace_write_approvals_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create workspace-write-approvals directory {}: {error}",
            dir.display()
        )
    })?;
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let record = WorkspaceWriteApprovalRecord {
        id: id.clone(),
        workspace_write_policy_id: workspace_write_policy_id.clone(),
        workspace_edit_preflight_id,
        workspace_editor_tab_id,
        workspace_file_preview_id,
        workspace_tree_metadata_id,
        workspace_path,
        relative_path,
        tab_title,
        normalized_action: normalized_action.clone(),
        approval_id: approval_id.clone(),
        approval_subject_id,
        approval_command_id,
        approval_status,
        approval_tier: policy_approval_tier,
        status: status.clone(),
        write_policy_found,
        write_policy_ready,
        approval_found,
        approval_matches_policy,
        approval_resolved,
        approval_evidence_recorded,
        approval_required: true,
        approval_record_required: true,
        approval_record_found: approval_found,
        requires_diff_preview,
        requires_clean_base,
        requires_backup_snapshot,
        requires_atomic_write,
        requires_user_confirmed_path,
        edit_enabled: false,
        writable_buffer_enabled: false,
        buffer_mutation_enabled: false,
        dirty_transition_enabled: false,
        save_enabled: false,
        save_as_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Use this approval evidence only as a prerequisite for future writable buffer and atomic save commands; writes remain disabled here.".to_string(),
    };

    let json = serde_json::to_string_pretty(&record)
        .map_err(|error| format!("failed to serialize workspace write approval: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write workspace write approval {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "workspace_write_approval_stub_created",
            "id": id,
            "workspace_write_policy_id": workspace_write_policy_id,
            "approval_id": approval_id,
            "status": record.status,
            "approval_evidence_recorded": record.approval_evidence_recorded,
            "approval_found": record.approval_found,
            "approval_matches_policy": record.approval_matches_policy,
            "approval_resolved": record.approval_resolved,
            "edit_enabled": false,
            "writable_buffer_enabled": false,
            "save_enabled": false,
            "file_write_enabled": false,
            "patch_apply_enabled": false,
            "terminal_enabled": false,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(WorkspaceWriteApprovalResult {
        accepted: false,
        approval_evidence_recorded: record.approval_evidence_recorded,
        write_policy_found: record.write_policy_found,
        write_policy_ready: record.write_policy_ready,
        approval_found: record.approval_found,
        approval_matches_policy: record.approval_matches_policy,
        approval_resolved: record.approval_resolved,
        edit_enabled: false,
        writable_buffer_enabled: false,
        save_enabled: false,
        file_write_enabled: false,
        patch_apply_enabled: false,
        terminal_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        record,
    })
}

