#[tauri::command]
pub fn list_workspace_editable_text_model_storage_preflights(
) -> Result<Vec<WorkspaceEditableTextModelStoragePreflightRecord>, String> {
    let dir = workspace_editable_text_model_storage_preflights_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read workspace-editable-text-model-storage-preflights directory {}: {error}",
            dir.display()
        )
    })? {
        let entry = entry.map_err(|error| {
            format!("failed to read workspace editable text model storage preflight entry: {error}")
        })?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) =
            serde_json::from_str::<WorkspaceEditableTextModelStoragePreflightRecord>(&content)
        {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

