#[tauri::command]
pub fn list_workspace_editable_text_model_text_snapshots(
) -> Result<Vec<WorkspaceEditableTextModelTextSnapshotRecord>, String> {
    let dir = workspace_editable_text_model_text_snapshots_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read workspace-editable-text-model-text-snapshots directory {}: {error}",
            dir.display()
        )
    })? {
        let entry = entry.map_err(|error| {
            format!("failed to read workspace editable text model text snapshot entry: {error}")
        })?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) =
            serde_json::from_str::<WorkspaceEditableTextModelTextSnapshotRecord>(&content)
        {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

#[tauri::command]
pub fn prepare_runner_adapter_stub(
    request: RunnerAdapterPrepareRequest,
) -> Result<RunnerAdapterPrepareResult, String> {
    let timestamp = now_ms()?;
    let id = format!(
        "runner-adapter-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug(&request.workspace_lease_id)
    );
    let dir = runner_adapters_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create runner-adapters directory {}: {error}",
            dir.display()
        )
    })?;

    let task_run = read_task_run_record(&request.task_run_id)?;
    let runner = read_runner_invocation_record(&request.runner_invocation_id)?;
    let joint_plan = read_joint_agent_plan_record(&request.joint_plan_id)?;
    let lease = read_workspace_lease_record(&request.workspace_lease_id)?;
    let event_preview = agent_event_log_preview(request.task_run_id.clone())?;
    let task_run_found = task_run.is_some();
    let runner_invocation_found = runner.is_some();
    let joint_plan_found = joint_plan.is_some();
    let workspace_lease_found = lease.is_some();
    let event_log_found = event_preview.found;
    let lease_conflict_count = lease
        .as_ref()
        .map(|record| record.conflicting_lease_ids.len())
        .unwrap_or(0);
    let mut reasons = Vec::new();

    if !task_run_found {
        reasons.push("task run record missing".to_string());
    }
    if !runner_invocation_found {
        reasons.push("runner invocation record missing".to_string());
    }
    if !joint_plan_found {
        reasons.push("joint Codex/Hermes plan record missing".to_string());
    }
    if !workspace_lease_found {
        reasons.push("workspace lease record missing".to_string());
    }
    if !event_log_found {
        reasons.push("typed agent event log missing".to_string());
    }
    if let Some(runner) = runner.as_ref() {
        if runner.task_run_id != request.task_run_id {
            reasons.push("runner invocation is not linked to this task run".to_string());
        }
        if runner.status != "ready_but_execution_disabled" {
            reasons.push(format!("runner invocation status is {}", runner.status));
        }
    }
    if let Some(joint_plan) = joint_plan.as_ref() {
        if joint_plan.task_run_id != request.task_run_id {
            reasons.push("joint plan is not linked to this task run".to_string());
        }
    }
    if let Some(lease) = lease.as_ref() {
        if lease.task_run_id != request.task_run_id {
            reasons.push("workspace lease is not linked to this task run".to_string());
        }
        if !lease.conflicting_lease_ids.is_empty() {
            reasons.push(format!(
                "workspace lease has {} conflict(s)",
                lease.conflicting_lease_ids.len()
            ));
        }
        if lease.writes_allowed || lease.execution_enabled {
            reasons.push("workspace lease unexpectedly reports enabled writes or execution".to_string());
        }
    }

    let status = if !task_run_found {
        "blocked_missing_task_run"
    } else if !runner_invocation_found {
        "blocked_missing_runner_invocation"
    } else if runner.as_ref().map(|record| record.task_run_id.as_str())
        != Some(request.task_run_id.as_str())
    {
        "blocked_runner_task_mismatch"
    } else if runner.as_ref().map(|record| record.status.as_str())
        != Some("ready_but_execution_disabled")
    {
        "blocked_runner_not_ready"
    } else if !joint_plan_found {
        "blocked_missing_joint_plan"
    } else if joint_plan
        .as_ref()
        .map(|record| record.task_run_id.as_str())
        != Some(request.task_run_id.as_str())
    {
        "blocked_joint_plan_task_mismatch"
    } else if !workspace_lease_found {
        "blocked_missing_workspace_lease"
    } else if lease.as_ref().map(|record| record.task_run_id.as_str())
        != Some(request.task_run_id.as_str())
    {
        "blocked_workspace_lease_task_mismatch"
    } else if lease_conflict_count > 0 {
        "blocked_workspace_lease_conflict"
    } else if !event_log_found {
        "blocked_missing_event_log"
    } else {
        "ready_read_only_execution_disabled"
    }
    .to_string();

    if status == "ready_read_only_execution_disabled" {
        reasons.push("all adapter prerequisites are present; process spawning remains disabled".to_string());
    }

    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let adapter = RunnerAdapterRecord {
        id: id.clone(),
        task_run_id: request.task_run_id,
        runner_invocation_id: request.runner_invocation_id,
        joint_plan_id: request.joint_plan_id,
        workspace_lease_id: request.workspace_lease_id,
        status: status.clone(),
        task_run_found,
        runner_invocation_found,
        joint_plan_found,
        workspace_lease_found,
        event_log_found,
        event_count: event_preview.line_count,
        lease_conflict_count,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Only connect a real read-only process adapter after this readiness record is mandatory and logged for every runner path.".to_string(),
    };

    let json = serde_json::to_string_pretty(&adapter)
        .map_err(|error| format!("failed to serialize runner adapter record: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write runner adapter record {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "runner_adapter_stub_prepared",
            "id": id,
            "task_run_id": adapter.task_run_id,
            "status": adapter.status,
            "event_count": adapter.event_count,
            "lease_conflict_count": adapter.lease_conflict_count,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(RunnerAdapterPrepareResult {
        accepted: false,
        status,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        adapter,
        event_preview,
    })
}

#[tauri::command]
pub fn list_runner_adapters() -> Result<Vec<RunnerAdapterRecord>, String> {
    let dir = runner_adapters_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir)
        .map_err(|error| format!("failed to read runner-adapters directory {}: {error}", dir.display()))?
    {
        let entry = entry.map_err(|error| format!("failed to read runner adapter entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<RunnerAdapterRecord>(&content) {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

fn argv_for_runtime(runtime: &str, task_run_id: &str) -> Option<Vec<String>> {
    match runtime {
        "codex" => Some(vec![
            "codex".to_string(),
            "review".to_string(),
            "--uncommitted".to_string(),
        ]),
        "hermes" => Some(vec![
            "hermes".to_string(),
            "chat".to_string(),
            "-Q".to_string(),
            "--source".to_string(),
            "tool".to_string(),
            "-t".to_string(),
            "terminal,file,search,skills".to_string(),
            format!("Review task-run {task_run_id} as the Hermes companion lane. Return findings only; do not write files."),
        ]),
        _ => None,
    }
}

#[tauri::command]
pub fn build_process_command_plan_stub(
    request: ProcessCommandPlanRequest,
) -> Result<ProcessCommandPlanResult, String> {
    let timestamp = now_ms()?;
    let runtime = request.runtime.to_ascii_lowercase();
    let id = format!(
        "process-command-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug(&runtime)
    );
    let dir = process_command_plans_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create process-command-plans directory {}: {error}",
            dir.display()
        )
    })?;

    let task_run = read_task_run_record(&request.task_run_id)?;
    let adapter = read_runner_adapter_record(&request.runner_adapter_id)?;
    let task_run_found = task_run.is_some();
    let runner_adapter_found = adapter.is_some();
    let adapter_status = adapter
        .as_ref()
        .map(|record| record.status.clone())
        .unwrap_or_else(|| "missing".to_string());
    let argv = argv_for_runtime(&runtime, &request.task_run_id).unwrap_or_default();
    let mut reasons = Vec::new();

    if !task_run_found {
        reasons.push("task run record missing".to_string());
    }
    if !runner_adapter_found {
        reasons.push("runner adapter readiness record missing".to_string());
    }
    if argv.is_empty() {
        reasons.push(format!("runtime {runtime} is not supported by the command builder"));
    }
    if let Some(adapter) = adapter.as_ref() {
        if adapter.task_run_id != request.task_run_id {
            reasons.push("runner adapter is not linked to this task run".to_string());
        }
        if adapter.status != "ready_read_only_execution_disabled" {
            reasons.push(format!("runner adapter status is {}", adapter.status));
        }
        if adapter.process_spawn_enabled || adapter.writes_allowed || adapter.execution_enabled {
            reasons.push("runner adapter unexpectedly reports enabled process, writes, or execution".to_string());
        }
    }

    let status = if !task_run_found {
        "blocked_missing_task_run"
    } else if !runner_adapter_found {
        "blocked_missing_runner_adapter"
    } else if adapter.as_ref().map(|record| record.task_run_id.as_str())
        != Some(request.task_run_id.as_str())
    {
        "blocked_adapter_task_mismatch"
    } else if adapter.as_ref().map(|record| record.status.as_str())
        != Some("ready_read_only_execution_disabled")
    {
        "blocked_adapter_not_ready"
    } else if argv.is_empty() {
        "blocked_unknown_runtime"
    } else {
        "planned_process_spawn_disabled"
    }
    .to_string();

    if status == "planned_process_spawn_disabled" {
        reasons.push("argv and stream destinations are planned; process spawning remains disabled".to_string());
    }

    let cwd = task_run
        .as_ref()
        .map(|record| record.repo.clone())
        .unwrap_or_default();
    let event_log_path = agent_event_log_path(&request.task_run_id)?.display().to_string();
    let stream_stdout_path = dir
        .join(format!("{id}.stdout.jsonl"))
        .display()
        .to_string();
    let stream_stderr_path = dir
        .join(format!("{id}.stderr.jsonl"))
        .display()
        .to_string();
    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let plan = ProcessCommandPlanRecord {
        id: id.clone(),
        task_run_id: request.task_run_id,
        runner_adapter_id: request.runner_adapter_id,
        runtime,
        cwd,
        argv,
        stream_stdout_path,
        stream_stderr_path,
        event_log_path,
        status: status.clone(),
        adapter_status,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Connect a real read-only process runner only after command plans, streams, and adapter readiness are mandatory for every launch path.".to_string(),
    };

    let json = serde_json::to_string_pretty(&plan)
        .map_err(|error| format!("failed to serialize process command plan: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write process command plan {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "process_command_plan_stub_built",
            "id": id,
            "task_run_id": plan.task_run_id,
            "runner_adapter_id": plan.runner_adapter_id,
            "runtime": plan.runtime,
            "status": plan.status,
            "argv": plan.argv,
            "stream_stdout_path": plan.stream_stdout_path,
            "stream_stderr_path": plan.stream_stderr_path,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(ProcessCommandPlanResult {
        accepted: false,
        task_run_found,
        runner_adapter_found,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        plan,
    })
}

#[tauri::command]
pub fn list_process_command_plans() -> Result<Vec<ProcessCommandPlanRecord>, String> {
    let dir = process_command_plans_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir)
        .map_err(|error| format!("failed to read process-command-plans directory {}: {error}", dir.display()))?
    {
        let entry = entry.map_err(|error| format!("failed to read process command plan entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<ProcessCommandPlanRecord>(&content) {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

fn stream_path_is_owned(path: &PathBuf, dir: &PathBuf, suffix: &str) -> bool {
    path.parent() == Some(dir.as_path())
        && path
            .file_name()
            .and_then(|value| value.to_str())
            .map(|name| name.ends_with(suffix))
            .unwrap_or(false)
}

#[tauri::command]
pub fn initialize_process_streams_stub(
    request: ProcessStreamInitRequest,
) -> Result<ProcessStreamInitResult, String> {
    let timestamp = now_ms()?;
    let id = format!("process-stream-{}-{}", timestamp, std::process::id());
    let init_dir = process_stream_inits_dir()?;
    fs::create_dir_all(&init_dir).map_err(|error| {
        format!(
            "failed to create process-stream-inits directory {}: {error}",
            init_dir.display()
        )
    })?;
    let plan_dir = process_command_plans_dir()?;
    fs::create_dir_all(&plan_dir).map_err(|error| {
        format!(
            "failed to create process-command-plans directory {}: {error}",
            plan_dir.display()
        )
    })?;

    let plan = read_process_command_plan_record(&request.process_command_plan_id)?;
    let process_command_plan_found = plan.is_some();
    let mut reasons = Vec::new();
    let mut stdout_created = false;
    let mut stderr_created = false;
    let mut stdout_size_bytes = 0;
    let mut stderr_size_bytes = 0;

    if !process_command_plan_found {
        reasons.push("process command plan record missing".to_string());
    }

    let (task_run_id, runtime, stdout_path, stderr_path, plan_status) = match plan.as_ref() {
        Some(plan) => (
            plan.task_run_id.clone(),
            plan.runtime.clone(),
            PathBuf::from(&plan.stream_stdout_path),
            PathBuf::from(&plan.stream_stderr_path),
            plan.status.clone(),
        ),
        None => (
            String::new(),
            String::new(),
            PathBuf::new(),
            PathBuf::new(),
            "missing".to_string(),
        ),
    };

    if plan_status != "planned_process_spawn_disabled" && process_command_plan_found {
        reasons.push(format!("process command plan status is {plan_status}"));
    }

    let stdout_path_owned = process_command_plan_found
        && stream_path_is_owned(&stdout_path, &plan_dir, ".stdout.jsonl");
    let stderr_path_owned = process_command_plan_found
        && stream_path_is_owned(&stderr_path, &plan_dir, ".stderr.jsonl");
    if process_command_plan_found && (!stdout_path_owned || !stderr_path_owned) {
        reasons.push("stream path is not owned by the scaffold process-command-plans directory".to_string());
    }

    let status = if !process_command_plan_found {
        "blocked_missing_process_command_plan"
    } else if plan_status != "planned_process_spawn_disabled" {
        "blocked_process_command_plan_not_ready"
    } else if !stdout_path_owned || !stderr_path_owned {
        "blocked_unsafe_stream_path"
    } else {
        "streams_initialized_execution_disabled"
    }
    .to_string();

    if status == "streams_initialized_execution_disabled" {
        OpenOptions::new()
            .create(true)
            .write(true)
            .truncate(true)
            .open(&stdout_path)
            .map_err(|error| {
                format!(
                    "failed to initialize stdout stream {}: {error}",
                    stdout_path.display()
                )
            })?;
        OpenOptions::new()
            .create(true)
            .write(true)
            .truncate(true)
            .open(&stderr_path)
            .map_err(|error| {
                format!(
                    "failed to initialize stderr stream {}: {error}",
                    stderr_path.display()
                )
            })?;
        stdout_created = stdout_path.exists();
        stderr_created = stderr_path.exists();
        stdout_size_bytes = fs::metadata(&stdout_path).map(|metadata| metadata.len()).unwrap_or(0);
        stderr_size_bytes = fs::metadata(&stderr_path).map(|metadata| metadata.len()).unwrap_or(0);
        reasons.push("stdout and stderr stream files were initialized empty; process spawning remains disabled".to_string());
    }

    let record_path = init_dir.join(format!("{id}.json"));
    let log_path = init_dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let stream = ProcessStreamInitRecord {
        id: id.clone(),
        process_command_plan_id: request.process_command_plan_id,
        task_run_id,
        runtime,
        stdout_path: stdout_path.display().to_string(),
        stderr_path: stderr_path.display().to_string(),
        stdout_created,
        stderr_created,
        stdout_size_bytes,
        stderr_size_bytes,
        status: status.clone(),
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Only connect stdout/stderr writers after stream files are initialized through this evidence path and a read-only runner is approved.".to_string(),
    };

    let json = serde_json::to_string_pretty(&stream)
        .map_err(|error| format!("failed to serialize process stream initialization: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write process stream initialization {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "process_streams_initialized_stub",
            "id": id,
            "process_command_plan_id": stream.process_command_plan_id,
            "task_run_id": stream.task_run_id,
            "runtime": stream.runtime,
            "status": stream.status,
            "stdout_created": stream.stdout_created,
            "stderr_created": stream.stderr_created,
            "stdout_size_bytes": stream.stdout_size_bytes,
            "stderr_size_bytes": stream.stderr_size_bytes,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(ProcessStreamInitResult {
        accepted: false,
        process_command_plan_found,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        stream,
    })
}

#[tauri::command]
