fn lifecycle_step(id: &str, status: &str, evidence: String) -> ProcessLifecycleStep {
    ProcessLifecycleStep {
        id: id.to_string(),
        status: status.to_string(),
        evidence,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
    }
}

#[tauri::command]
pub fn create_process_lifecycle_stub(
    request: ProcessLifecycleRequest,
) -> Result<ProcessLifecycleResult, String> {
    let timestamp = now_ms()?;
    let id = format!(
        "process-lifecycle-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug(&request.process_stream_init_id)
    );
    let dir = process_lifecycles_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create process-lifecycles directory {}: {error}",
            dir.display()
        )
    })?;

    let plan = read_process_command_plan_record(&request.process_command_plan_id)?;
    let stream_init = read_process_stream_init_record(&request.process_stream_init_id)?;
    let process_command_plan_found = plan.is_some();
    let process_stream_init_found = stream_init.is_some();
    let mut reasons = Vec::new();
    let mut steps = Vec::new();

    if !process_command_plan_found {
        reasons.push("process command plan record missing".to_string());
    }
    if !process_stream_init_found {
        reasons.push("process stream initialization record missing".to_string());
    }

    let (task_run_id, runtime, plan_status) = match plan.as_ref() {
        Some(plan) => (
            plan.task_run_id.clone(),
            plan.runtime.clone(),
            plan.status.clone(),
        ),
        None => (String::new(), String::new(), "missing".to_string()),
    };
    let stdout_ready = stream_init
        .as_ref()
        .map(|record| {
            record.stdout_created
                && PathBuf::from(&record.stdout_path).exists()
                && fs::metadata(&record.stdout_path)
                    .map(|metadata| metadata.len() == record.stdout_size_bytes)
                    .unwrap_or(false)
        })
        .unwrap_or(false);
    let stderr_ready = stream_init
        .as_ref()
        .map(|record| {
            record.stderr_created
                && PathBuf::from(&record.stderr_path).exists()
                && fs::metadata(&record.stderr_path)
                    .map(|metadata| metadata.len() == record.stderr_size_bytes)
                    .unwrap_or(false)
        })
        .unwrap_or(false);

    if let Some(plan) = plan.as_ref() {
        if plan.status != "planned_process_spawn_disabled" {
            reasons.push(format!("process command plan status is {}", plan.status));
        }
        if plan.process_spawn_enabled || plan.writes_allowed || plan.execution_enabled {
            reasons.push("process command plan unexpectedly reports enabled process, writes, or execution".to_string());
        }
    }
    if let Some(stream_init) = stream_init.as_ref() {
        if stream_init.process_command_plan_id != request.process_command_plan_id {
            reasons.push("stream initialization is not linked to this process command plan".to_string());
        }
        if stream_init.status != "streams_initialized_execution_disabled" {
            reasons.push(format!("stream initialization status is {}", stream_init.status));
        }
        if stream_init.process_spawn_enabled || stream_init.writes_allowed || stream_init.execution_enabled {
            reasons.push("stream initialization unexpectedly reports enabled process, writes, or execution".to_string());
        }
        if !stdout_ready {
            reasons.push("stdout stream is not ready".to_string());
        }
        if !stderr_ready {
            reasons.push("stderr stream is not ready".to_string());
        }
    }

    if process_command_plan_found {
        steps.push(lifecycle_step(
            "planned",
            "complete",
            format!("process command plan {plan_status}"),
        ));
    }
    if process_stream_init_found && stdout_ready && stderr_ready {
        steps.push(lifecycle_step(
            "stream-ready",
            "complete",
            "stdout/stderr stream files exist as initialized artifacts".to_string(),
        ));
    }

    let status = if !process_command_plan_found {
        "blocked_missing_process_command_plan"
    } else if plan_status != "planned_process_spawn_disabled" {
        "blocked_process_command_plan_not_ready"
    } else if !process_stream_init_found {
        "blocked_missing_process_stream_init"
    } else if stream_init
        .as_ref()
        .map(|record| record.process_command_plan_id.as_str())
        != Some(request.process_command_plan_id.as_str())
    {
        "blocked_stream_plan_mismatch"
    } else if stream_init.as_ref().map(|record| record.status.as_str())
        != Some("streams_initialized_execution_disabled")
    {
        "blocked_stream_init_not_ready"
    } else if !stdout_ready || !stderr_ready {
        "blocked_stream_files_missing"
    } else {
        "spawn_blocked_execution_disabled"
    }
    .to_string();

    if status == "spawn_blocked_execution_disabled" {
        steps.push(lifecycle_step(
            "spawn-blocked",
            "blocked",
            "process spawn is intentionally disabled by scaffold policy".to_string(),
        ));
        reasons.push("lifecycle reached stream-ready and stopped before process spawn".to_string());
    }

    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let lifecycle = ProcessLifecycleRecord {
        id: id.clone(),
        process_command_plan_id: request.process_command_plan_id,
        process_stream_init_id: request.process_stream_init_id,
        task_run_id,
        runtime,
        status: status.clone(),
        steps,
        process_command_plan_found,
        process_stream_init_found,
        stdout_ready,
        stderr_ready,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "A future read-only runner may only attempt spawn after this lifecycle still ends in spawn-blocked and the user explicitly enables a narrower execution phase.".to_string(),
    };

    let json = serde_json::to_string_pretty(&lifecycle)
        .map_err(|error| format!("failed to serialize process lifecycle: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write process lifecycle {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "process_lifecycle_stub_created",
            "id": id,
            "process_command_plan_id": lifecycle.process_command_plan_id,
            "process_stream_init_id": lifecycle.process_stream_init_id,
            "task_run_id": lifecycle.task_run_id,
            "runtime": lifecycle.runtime,
            "status": lifecycle.status,
            "stdout_ready": lifecycle.stdout_ready,
            "stderr_ready": lifecycle.stderr_ready,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(ProcessLifecycleResult {
        accepted: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        lifecycle,
    })
}

