#[tauri::command]
pub fn create_process_control_policy_stub(
    request: ProcessControlPolicyRequest,
) -> Result<ProcessControlPolicyResult, String> {
    let timestamp = now_ms()?;
    let requested_action = request.requested_action.to_ascii_lowercase();
    let id = format!(
        "process-control-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug(&requested_action)
    );
    let dir = process_control_policies_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create process-control-policies directory {}: {error}",
            dir.display()
        )
    })?;

    let lifecycle = read_process_lifecycle_record(&request.process_lifecycle_id)?;
    let process_lifecycle_found = lifecycle.is_some();
    let mut reasons = Vec::new();
    if !process_lifecycle_found {
        reasons.push("process lifecycle record missing".to_string());
    }
    if requested_action != "cancel" && requested_action != "retry" {
        reasons.push(format!("requested action {requested_action} is not supported"));
    }

    let (task_run_id, runtime, lifecycle_status) = match lifecycle.as_ref() {
        Some(record) => (
            record.task_run_id.clone(),
            record.runtime.clone(),
            record.status.clone(),
        ),
        None => (String::new(), String::new(), "missing".to_string()),
    };
    if let Some(lifecycle) = lifecycle.as_ref() {
        if lifecycle.process_spawn_enabled || lifecycle.writes_allowed || lifecycle.execution_enabled {
            reasons.push("process lifecycle unexpectedly reports enabled process, writes, or execution".to_string());
        }
        if lifecycle.status != "spawn_blocked_execution_disabled" {
            reasons.push(format!("process lifecycle status is {}", lifecycle.status));
        }
    }

    let status = if !process_lifecycle_found {
        "blocked_missing_process_lifecycle"
    } else if requested_action != "cancel" && requested_action != "retry" {
        "blocked_unsupported_control_action"
    } else if lifecycle_status != "spawn_blocked_execution_disabled" {
        "blocked_lifecycle_not_spawn_blocked"
    } else if requested_action == "cancel" {
        "cancel_recorded_signal_disabled"
    } else {
        "retry_recorded_spawn_disabled"
    }
    .to_string();

    if status == "cancel_recorded_signal_disabled" {
        reasons.push("cancel was recorded, but no process exists and signal delivery is disabled".to_string());
    } else if status == "retry_recorded_spawn_disabled" {
        reasons.push("retry was recorded, but retry spawning is disabled".to_string());
    }

    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let policy = ProcessControlPolicyRecord {
        id: id.clone(),
        process_lifecycle_id: request.process_lifecycle_id,
        task_run_id,
        runtime,
        requested_action,
        lifecycle_status,
        status: status.clone(),
        signal_enabled: false,
        retry_spawn_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Only wire real cancel or retry behavior after a process supervisor exists and this policy remains explicit per lifecycle.".to_string(),
    };

    let json = serde_json::to_string_pretty(&policy)
        .map_err(|error| format!("failed to serialize process control policy: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write process control policy {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "process_control_policy_stub_created",
            "id": id,
            "process_lifecycle_id": policy.process_lifecycle_id,
            "task_run_id": policy.task_run_id,
            "runtime": policy.runtime,
            "requested_action": policy.requested_action,
            "status": policy.status,
            "signal_enabled": false,
            "retry_spawn_enabled": false,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(ProcessControlPolicyResult {
        accepted: false,
        process_lifecycle_found,
        signal_enabled: false,
        retry_spawn_enabled: false,
        process_spawn_enabled: false,
        execution_enabled: false,
        policy,
    })
}

