#[tauri::command]
pub fn create_process_supervisor_preflight_stub(
    request: ProcessSupervisorPreflightRequest,
) -> Result<ProcessSupervisorPreflightResult, String> {
    let timestamp = now_ms()?;
    let id = format!(
        "process-supervisor-preflight-{}-{}",
        timestamp,
        std::process::id()
    );
    let dir = process_supervisor_preflights_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create process-supervisor-preflights directory {}: {error}",
            dir.display()
        )
    })?;

    let lifecycle = read_process_lifecycle_record(&request.process_lifecycle_id)?;
    let process_lifecycle_found = lifecycle.is_some();
    let mut reasons = Vec::new();
    if !process_lifecycle_found {
        reasons.push("process lifecycle record missing".to_string());
    }

    let (
        process_command_plan_id,
        process_stream_init_id,
        task_run_id,
        runtime,
        lifecycle_status,
        lifecycle_stdout_ready,
        lifecycle_stderr_ready,
    ) = match lifecycle.as_ref() {
        Some(record) => (
            record.process_command_plan_id.clone(),
            record.process_stream_init_id.clone(),
            record.task_run_id.clone(),
            record.runtime.clone(),
            record.status.clone(),
            record.stdout_ready,
            record.stderr_ready,
        ),
        None => (
            String::new(),
            String::new(),
            String::new(),
            String::new(),
            "missing".to_string(),
            false,
            false,
        ),
    };

    let mut process_command_plan_found = false;
    let mut process_command_plan_ready = false;
    let mut process_stream_init_found = false;
    let mut process_stream_init_ready = false;
    let mut stream_matches_plan = false;
    let mut stdout_file_present = false;
    let mut stderr_file_present = false;

    if let Some(record) = lifecycle.as_ref() {
        if record.process_spawn_enabled || record.writes_allowed || record.execution_enabled {
            reasons.push(
                "process lifecycle unexpectedly reports enabled process, writes, or execution"
                    .to_string(),
            );
        }
        if record.status != "spawn_blocked_execution_disabled" {
            reasons.push(format!("process lifecycle status is {}", record.status));
        }
        if !record.stdout_ready || !record.stderr_ready {
            reasons.push("process lifecycle stream readiness is incomplete".to_string());
        }

        let command_plan = read_process_command_plan_record(&record.process_command_plan_id)?;
        process_command_plan_found = command_plan.is_some();
        match command_plan.as_ref() {
            Some(plan) => {
                process_command_plan_ready = plan.status == "planned_process_spawn_disabled"
                    && !plan.process_spawn_enabled
                    && !plan.writes_allowed
                    && !plan.execution_enabled;
                if !process_command_plan_ready {
                    reasons.push(
                        "process command plan is not in a disabled planned state".to_string(),
                    );
                }
            }
            None => reasons.push("process command plan record missing".to_string()),
        }

        let stream_init = read_process_stream_init_record(&record.process_stream_init_id)?;
        process_stream_init_found = stream_init.is_some();
        match stream_init.as_ref() {
            Some(stream) => {
                stream_matches_plan = stream.process_command_plan_id == record.process_command_plan_id;
                stdout_file_present = PathBuf::from(&stream.stdout_path).exists();
                stderr_file_present = PathBuf::from(&stream.stderr_path).exists();
                process_stream_init_ready = stream.status == "streams_initialized_execution_disabled"
                    && stream_matches_plan
                    && stream.stdout_created
                    && stream.stderr_created
                    && stdout_file_present
                    && stderr_file_present
                    && !stream.process_spawn_enabled
                    && !stream.writes_allowed
                    && !stream.execution_enabled;
                if !stream_matches_plan {
                    reasons.push(
                        "process stream initialization does not belong to lifecycle plan"
                            .to_string(),
                    );
                }
                if !stdout_file_present || !stderr_file_present {
                    reasons.push("process stream files are not present".to_string());
                }
                if !process_stream_init_ready {
                    reasons.push(
                        "process stream initialization is not in a disabled ready state"
                            .to_string(),
                    );
                }
            }
            None => reasons.push("process stream initialization record missing".to_string()),
        }
    }

    let control_policies = if process_lifecycle_found {
        read_process_control_policy_records_for_lifecycle(&request.process_lifecycle_id)?
    } else {
        Vec::new()
    };
    let control_policy_count = control_policies.len();
    let cancel_policy_recorded = control_policies.iter().any(|policy| {
        policy.requested_action == "cancel" && policy.status == "cancel_recorded_signal_disabled"
    });
    let retry_policy_recorded = control_policies.iter().any(|policy| {
        policy.requested_action == "retry" && policy.status == "retry_recorded_spawn_disabled"
    });
    let control_policies_disabled = control_policies.iter().all(|policy| {
        !policy.signal_enabled
            && !policy.retry_spawn_enabled
            && !policy.process_spawn_enabled
            && !policy.writes_allowed
            && !policy.execution_enabled
    });

    if control_policy_count == 0 {
        reasons.push("no process control policy records found for lifecycle".to_string());
    }
    if !control_policies_disabled {
        reasons.push("a process control policy unexpectedly enables control or execution".to_string());
    }
    if !cancel_policy_recorded {
        reasons.push("cancel policy evidence has not been recorded".to_string());
    }
    if !retry_policy_recorded {
        reasons.push("retry policy evidence has not been recorded".to_string());
    }

    let stdout_ready = lifecycle_stdout_ready && stdout_file_present;
    let stderr_ready = lifecycle_stderr_ready && stderr_file_present;
    let preflight_passed = process_lifecycle_found
        && lifecycle_status == "spawn_blocked_execution_disabled"
        && process_command_plan_found
        && process_command_plan_ready
        && process_stream_init_found
        && process_stream_init_ready
        && stdout_ready
        && stderr_ready
        && control_policy_count > 0
        && control_policies_disabled;

    let status = if !process_lifecycle_found {
        "blocked_missing_process_lifecycle"
    } else if lifecycle_status != "spawn_blocked_execution_disabled" {
        "blocked_lifecycle_not_spawn_blocked"
    } else if !process_command_plan_found || !process_stream_init_found {
        "blocked_missing_supervisor_evidence"
    } else if !stdout_ready || !stderr_ready || !stream_matches_plan {
        "blocked_streams_not_ready"
    } else if control_policy_count == 0 {
        "blocked_missing_control_policy"
    } else if !control_policies_disabled {
        "blocked_control_policy_execution_enabled"
    } else {
        "supervisor_preflight_ready_execution_disabled"
    }
    .to_string();

    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let preflight = ProcessSupervisorPreflightRecord {
        id: id.clone(),
        process_lifecycle_id: request.process_lifecycle_id,
        process_command_plan_id,
        process_stream_init_id,
        task_run_id,
        runtime,
        lifecycle_status,
        status: status.clone(),
        process_lifecycle_found,
        process_command_plan_found,
        process_stream_init_found,
        control_policy_count,
        cancel_policy_recorded,
        retry_policy_recorded,
        stdout_ready,
        stderr_ready,
        stdout_file_present,
        stderr_file_present,
        supervisor_enabled: false,
        signal_enabled: false,
        retry_spawn_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Only enable a real supervisor after this preflight passes, a narrower runtime gate is added, and explicit user approval is attached to the process plan.".to_string(),
    };

    let json = serde_json::to_string_pretty(&preflight)
        .map_err(|error| format!("failed to serialize process supervisor preflight: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write process supervisor preflight {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "process_supervisor_preflight_stub_created",
            "id": id,
            "process_lifecycle_id": preflight.process_lifecycle_id,
            "process_command_plan_id": preflight.process_command_plan_id,
            "process_stream_init_id": preflight.process_stream_init_id,
            "task_run_id": preflight.task_run_id,
            "runtime": preflight.runtime,
            "status": preflight.status,
            "preflight_passed": preflight_passed,
            "control_policy_count": preflight.control_policy_count,
            "supervisor_enabled": false,
            "signal_enabled": false,
            "retry_spawn_enabled": false,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(ProcessSupervisorPreflightResult {
        accepted: false,
        preflight_passed,
        supervisor_enabled: false,
        signal_enabled: false,
        retry_spawn_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        preflight,
    })
}

