#[tauri::command]
pub fn create_process_supervisor_heartbeat_stub(
    request: ProcessSupervisorHeartbeatRequest,
) -> Result<ProcessSupervisorHeartbeatResult, String> {
    let timestamp = now_ms()?;
    let requested_state = request.requested_state.to_ascii_lowercase();
    let id = format!(
        "process-supervisor-heartbeat-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug(&requested_state)
    );
    let dir = process_supervisor_heartbeats_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create process-supervisor-heartbeats directory {}: {error}",
            dir.display()
        )
    })?;

    let preflight =
        read_process_supervisor_preflight_record(&request.process_supervisor_preflight_id)?;
    let process_supervisor_preflight_found = preflight.is_some();
    let mut reasons = Vec::new();
    if !process_supervisor_preflight_found {
        reasons.push("process supervisor preflight record missing".to_string());
    }
    if requested_state != "queued" && requested_state != "running" && requested_state != "exited" {
        reasons.push(format!(
            "requested supervisor state {requested_state} is not supported"
        ));
    }

    let (
        process_lifecycle_id,
        task_run_id,
        runtime,
        preflight_status,
        preflight_passed,
    ) = match preflight.as_ref() {
        Some(record) => (
            record.process_lifecycle_id.clone(),
            record.task_run_id.clone(),
            record.runtime.clone(),
            record.status.clone(),
            record.status == "supervisor_preflight_ready_execution_disabled"
                && !record.supervisor_enabled
                && !record.signal_enabled
                && !record.retry_spawn_enabled
                && !record.process_spawn_enabled
                && !record.writes_allowed
                && !record.execution_enabled,
        ),
        None => (
            String::new(),
            String::new(),
            String::new(),
            "missing".to_string(),
            false,
        ),
    };

    if let Some(record) = preflight.as_ref() {
        if record.status != "supervisor_preflight_ready_execution_disabled" {
            reasons.push(format!("process supervisor preflight status is {}", record.status));
        }
        if record.supervisor_enabled
            || record.signal_enabled
            || record.retry_spawn_enabled
            || record.process_spawn_enabled
            || record.writes_allowed
            || record.execution_enabled
        {
            reasons.push(
                "process supervisor preflight unexpectedly enables supervisor or execution"
                    .to_string(),
            );
        }
        if !record.stdout_ready || !record.stderr_ready {
            reasons.push("process supervisor preflight streams are not ready".to_string());
        }
        if record.control_policy_count == 0 {
            reasons.push("process supervisor preflight has no control policy evidence".to_string());
        }
    }

    let existing_heartbeats = if process_supervisor_preflight_found {
        read_process_supervisor_heartbeat_records_for_preflight(
            &request.process_supervisor_preflight_id,
        )?
    } else {
        Vec::new()
    };
    let heartbeat_sequence = existing_heartbeats.len() + 1;
    let supported_state =
        requested_state == "queued" || requested_state == "running" || requested_state == "exited";
    let recorded = process_supervisor_preflight_found && preflight_passed && supported_state;
    let status = if !process_supervisor_preflight_found {
        "blocked_missing_supervisor_preflight"
    } else if !supported_state {
        "blocked_unsupported_supervisor_state"
    } else if !preflight_passed {
        "blocked_preflight_not_ready"
    } else if requested_state == "queued" {
        "queued_state_recorded_execution_disabled"
    } else if requested_state == "running" {
        "running_state_recorded_spawn_disabled"
    } else {
        "exited_state_recorded_no_process"
    }
    .to_string();

    if recorded && requested_state == "queued" {
        reasons.push("queued state recorded without starting a supervisor loop".to_string());
    } else if recorded && requested_state == "running" {
        reasons.push("running state recorded without PID attachment or process spawn".to_string());
    } else if recorded && requested_state == "exited" {
        reasons.push("exited state recorded for a process that was never started".to_string());
    }

    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let heartbeat = ProcessSupervisorHeartbeatRecord {
        id: id.clone(),
        process_supervisor_preflight_id: request.process_supervisor_preflight_id,
        process_lifecycle_id,
        task_run_id,
        runtime,
        requested_state: requested_state.clone(),
        supervisor_state: requested_state,
        status: status.clone(),
        process_supervisor_preflight_found,
        preflight_status,
        preflight_passed,
        heartbeat_sequence,
        pid_attached: false,
        pid: None,
        supervisor_enabled: false,
        monitor_loop_enabled: false,
        signal_enabled: false,
        retry_spawn_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Only replace recorded supervisor states with live monitoring after a real supervisor gate, PID model, and stream reader are implemented.".to_string(),
    };

    let json = serde_json::to_string_pretty(&heartbeat)
        .map_err(|error| format!("failed to serialize process supervisor heartbeat: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write process supervisor heartbeat {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "process_supervisor_heartbeat_stub_created",
            "id": id,
            "process_supervisor_preflight_id": heartbeat.process_supervisor_preflight_id,
            "process_lifecycle_id": heartbeat.process_lifecycle_id,
            "task_run_id": heartbeat.task_run_id,
            "runtime": heartbeat.runtime,
            "requested_state": heartbeat.requested_state,
            "status": heartbeat.status,
            "heartbeat_sequence": heartbeat.heartbeat_sequence,
            "recorded": recorded,
            "pid_attached": false,
            "supervisor_enabled": false,
            "monitor_loop_enabled": false,
            "signal_enabled": false,
            "retry_spawn_enabled": false,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(ProcessSupervisorHeartbeatResult {
        accepted: false,
        recorded,
        process_supervisor_preflight_found,
        supervisor_enabled: false,
        monitor_loop_enabled: false,
        pid_attached: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        heartbeat,
    })
}

#[tauri::command]
pub fn list_process_supervisor_heartbeats() -> Result<Vec<ProcessSupervisorHeartbeatRecord>, String>
{
    let dir = process_supervisor_heartbeats_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read process-supervisor-heartbeats directory {}: {error}",
            dir.display()
        )
    })? {
        let entry = entry.map_err(|error| {
            format!("failed to read process supervisor heartbeat entry: {error}")
        })?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<ProcessSupervisorHeartbeatRecord>(&content) {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

#[tauri::command]
pub fn create_process_supervisor_exit_summary_stub(
    request: ProcessSupervisorExitSummaryRequest,
) -> Result<ProcessSupervisorExitSummaryResult, String> {
    let timestamp = now_ms()?;
    let id = format!(
        "process-supervisor-exit-summary-{}-{}",
        timestamp,
        std::process::id()
    );
    let dir = process_supervisor_exit_summaries_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create process-supervisor-exit-summaries directory {}: {error}",
            dir.display()
        )
    })?;

    let heartbeat =
        read_process_supervisor_heartbeat_record(&request.process_supervisor_heartbeat_id)?;
    let process_supervisor_heartbeat_found = heartbeat.is_some();
    let mut reasons = Vec::new();
    if !process_supervisor_heartbeat_found {
        reasons.push("process supervisor heartbeat record missing".to_string());
    }

    let (
        process_supervisor_preflight_id,
        process_lifecycle_id,
        task_run_id,
        runtime,
        final_supervisor_state,
        final_heartbeat_status,
        heartbeat_log_path,
        heartbeat_created_at_ms,
        heartbeat_is_exited,
    ) = match heartbeat.as_ref() {
        Some(record) => (
            record.process_supervisor_preflight_id.clone(),
            record.process_lifecycle_id.clone(),
            record.task_run_id.clone(),
            record.runtime.clone(),
            record.supervisor_state.clone(),
            record.status.clone(),
            record.log_path.clone(),
            record.created_at_ms,
            record.supervisor_state == "exited" && record.status == "exited_state_recorded_no_process",
        ),
        None => (
            String::new(),
            String::new(),
            String::new(),
            String::new(),
            "missing".to_string(),
            "missing".to_string(),
            String::new(),
            timestamp,
            false,
        ),
    };

    if let Some(record) = heartbeat.as_ref() {
        if record.supervisor_state != "exited" || record.status != "exited_state_recorded_no_process"
        {
            reasons.push(format!(
                "supervisor heartbeat is {} / {}",
                record.supervisor_state, record.status
            ));
        }
        if record.pid_attached
            || record.pid.is_some()
            || record.supervisor_enabled
            || record.monitor_loop_enabled
            || record.signal_enabled
            || record.retry_spawn_enabled
            || record.process_spawn_enabled
            || record.writes_allowed
            || record.execution_enabled
        {
            reasons.push(
                "process supervisor heartbeat unexpectedly reports a live process or execution"
                    .to_string(),
            );
        }
    }

    let preflight = if process_supervisor_heartbeat_found {
        read_process_supervisor_preflight_record(&process_supervisor_preflight_id)?
    } else {
        None
    };
    let process_supervisor_preflight_found = preflight.is_some();
    let preflight_log_path = preflight
        .as_ref()
        .map(|record| record.log_path.clone())
        .unwrap_or_default();
    if process_supervisor_heartbeat_found && !process_supervisor_preflight_found {
        reasons.push("linked process supervisor preflight record missing".to_string());
    }
    if let Some(record) = preflight.as_ref() {
        if record.supervisor_enabled
            || record.signal_enabled
            || record.retry_spawn_enabled
            || record.process_spawn_enabled
            || record.writes_allowed
            || record.execution_enabled
        {
            reasons.push(
                "linked process supervisor preflight unexpectedly enables execution".to_string(),
            );
        }
    }

    let heartbeats = if process_supervisor_heartbeat_found {
        read_process_supervisor_heartbeat_records_for_preflight(&process_supervisor_preflight_id)?
    } else {
        Vec::new()
    };
    let heartbeat_count = heartbeats.len();
    let first_heartbeat_at_ms = heartbeats
        .first()
        .map(|record| record.created_at_ms)
        .unwrap_or(heartbeat_created_at_ms);
    let last_heartbeat_at_ms = heartbeats
        .last()
        .map(|record| record.created_at_ms)
        .unwrap_or(heartbeat_created_at_ms);
    let duration_ms = last_heartbeat_at_ms.saturating_sub(first_heartbeat_at_ms);
    let all_heartbeats_disabled = heartbeats.iter().all(|record| {
        !record.pid_attached
            && record.pid.is_none()
            && !record.supervisor_enabled
            && !record.monitor_loop_enabled
            && !record.signal_enabled
            && !record.retry_spawn_enabled
            && !record.process_spawn_enabled
            && !record.writes_allowed
            && !record.execution_enabled
    });
    if !all_heartbeats_disabled {
        reasons.push("a linked supervisor heartbeat unexpectedly enables execution".to_string());
    }

    let summarized = process_supervisor_heartbeat_found
        && process_supervisor_preflight_found
        && heartbeat_is_exited
        && all_heartbeats_disabled;
    let status = if !process_supervisor_heartbeat_found {
        "blocked_missing_supervisor_heartbeat"
    } else if !heartbeat_is_exited {
        "blocked_heartbeat_not_exited"
    } else if !process_supervisor_preflight_found {
        "blocked_missing_supervisor_preflight"
    } else if !all_heartbeats_disabled {
        "blocked_heartbeat_execution_enabled"
    } else {
        "exit_summary_recorded_no_process"
    }
    .to_string();

    if summarized {
        reasons.push("exit summary recorded without process start or exit code capture".to_string());
    }

    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let summary = ProcessSupervisorExitSummaryRecord {
        id: id.clone(),
        process_supervisor_heartbeat_id: request.process_supervisor_heartbeat_id,
        process_supervisor_preflight_id,
        process_lifecycle_id,
        task_run_id,
        runtime,
        final_supervisor_state,
        final_heartbeat_status,
        status: status.clone(),
        process_supervisor_heartbeat_found,
        process_supervisor_preflight_found,
        exited_heartbeat_found: heartbeat_is_exited,
        heartbeat_count,
        first_heartbeat_at_ms,
        last_heartbeat_at_ms,
        duration_ms,
        exit_code: None,
        exit_code_captured: false,
        process_started: false,
        pid_attached: false,
        pid: None,
        supervisor_enabled: false,
        monitor_loop_enabled: false,
        signal_enabled: false,
        retry_spawn_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        heartbeat_log_path,
        preflight_log_path,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Only replace this summary with real exit data after a process supervisor, PID attachment, stream reader, and exit-code capture path are implemented.".to_string(),
    };

    let json = serde_json::to_string_pretty(&summary)
        .map_err(|error| format!("failed to serialize process supervisor exit summary: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write process supervisor exit summary {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "process_supervisor_exit_summary_stub_created",
            "id": id,
            "process_supervisor_heartbeat_id": summary.process_supervisor_heartbeat_id,
            "process_supervisor_preflight_id": summary.process_supervisor_preflight_id,
            "process_lifecycle_id": summary.process_lifecycle_id,
            "task_run_id": summary.task_run_id,
            "runtime": summary.runtime,
            "status": summary.status,
            "summarized": summarized,
            "heartbeat_count": summary.heartbeat_count,
            "duration_ms": summary.duration_ms,
            "exit_code_captured": false,
            "process_started": false,
            "pid_attached": false,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(ProcessSupervisorExitSummaryResult {
        accepted: false,
        summarized,
        process_supervisor_heartbeat_found,
        exit_code_captured: false,
        process_started: false,
        pid_attached: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        summary,
    })
}

