#[tauri::command]
pub fn create_process_output_tail_summary_stub(
    request: ProcessOutputTailSummaryRequest,
) -> Result<ProcessOutputTailSummaryResult, String> {
    let timestamp = now_ms()?;
    let id = format!("process-output-tail-summary-{}-{}", timestamp, std::process::id());
    let dir = process_output_tail_summaries_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create process-output-tail-summaries directory {}: {error}",
            dir.display()
        )
    })?;

    let exit_summary =
        read_process_supervisor_exit_summary_record(&request.process_supervisor_exit_summary_id)?;
    let exit_summary_found = exit_summary.is_some();
    let mut reasons = Vec::new();
    if !exit_summary_found {
        reasons.push("process supervisor exit summary record missing".to_string());
    }

    let (
        process_supervisor_preflight_id,
        process_lifecycle_id,
        task_run_id,
        runtime,
        exit_summary_ready,
    ) = match exit_summary.as_ref() {
        Some(record) => (
            record.process_supervisor_preflight_id.clone(),
            record.process_lifecycle_id.clone(),
            record.task_run_id.clone(),
            record.runtime.clone(),
            record.status == "exit_summary_recorded_no_process"
                && !record.exit_code_captured
                && !record.process_started
                && !record.pid_attached
                && !record.process_spawn_enabled
                && !record.writes_allowed
                && !record.execution_enabled,
        ),
        None => (
            String::new(),
            String::new(),
            String::new(),
            String::new(),
            false,
        ),
    };

    if let Some(record) = exit_summary.as_ref() {
        if record.status != "exit_summary_recorded_no_process" {
            reasons.push(format!("process supervisor exit summary status is {}", record.status));
        }
        if record.exit_code_captured
            || record.process_started
            || record.pid_attached
            || record.pid.is_some()
            || record.process_spawn_enabled
            || record.writes_allowed
            || record.execution_enabled
        {
            reasons.push(
                "process supervisor exit summary unexpectedly reports live process evidence"
                    .to_string(),
            );
        }
    }

    let preflight = if exit_summary_found {
        read_process_supervisor_preflight_record(&process_supervisor_preflight_id)?
    } else {
        None
    };
    let preflight_found = preflight.is_some();
    if exit_summary_found && !preflight_found {
        reasons.push("linked process supervisor preflight record missing".to_string());
    }

    let lifecycle = if exit_summary_found {
        read_process_lifecycle_record(&process_lifecycle_id)?
    } else {
        None
    };
    let lifecycle_found = lifecycle.is_some();
    if exit_summary_found && !lifecycle_found {
        reasons.push("linked process lifecycle record missing".to_string());
    }

    let process_stream_init_id = preflight
        .as_ref()
        .map(|record| record.process_stream_init_id.clone())
        .unwrap_or_default();
    let stream_init = if preflight_found {
        read_process_stream_init_record(&process_stream_init_id)?
    } else {
        None
    };
    let stream_init_found = stream_init.is_some();
    if preflight_found && !stream_init_found {
        reasons.push("linked process stream initialization record missing".to_string());
    }

    let mut stdout_path = String::new();
    let mut stderr_path = String::new();
    let mut stdout_present = false;
    let mut stderr_present = false;
    let mut stdout_size_bytes = 0;
    let mut stderr_size_bytes = 0;
    let mut stream_init_ready = false;

    if let Some(record) = stream_init.as_ref() {
        stdout_path = record.stdout_path.clone();
        stderr_path = record.stderr_path.clone();
        stdout_present = PathBuf::from(&record.stdout_path).exists();
        stderr_present = PathBuf::from(&record.stderr_path).exists();
        stdout_size_bytes = if stdout_present {
            fs::metadata(&record.stdout_path)
                .map(|metadata| metadata.len())
                .unwrap_or(0)
        } else {
            0
        };
        stderr_size_bytes = if stderr_present {
            fs::metadata(&record.stderr_path)
                .map(|metadata| metadata.len())
                .unwrap_or(0)
        } else {
            0
        };
        stream_init_ready = record.status == "streams_initialized_execution_disabled"
            && record.stdout_created
            && record.stderr_created
            && stdout_present
            && stderr_present
            && !record.process_spawn_enabled
            && !record.writes_allowed
            && !record.execution_enabled;

        if !stream_init_ready {
            reasons.push("process stream initialization is not in a disabled ready state".to_string());
        }
    }

    if !stdout_present {
        reasons.push("stdout artifact is missing".to_string());
    }
    if !stderr_present {
        reasons.push("stderr artifact is missing".to_string());
    }
    if stdout_size_bytes != 0 || stderr_size_bytes != 0 {
        reasons.push("stdout or stderr artifact contains unexpected output".to_string());
    }

    let summarized = exit_summary_found
        && exit_summary_ready
        && preflight_found
        && lifecycle_found
        && stream_init_found
        && stream_init_ready
        && stdout_size_bytes == 0
        && stderr_size_bytes == 0;
    let status = if !exit_summary_found {
        "blocked_missing_exit_summary"
    } else if !exit_summary_ready {
        "blocked_exit_summary_not_no_process"
    } else if !preflight_found || !lifecycle_found || !stream_init_found {
        "blocked_missing_output_evidence"
    } else if !stdout_present || !stderr_present {
        "blocked_missing_output_artifact"
    } else if stdout_size_bytes != 0 || stderr_size_bytes != 0 {
        "blocked_unexpected_output_present"
    } else {
        "output_tail_summary_recorded_empty_artifacts"
    }
    .to_string();

    if summarized {
        reasons.push(
            "empty stdout/stderr tail summary recorded without live tailing or stream reading"
                .to_string(),
        );
    }

    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let summary = ProcessOutputTailSummaryRecord {
        id: id.clone(),
        process_supervisor_exit_summary_id: request.process_supervisor_exit_summary_id,
        process_supervisor_preflight_id,
        process_lifecycle_id,
        process_stream_init_id,
        task_run_id,
        runtime,
        status: status.clone(),
        exit_summary_found,
        preflight_found,
        lifecycle_found,
        stream_init_found,
        stdout_path,
        stderr_path,
        stdout_present,
        stderr_present,
        stdout_size_bytes,
        stderr_size_bytes,
        stdout_tail_lines: Vec::new(),
        stderr_tail_lines: Vec::new(),
        stdout_line_count: 0,
        stderr_line_count: 0,
        tail_line_limit: 40,
        output_preview_enabled: summarized,
        live_tail_enabled: false,
        stream_reader_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Only replace empty artifact summaries with live output tailing after a stream reader and bounded tail policy are implemented.".to_string(),
    };

    let json = serde_json::to_string_pretty(&summary)
        .map_err(|error| format!("failed to serialize process output tail summary: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write process output tail summary {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "process_output_tail_summary_stub_created",
            "id": id,
            "process_supervisor_exit_summary_id": summary.process_supervisor_exit_summary_id,
            "process_supervisor_preflight_id": summary.process_supervisor_preflight_id,
            "process_lifecycle_id": summary.process_lifecycle_id,
            "process_stream_init_id": summary.process_stream_init_id,
            "task_run_id": summary.task_run_id,
            "runtime": summary.runtime,
            "status": summary.status,
            "summarized": summarized,
            "stdout_size_bytes": summary.stdout_size_bytes,
            "stderr_size_bytes": summary.stderr_size_bytes,
            "output_preview_enabled": summary.output_preview_enabled,
            "live_tail_enabled": false,
            "stream_reader_enabled": false,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(ProcessOutputTailSummaryResult {
        accepted: false,
        summarized,
        live_tail_enabled: false,
        stream_reader_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        summary,
    })
}

