#[tauri::command]
pub fn create_run_transcript_bundle_stub(
    request: RunTranscriptBundleRequest,
) -> Result<RunTranscriptBundleResult, String> {
    let timestamp = now_ms()?;
    let id = format!("run-transcript-bundle-{}-{}", timestamp, std::process::id());
    let dir = run_transcript_bundles_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create run-transcript-bundles directory {}: {error}",
            dir.display()
        )
    })?;

    let output_tail =
        read_process_output_tail_summary_record(&request.process_output_tail_summary_id)?;
    let output_tail_found = output_tail.is_some();
    let mut reasons = Vec::new();
    if !output_tail_found {
        reasons.push("process output tail summary record missing".to_string());
    }

    let (
        process_supervisor_exit_summary_id,
        process_supervisor_preflight_id,
        process_lifecycle_id,
        process_stream_init_id,
        task_run_id,
        runtime,
        stdout_path,
        stderr_path,
        stdout_size_bytes,
        stderr_size_bytes,
        output_tail_ready,
    ) = match output_tail.as_ref() {
        Some(record) => (
            record.process_supervisor_exit_summary_id.clone(),
            record.process_supervisor_preflight_id.clone(),
            record.process_lifecycle_id.clone(),
            record.process_stream_init_id.clone(),
            record.task_run_id.clone(),
            record.runtime.clone(),
            record.stdout_path.clone(),
            record.stderr_path.clone(),
            record.stdout_size_bytes,
            record.stderr_size_bytes,
            record.status == "output_tail_summary_recorded_empty_artifacts"
                && record.output_preview_enabled
                && !record.live_tail_enabled
                && !record.stream_reader_enabled
                && !record.process_spawn_enabled
                && !record.writes_allowed
                && !record.execution_enabled,
        ),
        None => (
            String::new(),
            String::new(),
            String::new(),
            String::new(),
            String::new(),
            String::new(),
            String::new(),
            String::new(),
            0,
            0,
            false,
        ),
    };

    if let Some(record) = output_tail.as_ref() {
        if record.status != "output_tail_summary_recorded_empty_artifacts" {
            reasons.push(format!("process output tail summary status is {}", record.status));
        }
        if record.live_tail_enabled
            || record.stream_reader_enabled
            || record.process_spawn_enabled
            || record.writes_allowed
            || record.execution_enabled
        {
            reasons.push(
                "process output tail summary unexpectedly enables live tailing or execution"
                    .to_string(),
            );
        }
    }

    let exit_summary = if output_tail_found {
        read_process_supervisor_exit_summary_record(&process_supervisor_exit_summary_id)?
    } else {
        None
    };
    let exit_summary_found = exit_summary.is_some();
    if output_tail_found && !exit_summary_found {
        reasons.push("linked process supervisor exit summary record missing".to_string());
    }

    let preflight = if output_tail_found {
        read_process_supervisor_preflight_record(&process_supervisor_preflight_id)?
    } else {
        None
    };
    let preflight_found = preflight.is_some();
    if output_tail_found && !preflight_found {
        reasons.push("linked process supervisor preflight record missing".to_string());
    }

    let lifecycle = if output_tail_found {
        read_process_lifecycle_record(&process_lifecycle_id)?
    } else {
        None
    };
    let lifecycle_found = lifecycle.is_some();
    if output_tail_found && !lifecycle_found {
        reasons.push("linked process lifecycle record missing".to_string());
    }

    let process_command_plan_id = lifecycle
        .as_ref()
        .map(|record| record.process_command_plan_id.clone())
        .unwrap_or_default();
    let process_plan = if lifecycle_found {
        read_process_command_plan_record(&process_command_plan_id)?
    } else {
        None
    };
    let process_command_plan_found = process_plan.is_some();
    if lifecycle_found && !process_command_plan_found {
        reasons.push("linked process command plan record missing".to_string());
    }

    let stream_init = if output_tail_found {
        read_process_stream_init_record(&process_stream_init_id)?
    } else {
        None
    };
    let stream_init_found = stream_init.is_some();
    if output_tail_found && !stream_init_found {
        reasons.push("linked process stream initialization record missing".to_string());
    }

    let task_run = if output_tail_found {
        read_task_run_record(&task_run_id)?
    } else {
        None
    };
    let task_run_found = task_run.is_some();
    if output_tail_found && !task_run_found {
        reasons.push("linked task run record missing".to_string());
    }

    let artifact_preview = if task_run_found {
        task_run_artifact_preview(task_run_id.clone())?
    } else {
        ArtifactPreview {
            found: false,
            id: task_run_id.clone(),
            record_path: String::new(),
            log_path: String::new(),
            record_json: String::new(),
            log_lines: Vec::new(),
            line_count: 0,
            truncated: false,
            error: Some("task run record was not found".to_string()),
        }
    };
    let artifact_preview_found = artifact_preview.found;

    let mut evidence_ids = Vec::new();
    let mut evidence_statuses = Vec::new();
    let mut evidence_record_paths = Vec::new();
    let mut evidence_log_paths = Vec::new();

    if let Some(record) = task_run.as_ref() {
        evidence_ids.push(record.id.clone());
        evidence_statuses.push(record.status.clone());
        evidence_record_paths.push(record.record_path.clone());
        evidence_log_paths.push(record.log_path.clone());
        if record.execution_enabled {
            reasons.push("linked task run unexpectedly enables execution".to_string());
        }
    }
    if let Some(record) = process_plan.as_ref() {
        evidence_ids.push(record.id.clone());
        evidence_statuses.push(record.status.clone());
        evidence_record_paths.push(record.record_path.clone());
        evidence_log_paths.push(record.log_path.clone());
        if record.process_spawn_enabled || record.writes_allowed || record.execution_enabled {
            reasons.push("linked process command plan unexpectedly enables execution".to_string());
        }
    }
    if let Some(record) = lifecycle.as_ref() {
        evidence_ids.push(record.id.clone());
        evidence_statuses.push(record.status.clone());
        evidence_record_paths.push(record.record_path.clone());
        evidence_log_paths.push(record.log_path.clone());
        if record.process_spawn_enabled || record.writes_allowed || record.execution_enabled {
            reasons.push("linked process lifecycle unexpectedly enables execution".to_string());
        }
    }
    if let Some(record) = stream_init.as_ref() {
        evidence_ids.push(record.id.clone());
        evidence_statuses.push(record.status.clone());
        evidence_record_paths.push(record.record_path.clone());
        evidence_log_paths.push(record.log_path.clone());
        if record.process_spawn_enabled || record.writes_allowed || record.execution_enabled {
            reasons.push("linked process stream initialization unexpectedly enables execution".to_string());
        }
    }
    if let Some(record) = preflight.as_ref() {
        evidence_ids.push(record.id.clone());
        evidence_statuses.push(record.status.clone());
        evidence_record_paths.push(record.record_path.clone());
        evidence_log_paths.push(record.log_path.clone());
        if record.supervisor_enabled
            || record.signal_enabled
            || record.retry_spawn_enabled
            || record.process_spawn_enabled
            || record.writes_allowed
            || record.execution_enabled
        {
            reasons.push("linked process supervisor preflight unexpectedly enables execution".to_string());
        }
    }
    if let Some(record) = exit_summary.as_ref() {
        evidence_ids.push(record.id.clone());
        evidence_statuses.push(record.status.clone());
        evidence_record_paths.push(record.record_path.clone());
        evidence_log_paths.push(record.log_path.clone());
        if record.process_spawn_enabled || record.writes_allowed || record.execution_enabled {
            reasons.push("linked process supervisor exit summary unexpectedly enables execution".to_string());
        }
    }
    if let Some(record) = output_tail.as_ref() {
        evidence_ids.push(record.id.clone());
        evidence_statuses.push(record.status.clone());
        evidence_record_paths.push(record.record_path.clone());
        evidence_log_paths.push(record.log_path.clone());
    }

    let all_required_found = output_tail_found
        && exit_summary_found
        && preflight_found
        && lifecycle_found
        && stream_init_found
        && process_command_plan_found
        && task_run_found
        && artifact_preview_found;
    let bundled = all_required_found && output_tail_ready && reasons.iter().all(|reason| {
        !reason.contains("unexpectedly enables") && !reason.contains("missing")
    });
    let status = if !output_tail_found {
        "blocked_missing_output_tail_summary"
    } else if !all_required_found {
        "blocked_missing_transcript_evidence"
    } else if !output_tail_ready {
        "blocked_output_tail_not_ready"
    } else if reasons.iter().any(|reason| reason.contains("unexpectedly enables")) {
        "blocked_transcript_execution_enabled"
    } else {
        "transcript_bundle_recorded_execution_disabled"
    }
    .to_string();

    if bundled {
        reasons.push("transcript bundle recorded without export, process spawn, writes, or execution".to_string());
    }

    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let bundle = RunTranscriptBundleRecord {
        id: id.clone(),
        process_output_tail_summary_id: request.process_output_tail_summary_id,
        process_supervisor_exit_summary_id,
        process_supervisor_preflight_id,
        process_lifecycle_id,
        process_stream_init_id,
        process_command_plan_id,
        task_run_id,
        runtime,
        status: status.clone(),
        output_tail_found,
        exit_summary_found,
        preflight_found,
        lifecycle_found,
        stream_init_found,
        process_command_plan_found,
        task_run_found,
        artifact_preview_found,
        evidence_ids,
        evidence_statuses,
        evidence_record_paths,
        evidence_log_paths,
        stdout_path,
        stderr_path,
        stdout_size_bytes,
        stderr_size_bytes,
        bundle_export_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Only enable transcript export after the bundle format, retention policy, and user-controlled destination are implemented.".to_string(),
    };

    let json = serde_json::to_string_pretty(&bundle)
        .map_err(|error| format!("failed to serialize run transcript bundle: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write run transcript bundle {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "run_transcript_bundle_stub_created",
            "id": id,
            "task_run_id": bundle.task_run_id,
            "process_output_tail_summary_id": bundle.process_output_tail_summary_id,
            "evidence_count": bundle.evidence_ids.len(),
            "status": bundle.status,
            "bundled": bundled,
            "bundle_export_enabled": false,
            "process_spawn_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(RunTranscriptBundleResult {
        accepted: false,
        bundled,
        bundle_export_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        bundle,
    })
}

#[tauri::command]
pub fn list_run_transcript_bundles() -> Result<Vec<RunTranscriptBundleRecord>, String> {
    let dir = run_transcript_bundles_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read run-transcript-bundles directory {}: {error}",
            dir.display()
        )
    })? {
        let entry =
            entry.map_err(|error| format!("failed to read run transcript bundle entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<RunTranscriptBundleRecord>(&content) {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

#[tauri::command]
pub fn create_transcript_export_policy_stub(
    request: TranscriptExportPolicyRequest,
) -> Result<TranscriptExportPolicyResult, String> {
    let timestamp = now_ms()?;
    let requested_destination = request.requested_destination.to_ascii_lowercase();
    let id = format!(
        "transcript-export-policy-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug(&requested_destination)
    );
    let dir = transcript_export_policies_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create transcript-export-policies directory {}: {error}",
            dir.display()
        )
    })?;

    let bundle = read_run_transcript_bundle_record(&request.run_transcript_bundle_id)?;
    let run_transcript_bundle_found = bundle.is_some();
    let mut reasons = Vec::new();
    if !run_transcript_bundle_found {
        reasons.push("run transcript bundle record missing".to_string());
    }

    let supported_destination = matches!(
        requested_destination.as_str(),
        "local_file" | "clipboard" | "share_sheet"
    );
    if !supported_destination {
        reasons.push(format!(
            "requested destination {requested_destination} is not supported"
        ));
    }

    let (task_run_id, runtime, bundle_status, evidence_count, bundle_ready) =
        match bundle.as_ref() {
            Some(record) => (
                record.task_run_id.clone(),
                record.runtime.clone(),
                record.status.clone(),
                record.evidence_ids.len(),
                record.status == "transcript_bundle_recorded_execution_disabled"
                    && !record.bundle_export_enabled
                    && !record.process_spawn_enabled
                    && !record.writes_allowed
                    && !record.execution_enabled,
            ),
            None => (
                String::new(),
                String::new(),
                "missing".to_string(),
                0,
                false,
            ),
        };

    if let Some(record) = bundle.as_ref() {
        if record.status != "transcript_bundle_recorded_execution_disabled" {
            reasons.push(format!("run transcript bundle status is {}", record.status));
        }
        if record.bundle_export_enabled
            || record.process_spawn_enabled
            || record.writes_allowed
            || record.execution_enabled
        {
            reasons.push("run transcript bundle unexpectedly enables export or execution".to_string());
        }
    }

    let destination_kind = if supported_destination {
        requested_destination.clone()
    } else {
        "unsupported".to_string()
    };
    let planned_destination_label = match destination_kind.as_str() {
        "local_file" => "$XDG_STATE_HOME/gravity-omega-native/exports/transcripts/".to_string(),
        "clipboard" => "desktop clipboard".to_string(),
        "share_sheet" => "desktop share sheet".to_string(),
        _ => "unsupported destination".to_string(),
    };

    let policy_recorded = run_transcript_bundle_found && bundle_ready && supported_destination;
    let status = if !run_transcript_bundle_found {
        "blocked_missing_transcript_bundle"
    } else if !supported_destination {
        "blocked_unsupported_export_destination"
    } else if !bundle_ready {
        "blocked_transcript_bundle_not_ready"
    } else {
        "transcript_export_policy_recorded_export_disabled"
    }
    .to_string();

    if policy_recorded {
        reasons.push("export policy recorded with all destination write/share gates disabled".to_string());
    }

    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let policy = TranscriptExportPolicyRecord {
        id: id.clone(),
        run_transcript_bundle_id: request.run_transcript_bundle_id,
        task_run_id,
        runtime,
        requested_destination,
        destination_kind,
        planned_destination_label,
        bundle_status,
        status: status.clone(),
        run_transcript_bundle_found,
        supported_destination,
        evidence_count,
        consent_required: true,
        export_enabled: false,
        bundle_export_enabled: false,
        clipboard_write_enabled: false,
        share_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Only enable export after destination-specific consent, retention, and redaction policies are implemented.".to_string(),
    };

    let json = serde_json::to_string_pretty(&policy)
        .map_err(|error| format!("failed to serialize transcript export policy: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write transcript export policy {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "transcript_export_policy_stub_created",
            "id": id,
            "run_transcript_bundle_id": policy.run_transcript_bundle_id,
            "task_run_id": policy.task_run_id,
            "requested_destination": policy.requested_destination,
            "status": policy.status,
            "policy_recorded": policy_recorded,
            "export_enabled": false,
            "bundle_export_enabled": false,
            "clipboard_write_enabled": false,
            "share_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(TranscriptExportPolicyResult {
        accepted: false,
        policy_recorded,
        export_enabled: false,
        bundle_export_enabled: false,
        clipboard_write_enabled: false,
        share_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        policy,
    })
}

