#[tauri::command]
pub fn create_transcript_protection_policy_stub(
    request: TranscriptProtectionPolicyRequest,
) -> Result<TranscriptProtectionPolicyResult, String> {
    let timestamp = now_ms()?;
    let requested_redaction_profile = request.requested_redaction_profile.to_ascii_lowercase();
    let requested_retention_tier = request.requested_retention_tier.to_ascii_lowercase();
    let id = format!(
        "transcript-protection-policy-{}-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug(&requested_redaction_profile),
        slug(&requested_retention_tier)
    );
    let dir = transcript_protection_policies_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create transcript-protection-policies directory {}: {error}",
            dir.display()
        )
    })?;

    let export_policy =
        read_transcript_export_policy_record(&request.transcript_export_policy_id)?;
    let transcript_export_policy_found = export_policy.is_some();
    let mut reasons = Vec::new();
    if !transcript_export_policy_found {
        reasons.push("transcript export policy record missing".to_string());
    }

    let supported_redaction_profile = matches!(
        requested_redaction_profile.as_str(),
        "secrets_and_paths" | "secrets_only" | "none_required"
    );
    if !supported_redaction_profile {
        reasons.push(format!(
            "requested redaction profile {requested_redaction_profile} is not supported"
        ));
    }

    let supported_retention_tier = matches!(
        requested_retention_tier.as_str(),
        "local_7_days" | "local_30_days" | "manual_review"
    );
    if !supported_retention_tier {
        reasons.push(format!(
            "requested retention tier {requested_retention_tier} is not supported"
        ));
    }

    let (
        run_transcript_bundle_id,
        task_run_id,
        runtime,
        destination_kind,
        export_policy_status,
        evidence_count,
        export_policy_ready,
    ) = match export_policy.as_ref() {
        Some(record) => (
            record.run_transcript_bundle_id.clone(),
            record.task_run_id.clone(),
            record.runtime.clone(),
            record.destination_kind.clone(),
            record.status.clone(),
            record.evidence_count,
            record.status == "transcript_export_policy_recorded_export_disabled"
                && record.consent_required
                && !record.export_enabled
                && !record.bundle_export_enabled
                && !record.clipboard_write_enabled
                && !record.share_enabled
                && !record.process_spawn_enabled
                && !record.writes_allowed
                && !record.execution_enabled,
        ),
        None => (
            String::new(),
            String::new(),
            String::new(),
            String::new(),
            "missing".to_string(),
            0,
            false,
        ),
    };

    if let Some(record) = export_policy.as_ref() {
        if record.status != "transcript_export_policy_recorded_export_disabled" {
            reasons.push(format!("transcript export policy status is {}", record.status));
        }
        if !record.consent_required {
            reasons.push("transcript export policy does not require consent".to_string());
        }
        if record.export_enabled
            || record.bundle_export_enabled
            || record.clipboard_write_enabled
            || record.share_enabled
            || record.process_spawn_enabled
            || record.writes_allowed
            || record.execution_enabled
        {
            reasons.push("transcript export policy unexpectedly enables export, writes, share, or execution".to_string());
        }
    }

    let redaction_profile = if supported_redaction_profile {
        requested_redaction_profile.clone()
    } else {
        "unsupported".to_string()
    };
    let retention_tier = if supported_retention_tier {
        requested_retention_tier.clone()
    } else {
        "unsupported".to_string()
    };
    let retention_days = match retention_tier.as_str() {
        "local_7_days" => 7,
        "local_30_days" => 30,
        "manual_review" => 0,
        _ => 0,
    };

    let policy_recorded = transcript_export_policy_found
        && export_policy_ready
        && supported_redaction_profile
        && supported_retention_tier;
    let status = if !transcript_export_policy_found {
        "blocked_missing_transcript_export_policy"
    } else if !supported_redaction_profile {
        "blocked_unsupported_redaction_profile"
    } else if !supported_retention_tier {
        "blocked_unsupported_retention_tier"
    } else if !export_policy_ready {
        "blocked_transcript_export_policy_not_ready"
    } else {
        "transcript_protection_policy_recorded_export_disabled"
    }
    .to_string();

    if policy_recorded {
        reasons.push("protection policy recorded without applying redaction, retention deletion, export, or execution".to_string());
    }

    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let policy = TranscriptProtectionPolicyRecord {
        id: id.clone(),
        transcript_export_policy_id: request.transcript_export_policy_id,
        run_transcript_bundle_id,
        task_run_id,
        runtime,
        destination_kind,
        requested_redaction_profile,
        redaction_profile,
        requested_retention_tier,
        retention_tier,
        retention_days,
        export_policy_status,
        status: status.clone(),
        transcript_export_policy_found,
        export_policy_ready,
        supported_redaction_profile,
        supported_retention_tier,
        evidence_count,
        consent_required: true,
        redaction_required: true,
        retention_required: true,
        redaction_applied: false,
        retention_enforced: false,
        deletion_scheduled: false,
        export_enabled: false,
        bundle_export_enabled: false,
        clipboard_write_enabled: false,
        share_enabled: false,
        process_spawn_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        next_step: "Only apply redaction or retention after content scanning, consent, dry-run review, and rollback policy are implemented.".to_string(),
    };

    let json = serde_json::to_string_pretty(&policy)
        .map_err(|error| format!("failed to serialize transcript protection policy: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write transcript protection policy {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "transcript_protection_policy_stub_created",
            "id": id,
            "transcript_export_policy_id": policy.transcript_export_policy_id,
            "run_transcript_bundle_id": policy.run_transcript_bundle_id,
            "task_run_id": policy.task_run_id,
            "redaction_profile": policy.redaction_profile,
            "retention_tier": policy.retention_tier,
            "retention_days": policy.retention_days,
            "status": policy.status,
            "policy_recorded": policy_recorded,
            "redaction_applied": false,
            "retention_enforced": false,
            "deletion_scheduled": false,
            "export_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(TranscriptProtectionPolicyResult {
        accepted: false,
        policy_recorded,
        redaction_applied: false,
        retention_enforced: false,
        deletion_scheduled: false,
        export_enabled: false,
        bundle_export_enabled: false,
        clipboard_write_enabled: false,
        share_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        policy,
    })
}

#[tauri::command]
pub fn list_transcript_protection_policies(
) -> Result<Vec<TranscriptProtectionPolicyRecord>, String> {
    let dir = transcript_protection_policies_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read transcript-protection-policies directory {}: {error}",
            dir.display()
        )
    })? {
        let entry = entry
            .map_err(|error| format!("failed to read transcript protection policy entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<TranscriptProtectionPolicyRecord>(&content) {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

#[tauri::command]
pub fn create_local_mcp_health_record_stub(
    request: LocalMcpHealthRequest,
) -> Result<LocalMcpHealthResult, String> {
    let timestamp = now_ms()?;
    let requested = request.subsystem.to_ascii_lowercase();
    let subsystem = match requested.as_str() {
        "brain" | "omega-brain" | "omega_brain" => "omega_brain".to_string(),
        "sswp" => "sswp".to_string(),
        "steno" | "omega-stenographer" | "omega_stenographer" => {
            "omega_stenographer".to_string()
        }
        _ => requested.clone(),
    };
    let dir = local_mcp_health_dir()?;
    fs::create_dir_all(&dir).map_err(|error| {
        format!(
            "failed to create local-mcp-health directory {}: {error}",
            dir.display()
        )
    })?;

    let requested_preflight_id = request
        .local_mcp_health_preflight_id
        .unwrap_or_default()
        .trim()
        .chars()
        .take(180)
        .collect::<String>();
    let preflight = if requested_preflight_id.is_empty() {
        latest_local_mcp_health_preflight_record()?
    } else {
        read_local_mcp_health_preflight_record(&requested_preflight_id)?
    };
    let preflight_source = preflight.as_ref();
    let preflight_found = preflight_source.is_some();
    let local_mcp_health_preflight_id = preflight_source
        .map(|record| record.id.clone())
        .unwrap_or_else(|| {
            if requested_preflight_id.is_empty() {
                "unresolved".to_string()
            } else {
                requested_preflight_id.clone()
            }
        });
    let preflight_ready = preflight_source
        .and_then(|record| record.lanes.iter().find(|lane| lane.subsystem == subsystem))
        .map(|lane| lane.health_preflight_recorded && !lane.live_probe_enabled)
        .unwrap_or(false);
    let supported_subsystem = matches!(
        subsystem.as_str(),
        "omega_brain" | "sswp" | "omega_stenographer"
    );
    let mut reasons = Vec::new();
    if !supported_subsystem {
        reasons.push(format!(
            "local MCP subsystem {subsystem} is not first-class in this scaffold"
        ));
    } else if !preflight_found {
        reasons.push(
            "local MCP health record requires an existing local MCP health preflight".to_string(),
        );
    } else if !preflight_ready {
        reasons.push(
            "local MCP health preflight exists but does not contain a ready lane for this subsystem"
                .to_string(),
        );
    }

    let (
        display_name,
        current_surface,
        health_source,
        expected_config_surfaces,
        expected_command_ids,
        capability_summary,
        recovery_hint,
    ) = match subsystem.as_str() {
        "omega_brain" => (
            "Omega Brain".to_string(),
            "User-owned Omega Brain memory MCP lane shared by Codex, Hermes, and Gravity Omega"
                .to_string(),
            "planned local MCP registry health check gated by health preflight; live probe disabled"
                .to_string(),
            vec![
                "~/.omega-brain/omega_brain.db".to_string(),
                "~/.hermes/config.yaml".to_string(),
                "~/.claude.json or ~/.claude/settings.json".to_string(),
                "~/.codex/config.toml".to_string(),
            ],
            vec![
                "omega_brain_status".to_string(),
                "omega_brain_search".to_string(),
                "omega_brain_cite".to_string(),
                "omega_brain_memory_policy".to_string(),
            ],
            "Status, cited memory retrieval, retention policy, and recovery state."
                .to_string(),
            "Verify DB availability, citation envelope, and retention policy separately before enabling memory calls.".to_string(),
        ),
        "sswp" => (
            "SSWP".to_string(),
            "User-created local SSWP MCP wired across Codex, Hermes, and Claude tooling".to_string(),
            "planned local MCP registry health check gated by health preflight; live probe disabled".to_string(),
            vec![
                "~/.hermes/config.yaml".to_string(),
                "~/.claude.json or ~/.claude/settings.json".to_string(),
                "~/.codex/config.toml".to_string(),
                "local SSWP MCP package".to_string(),
            ],
            vec![
                "sswp_status".to_string(),
                "sswp_capabilities".to_string(),
                "sswp_call".to_string(),
            ],
            "Status, capability discovery, gated SSWP calls, and audited recovery state.".to_string(),
            "Verify config registration and process startup health separately before enabling calls.".to_string(),
        ),
        "omega_stenographer" => (
            "Omega Stenographer".to_string(),
            "User-created omega-stenographer MCP and transcript/capture workflows".to_string(),
            "planned local MCP registry health check gated by health preflight; live probe disabled".to_string(),
            vec![
                "~/.hermes/config.yaml".to_string(),
                "~/.claude.json or ~/.claude/settings.json".to_string(),
                "~/.codex/config.toml".to_string(),
                "local omega-stenographer MCP package".to_string(),
            ],
            vec![
                "steno_status".to_string(),
                "steno_capture".to_string(),
                "steno_search".to_string(),
                "steno_export_policy".to_string(),
            ],
            "Capture consent, transcript search, export policy, and cited evidence workflows.".to_string(),
            "Verify capture consent, transcript retention, and redaction policy before enabling live capture.".to_string(),
        ),
        _ => (
            "Unsupported local MCP".to_string(),
            "unknown".to_string(),
            "none".to_string(),
            Vec::new(),
            Vec::new(),
            "unsupported".to_string(),
            "Add this MCP to the feature and command contracts before recording health.".to_string(),
        ),
    };

    let health_recorded = supported_subsystem && preflight_ready;
    let status = if !supported_subsystem {
        "blocked_unsupported_local_mcp"
    } else if !preflight_found {
        "blocked_missing_local_mcp_health_preflight"
    } else if !preflight_ready {
        "blocked_local_mcp_health_preflight_not_ready"
    } else {
        reasons.push("local MCP health record created from preflight evidence without probing or calling the subsystem".to_string());
        "local_mcp_health_recorded_probe_disabled"
    }
    .to_string();
    let id = format!(
        "local-mcp-health-{}-{}-{}-{}-{}",
        timestamp,
        std::process::id(),
        slug(&subsystem),
        slug_limit(&local_mcp_health_preflight_id, 32),
        slug_limit(&status, 32)
    );

    let record_path = dir.join(format!("{id}.json"));
    let log_path = dir.join(format!("{id}.jsonl"));
    let record_path_display = record_path.display().to_string();
    let log_path_display = log_path.display().to_string();
    let record = LocalMcpHealthRecord {
        id: id.clone(),
        local_mcp_health_preflight_id,
        subsystem,
        display_name,
        current_surface,
        health_source,
        expected_config_surfaces,
        expected_command_ids,
        capability_summary,
        status: status.clone(),
        supported_subsystem,
        preflight_found,
        preflight_ready,
        health_preflight_required: true,
        configured_expected: health_recorded,
        capability_manifest_required: true,
        approval_required_for_calls: true,
        audit_required: true,
        live_probe_enabled: false,
        live_call_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        created_at_ms: timestamp,
        updated_at_ms: timestamp,
        record_path: record_path_display.clone(),
        log_path: log_path_display.clone(),
        reasons,
        recovery_hint,
        next_step: "Enable live health probes only after registry lookup, process health checks, and failure-mode reporting are implemented.".to_string(),
    };

    let json = serde_json::to_string_pretty(&record)
        .map_err(|error| format!("failed to serialize local MCP health record: {error}"))?;
    fs::write(&record_path, json).map_err(|error| {
        format!(
            "failed to write local MCP health record {}: {error}",
            record_path.display()
        )
    })?;
    write_jsonl_event(
        &log_path,
        serde_json::json!({
            "event": "local_mcp_health_record_stub_created",
            "id": id,
            "local_mcp_health_preflight_id": record.local_mcp_health_preflight_id,
            "subsystem": record.subsystem,
            "status": record.status,
            "health_recorded": health_recorded,
            "preflight_found": record.preflight_found,
            "preflight_ready": record.preflight_ready,
            "live_probe_enabled": false,
            "live_call_enabled": false,
            "writes_allowed": false,
            "execution_enabled": false,
            "created_at_ms": timestamp
        }),
    )?;

    Ok(LocalMcpHealthResult {
        accepted: false,
        health_recorded,
        live_probe_enabled: false,
        live_call_enabled: false,
        writes_allowed: false,
        execution_enabled: false,
        record,
    })
}

#[tauri::command]
pub fn list_local_mcp_health_records() -> Result<Vec<LocalMcpHealthRecord>, String> {
    let dir = local_mcp_health_dir()?;
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in fs::read_dir(&dir).map_err(|error| {
        format!(
            "failed to read local-mcp-health directory {}: {error}",
            dir.display()
        )
    })? {
        let entry =
            entry.map_err(|error| format!("failed to read local MCP health entry: {error}"))?;
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }

        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(_) => continue,
        };
        if let Ok(record) = serde_json::from_str::<LocalMcpHealthRecord>(&content) {
            records.push(record);
        }
    }

    records.sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    records.truncate(20);
    Ok(records)
}

