    #[test]
    fn command_surface_collapse_board_maps_kimi_findings_to_twenty_families() {
        let _test_env_guard = test_env_lock();
        let board = command_surface_collapse_board();

        assert_eq!(board.status, "command_surface_collapse_board_read_only");
        assert_eq!(board.current_rust_command_file_lines, 124_144);
        assert_eq!(board.current_rust_stub_command_count, 304);
        assert_eq!(board.target_command_family_count, 20);
        assert_eq!(board.family_count, 20);
        assert_eq!(board.product_parity_feature_count, 29);
        assert_eq!(board.electron_ipc_handler_count, 92);
        assert_eq!(board.flask_backend_route_count, 60);
        assert_eq!(board.registered_module_count, 52);
        assert_eq!(board.tool_count, 24);
        assert_eq!(board.sidebar_panel_count, 12);
        assert_eq!(board.retired_stub_target_count, 284);
        assert!(board.current_contract_command_count >= 238);
        assert!(board.high_risk_family_count >= 10);
        assert!(!board.file_write_enabled);
        assert!(!board.patch_apply_enabled);
        assert!(!board.terminal_enabled);
        assert!(!board.process_spawn_enabled);
        assert!(!board.desktop_control_enabled);
        assert!(!board.browser_automation_enabled);
        assert!(!board.media_playback_enabled);
        assert!(!board.sidecar_launch_enabled);
        assert!(!board.config_read_enabled);
        assert!(!board.live_mcp_call_enabled);
        assert!(!board.socket_connect_enabled);
        assert!(!board.capture_enabled);
        assert!(!board.export_enabled);
        assert!(!board.memory_write_enabled);
        assert!(!board.writes_allowed);
        assert!(!board.execution_enabled);
        assert!(board.families.iter().any(|family| {
            family.id == "workspace-edit"
                && family.target_command_shape.contains("workspace_edit")
                && !family.file_write_enabled
                && !family.execution_enabled
        }));
        assert!(board.families.iter().any(|family| {
            family.id == "terminal-process"
                && family.parity_source.contains("PTY")
                && !family.terminal_enabled
                && !family.process_spawn_enabled
        }));
        assert!(board.families.iter().any(|family| {
            family.id == "mcp"
                && family.target_command_shape.contains("mcp")
                && !family.live_mcp_call_enabled
        }));
        assert!(board.families.iter().any(|family| {
            family.id == "python-modules"
                && family.target_command_shape.contains("module_sidecar")
                && !family.sidecar_launch_enabled
        }));
        assert!(board.families.windows(2).all(|pair| {
            pair[0].release_priority < pair[1].release_priority
        }));
    }

