    #[test]
    fn toolbar_action_readiness_covers_every_non_live_toolbar_command() {
        let _test_env_guard = test_env_lock();
        let commands = command_registry().expect("toolbar registry loads");
        let non_live_commands: Vec<&ToolbarCommand> = commands
            .iter()
            .filter(|command| command.state != "live")
            .collect();

        assert_eq!(non_live_commands.len(), 12);

        for command in non_live_commands {
            let panel = toolbar_action_readiness(command.id.clone())
                .expect("toolbar action readiness resolves");
            assert!(panel.found);
            assert!(!panel.accepted);
            assert_eq!(panel.status, "toolbar_action_blocked_readiness");
            assert_eq!(panel.command_id, command.id);
            assert_eq!(panel.state.as_deref(), Some(command.state.as_str()));
            assert_eq!(
                panel.target_command.as_deref(),
                command.target_command.as_deref()
            );
            assert!(panel.readiness_count >= 6);
            assert!(panel.blocked_count >= 1);
            assert!(panel.read_only);
            assert!(!panel.action_enabled);
            assert!(!panel.file_read_enabled);
            assert!(!panel.file_write_enabled);
            assert!(!panel.patch_apply_enabled);
            assert!(!panel.terminal_enabled);
            assert!(!panel.terminal_write_enabled);
            assert!(!panel.process_spawn_enabled);
            assert!(!panel.desktop_control_enabled);
            assert!(!panel.config_read_enabled);
            assert!(!panel.live_mcp_call_enabled);
            assert!(!panel.socket_connect_enabled);
            assert!(!panel.capture_enabled);
            assert!(!panel.export_enabled);
            assert!(!panel.memory_write_enabled);
            assert!(!panel.writes_allowed);
            assert!(!panel.execution_enabled);
            assert!(panel
                .readiness
                .iter()
                .any(|item| item.item_id == "evidence-panel-live" && item.ready));
        }

        let missing =
            toolbar_action_readiness("not.in.registry".to_string()).expect("missing resolves");
        assert!(!missing.found);
        assert_eq!(missing.status, "toolbar_action_not_found");
        assert!(!missing.execution_enabled);

        for command_id in [
            "file.new",
            "window.new",
            "file.open",
            "workspace.open_folder",
            "app.exit",
            "edit.undo",
            "edit.redo",
            "window.fullscreen",
            "security.refresh",
            "agent.codex_review",
            "agent.hermes_companion",
            "agent.joint_ci",
            "mcp.sswp_call",
            "steno.capture",
        ] {
            let panel = toolbar_action_readiness(command_id.to_string())
                .expect("safe live intent readiness resolves");
            assert!(panel.found);
            assert_eq!(panel.status, "toolbar_action_live_readiness");
            assert_eq!(panel.state.as_deref(), Some("live"));
            assert!(panel.read_only);
            assert!(!panel.action_enabled);
            assert!(!panel.writes_allowed);
            assert!(!panel.execution_enabled);
        }
    }

